/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"#1":{"묶음":[{"머리":"보관의 기능","줄":[{"t":"보관은 시간적 효용을 창출한다. 생산과 소비의 시간 간격을 메운다.","src":"기출 2021-1, 2022-2, 2023-12"},{"t":"장소적 효용은 운송이 창출한다. 보관의 기능이 아니다.","src":"기출 2021-1, 2023-1, 2025-4"},{"t":"수송과 배송을 연계한다.","src":"기출 2021-1, 2022-2, 2023-1, 2026-1"},{"t":"생산과 판매를 조정하고 완충한다(생산 평준화·안정화 지원).","src":"기출 2021-1, 2022-2, 2026-1"},{"t":"재고를 보유해 고객 수요에 대응한다. 고객 서비스에 신속히 대응한다.","src":"기출 2021-1, 2022-2, 2023-1, 2025-4"},{"t":"물품의 분류와 혼재, 보존과 관리도 보관 기능에 든다.","src":"기출 2023-1"},{"t":"유통가공·재포장·검품도 보관(창고) 기능에 포함된다.","src":"기출 2026-1, 2024-15"},{"t":"물품의 수급 조정 기능이 있다.","src":"기출 2025-4"},{"t":"보관(Storage): 재화를 물리적으로 보존하고 관리하는 것이다. KS T-0001은 물품을 일정한 장소에서 품질·수량 등을 유지하며 적절한 관리하에 일정 기간 저장·방치하는 것으로 정의한다.","src":"이론"},{"t":"용어 구분: 보관은 제품·반제품을 비교적 단기간 놓아두는 경우, 저장은 원자재·중간재를 비교적 장기간 놓아두는 경우, 창고는 제품의 보관 장소이다.","src":"이론"},{"t":"보관 기능 전체: 물리적 보존·관리, Link와 Link 연결, 고객서비스 접점(주문 신속 대응·결품 방지), 생산·판매 조정과 완충, 수·배송 연결로 운송비 절감, 집산·분류·재포장·검품·검사의 장소적 기능, 수요·공급 조절(수량·시간·가격 안정화), 판매시점 조절, 생산 평준화·안정화 지원, 유통가공으로 부가가치 증대.","src":"이론"},{"t":"판매시점 조절 기능: 마케팅과 연계해 상품의 시장 출시일을 조절한다.","src":"이론"},{"t":"집산·분류·구분·조합·검사의 장소적 기능도 보관 기능에 든다.","src":"기출 2020-1"},{"t":"보관의 필요성(목적): 생산과 판매·수송과 배송의 완충, 재고 유지로 수요·공급의 시간적 조정과 균형, 대량구매·대량보관으로 비용 절감, 계절 요인·시장 변화 같은 불확실한 수요 패턴에 대응.","src":"이론"},{"t":"최근 보관 개념은 저장창고에서 유통창고로, 저장재고는 활성(유동)재고로 바뀌고 있다.","src":"이론"}]},{"머리":"보관의 원칙 전체","줄":[{"t":"위치표시의 원칙: 보관 물품의 장소와 선반 번호를 표시해 입출고·재고 작업 효율을 높인다.","src":"기출 2021-3, 2022-1, 2024-1"},{"t":"회전대응의 원칙: 입출고 빈도가 높은 물품은 출입구 가까이, 낮은 물품은 먼 곳에 둔다.","src":"기출 2021-3, 2022-1, 2023-4, 2025-1"},{"t":"선입선출의 원칙: 먼저 입고한 물품을 먼저 출고한다.","src":"기출 2022-1, 2025-1, 2026-2"},{"t":"중량특성의 원칙: 중량에 따라 보관 위치(높이)를 정한다. 무거운 물품은 하층부에 둔다.","src":"기출 2022-1, 2024-1, 2025-1, 2026-2"},{"t":"동일성·유사성의 원칙: 동일 품종은 같은 장소에, 유사품은 인접 장소에 둔다. 관리 효율이 오른다.","src":"기출 2024-1, 2025-1, 2026-2"},{"t":"통로대면의 원칙: 입출고를 쉽게 하려고 물품을 통로에 접하게 보관한다.","src":"기출 2024-1, 2026-2"},{"t":"네트워크 보관의 원칙: 연대출고가 예상되는 관련 품목을 출하하기 쉽게 모아 계통적으로 보관한다.","src":"기출 2021-3, 2022-1"},{"t":"명료성의 원칙: 보관 물품을 눈으로 쉽게 식별할 수 있게 둔다.","src":"보충(추정)"},{"t":"형상특성의 원칙: 물품의 형상에 맞추어 보관한다.","src":"기출 2021-3 / 보충"},{"t":"보관의 원칙 10가지: 통로대면, 높이 쌓기(고적), 선입선출, 회전대응, 동일성·유사성, 중량특성, 형상특성, 위치표시, 명료성, 네트워크 보관.","src":"이론"},{"t":"높이 쌓기의 원칙(고적의 원칙): 제품을 높게 쌓아 창고의 용적효율·충전효율·보관효율을 높인다. 랙 등 보관설비를 쓴다.","src":"이론"},{"t":"통로대면의 원칙은 창고 레이아웃 설계의 원칙이기도 하다. 작업의 접근성을 강조한다.","src":"이론"},{"t":"선입선출의 원칙이 필요한 품목: 사양변경이 잦은 제품, 제품수명주기(PLC)가 짧은 제품, 보관 중 파손·감모가 생기기 쉬운 물품.","src":"이론"},{"t":"회전대응 보관의 원칙은 ABC 분석에 기초해 품목을 분류한다. 출입구가 같은 창고에서 입출고 빈도가 높은 화물은 출입구 가까이 둔다.","src":"이론"},{"t":"중량특성의 원칙: 제품 중량에 따라 출입구 기준 거리와 높낮이를 정한다. 중량물·대형물은 하부와 출구 쪽에 두어 안전사고와 이동거리를 줄인다. 경량품은 상층부에 둔다.","src":"이론"},{"t":"형상특성의 원칙: 포장 모듈화에 대응하는 표준화 제품은 랙에 보관하고, 표준화되지 않은 제품은 형상에 따라 보관 효율을 고려해 보관한다.","src":"이론"},{"t":"위치표시의 원칙: 랙의 위치에 특정 기호를 써서 표시한다. 입출고 작업이 단순해지고 재고 파악·정리 때 실수가 준다. 명료성의 원칙과 함께 로케이션 관리에 필요한 원칙이다.","src":"이론"}]},{"머리":"보관유형(품목수·수량·회전율)","줄":[{"t":"A-A-A형: 품목수 적음, 수량 많음, 회전율 높음.","src":"기출 2024-2"},{"t":"C-A-A형: 품목수와 수량이 매우 많고 회전율이 높다. 관리가 복잡해 자동화 방식이 적합하다.","src":"기출 2024-2"}]}],"함정":[{"x":"유사성의 원칙: 연대출고가 예상되는 관련 품목을 출하가 용이하도록 모아서 보 관하는 원칙이다.","o":"연대출고가 예상되는 관련 품목을 출하하기 쉽게 모아 보관하는 원칙은 네트워크보관의 원칙이다. 유사성의 원칙은 유사품을 가까운 장소에 모아 보관한다.","src":"기출 2022-1 / 기출 2021-3, 2024-1"},{"x":"네트워크 보관의 원칙: 입출고 빈도에 따라 보관할 물품의 위치를 달리하는 원 칙으로 빈도가 높은 물품은 출입구 가까운 위치에 보관한다.","o":"입출고 빈도에 따라 보관 위치를 달리하는 원칙은 회전대응의 원칙이다.","src":"기출 2024-1 / 기출 2021-3, 2022-1, 2023-4"},{"x":"통로대면의 원칙: 작업의 효율성을 위하여 보관물품의 장소와 선반 번호 위치를 표시하여 보관한다.","o":"통로대면의 원칙: 입출고를 쉽게 하려고 물품을 통로에 접하게 보관한다. 장소·선반번호를 표시하는 것은 위치표시의 원칙이다.","src":"기출 2025-1 / 기출 2022-1, 2024-1, 2026-2"},{"x":"유통가공, 재포장, 검품은 보관의 기능으로 분류되지 않는다.","o":"유통가공·재포장·검품도 창고(보관)의 기능이다.","src":"기출 2026-1 / 기출 2024-15"},{"x":"명료성의 원칙: 용적 효율을 향상시키기 위해 물품을 높게 쌓는다.","o":"명료성의 원칙: 보관 물품을 눈으로 쉽게 식별할 수 있게 보관한다. 높게 쌓아 용적효율을 높인다는 설명은 아니다.","src":"기출 2026-2 / 보충(추정)"},{"x":"제품에 대한 장소적 효용을 창출한다.","o":"보관은 시간적 효용을 창출한다. 장소적 효용은 운송 기능이다.","src":"기출 2021-1"},{"x":"거리적·장소적 효용 창출 기능(보관의 기능으로)","o":"보관의 기능이 아니다. 장소적 효용은 운송이 창출한다.","src":"기출 2023-1"},{"x":"제품의 판매촉진을 위한 장소적 효용 창출 기능(보관의 기능으로)","o":"보관의 기능이 아니다.","src":"기출 2025-4"},{"x":"제품의 거리적, 장소적 효용을 높이는 기능(보관의 기능으로)","o":"거리적·장소적 효용은 운송이 창출한다. 보관은 시간적 효용을 창출한다.","src":"기출 2020-1"},{"x":"형상특성의 원칙: 동일 품목은 동일 장소에, 유사품은 인접 장소에 보관한다.","o":"동일 품목은 동일 장소에, 유사품은 인접 장소에 두는 것은 동일성·유사성의 원칙이다. 형상특성의 원칙은 형상에 따라 보관방법을 달리한다.","src":"기출 2020-2"},{"x":"형상특성의 원칙: 표준화된 물품은 형상에 따라 보관하고 표준화되지 않은 물품은 랙에 보관한다.","o":"표준화된 물품은 랙에 보관하고, 표준화되지 않은 물품은 형상에 따라 보관한다.","src":"이론"}]},"#2":{"묶음":[{"머리":"물류시설법의 정의","줄":[{"t":"물류터미널: 화물의 집화·하역 및 이와 관련된 분류·포장·보관·가공·조립 또는 통관 등에 필요한 기능을 갖춘 시설물이다. 가공·조립 시설은 대통령령 규모 이하여야 한다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조 / 기출 2023-7, 2025-5, 2026-3"},{"t":"복합물류터미널사업: 두 종류 이상의 운송수단 간 연계운송을 할 수 있는 규모 및 시설을 갖춘 물류터미널사업이다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조 / 기출 2023-3, 2024-3, 2025-3"},{"t":"일반물류터미널사업: 물류터미널사업 중 복합물류터미널사업을 제외한 것이다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조"},{"t":"물류창고: 화물의 저장·관리, 집화·배송 및 수급조정 등을 위한 보관시설·보관장소, 또는 이와 관련된 하역·분류·포장·상표부착 등에 필요한 기능을 갖춘 시설이다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조"},{"t":"스마트물류센터: 첨단물류시설·설비·운영시스템을 도입해 저비용·고효율·안전성·친환경성 등이 우수한 물류창고로, 국토교통부장관의 인증을 받은 물류창고이다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조 / 기출 2024-4, 2026-5"},{"t":"물류단지: 도시첨단물류단지와 일반물류단지로 나눈다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조"},{"t":"도시첨단물류단지: 도시 내 물류를 지원하고 물류·유통산업과 관련 산업의 육성·개발을 촉진하려고 도시지역에 지정·개발하는 단지이다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조 / 기출 2024-4"},{"t":"일반물류단지시설에는 물류터미널 및 창고, 대규모점포·공동집배송센터·중소유통공동도매물류센터, 농수산물도매시장·공판장·종합유통센터, 화물자동차운수사업용 차고·화물취급소 등이 든다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조"},{"t":"물류시설: 화물의 운송·보관·하역을 위한 시설, 이와 관련된 가공·조립·분류·수리·포장·상표부착·판매·정보통신 등의 활동을 위한 시설, 물류의 공동화·자동화·정보화를 위한 시설, 이들 시설이 모여 있는 물류터미널 및 물류단지를 말한다.","src":"이론"},{"t":"물류거점시설의 종류: 물류단지, 복합물류터미널, 공동집배송센터, ICD, CY, CFS, 물류센터, 유통센터, 배송센터, 데포(Depot).","src":"이론"},{"t":"물류단지: 물류단지시설과 지원시설을 집단적으로 설치·육성하려고 지정·개발하는 일단의 토지이다. 보관·가공·조립·포장·통관·집배송·환적 기능을 한다.","src":"이론"},{"t":"물류터미널은 복합물류터미널과 일반물류터미널로 나눈다.","src":"이론"}]},{"머리":"물류터미널·복합물류터미널·배송센터","줄":[{"t":"복합물류터미널: 복수 운송수단 간 연계 규모·시설, 화물취급장, 창고, 유통가공시설, 편의시설을 갖춘다. 환적과 화물정보센터 기능도 한다.","src":"기출 2023-3, 2024-3, 2025-3, 2026-3"},{"t":"복합물류터미널은 보관 위주 시설이 아니고 환적물량을 취급한다. 물류정보 기능도 포함한다.","src":"기출 2024-3, 2025-3"},{"t":"물류터미널의 기능: 집하·하역·분류·포장·보관·가공·조립·혼재·환적·재포장·화물정보 제공.","src":"기출 2021-6, 2022-5, 2023-7"},{"t":"물류센터의 기능: 조립·유통가공, 상품 보호를 위한 포장, 입출고를 위한 오더피킹.","src":"기출 2021-14"},{"t":"배송센터의 일반 기능: 보관, 분류, 배송, 수집, 유통가공. 통관은 하지 않는다.","src":"기출 2026-16"},{"t":"공동집배송센터: 여러 유통사업자·제조업자가 공동으로 쓰는 집배송시설과 부대업무시설을 갖춘다.","src":"기출 2023-7, 2025-5"},{"t":"스톡 포인트(Stock Point): 재고품의 임시보관 거점이자 배송거점이며 예상 수요에 대한 보관 장소이다. 대도시·지방 중소도시의 효율적 배송을 위한 유통 중계시설이다.","src":"기출 2023-3, 2025-5"},{"t":"공동집배송단지 도입 효과: 계획 배송으로 차량 적재효율 상승, 혼합배송으로 공차율 감소, 공동 참여로 대량 구매·계획 매입, 물류작업 공동화로 물류비 절감.","src":"기출 2023-2"},{"t":"공동집배송단지는 보관 수요를 통합 관리하므로 업체별 보관 공간과 관리 비용이 줄어든다.","src":"기출 2023-2"}]},{"머리":"입지·소유에 따른 물류센터 분류","줄":[{"t":"항만 입지형: 부두 창고, 임항 창고, 보세 창고 등이 있다.","src":"기출 2022-3"},{"t":"단지 입지형: 유통업무단지 등 유통 거점에 집중 입지한다. 공동창고, 집배송단지, 복합물류터미널 등이다.","src":"기출 2022-3"},{"t":"도시 근교 입지형: 백화점·슈퍼마켓·대형 할인매장·인터넷 쇼핑몰 등을 지원하는 창고이다.","src":"기출 2022-3"},{"t":"자가 시설: 제조·유통업체가 자기 책임으로 운영하는 물류센터이다.","src":"기출 2022-3"}]},{"머리":"컨테이너 관련 시설 (ICD·CY·CFS)","줄":[{"t":"ICD(Inland Container Depot): 수출입 통관, 집하·분류를 하고 트럭회사·포워더를 유치하므로 내륙 항만이라 부른다.","src":"기출 2021-5, 2024-4"},{"t":"ICD는 마샬링과 본선 선적·양하는 하지 않는다. 그것은 항만 컨테이너터미널의 기능이다.","src":"기출 2024-4"},{"t":"ICD 특성: 다양한 교통수단과의 높은 연계성이 입지조건이다. 통관이 빨라져 통관비가 줄어든다. 통관검사 후 재포장이 필요하면 ICD 자체 포장시설을 이용할 수 있다.","src":"기출 2022-4"},{"t":"ICD는 항만지역에 비해 창고용 토지 매입이 쉽고, 화물을 대단위화해 운송 효율을 높인다.","src":"기출 2022-4 / 보충(추정)"},{"t":"CY(Container Yard): 컨테이너를 인도·인수·보관하는 장소.","src":"기출 2024-4, 2025-6 / 보충"},{"t":"CFS(Container Freight Station): LCL 화물을 모아 목적지별로 선별해 컨테이너에 적입(Stuffing)하고, FCL 화물을 분리(Stripping)하는 시설이다.","src":"기출 2021-18, 2023-3, 2025-6"},{"t":"ODCY(Off Dock Container Yard): 부두 밖에 있는 컨테이너 장치장.","src":"기출 2026-3 / 보충"}]},{"머리":"보세구역 (관세법)","줄":[{"t":"보세구역은 지정보세구역·특허보세구역·종합보세구역으로 나눈다.","src":"관세법 제154조 / 기출 2025-7"},{"t":"지정보세구역은 지정장치장과 세관검사장으로 나눈다.","src":"관세법 제154조 / 기출 2023-7"},{"t":"특허보세구역은 보세창고·보세공장·보세전시장·보세건설장·보세판매장으로 나눈다. 세관검사장은 특허보세구역이 아니다.","src":"관세법 제154조 / 기출 2023-7, 2026-7"},{"t":"지정장치장은 통관을 하려는 물품을 일시 장치하기 위한 장소로 세관장이 지정하는 구역이다.","src":"관세법 제169조 / 기출 2025-7"},{"t":"세관장은 국가, 지방자치단체, 공항시설·항만시설을 관리하는 법인이 소유·관리하는 토지·건물 등을 지정보세구역으로 지정할 수 있다.","src":"관세법 제166조"},{"t":"특허보세구역을 설치·운영하려는 자는 세관장의 특허를 받아야 한다. 갱신도 같다.","src":"관세법 제174조 / 기출 2025-7"},{"t":"보세창고에는 외국물품이나 통관을 하려는 물품을 장치한다.","src":"관세법 제183조 / 기출 2023-13, 2025-12"},{"t":"보세공장에서는 외국물품을 원료 또는 재료로 하거나 외국물품과 내국물품을 원료로 하여 제조·가공 등을 할 수 있다. 내국물품만 원료로 하려면 세관장의 허가가 필요하다.","src":"관세법 제185조 / 기출 2025-7"},{"t":"종합보세구역에서는 보세창고·보세공장·보세전시장·보세건설장·보세판매장 기능 중 둘 이상을 수행할 수 있다. 지정권자는 관세청장이다.","src":"관세법 제197조 / 기출 2025-7"},{"t":"세관검사장: 통관을 위한 물품을 반입해 세관검사를 받게 하는 장소.","src":"기출 2025-7"}]},{"머리":"그 밖의 물류시설","줄":[{"t":"농수산물종합유통센터: 농수산물의 수집·포장·가공·보관·수송·판매 기능을 한다. 통관 기능은 없다.","src":"기출 2024-4"},{"t":"중소유통공동도매물류센터는 일반물류단지시설에 든다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조 / 기출 2026-5"}]},{"머리":"물류센터의 종류·기능","줄":[{"t":"물류센터: 물적유통의 중심지. 수요와 공급의 조절, 유통가공으로 부가가치 증진, 수송비와 생산비의 절충, 마케팅 지원을 맡는다.","src":"이론"},{"t":"보관센터(SC, Stock Center): 재고품의 임시보관 거점이다. 상품의 배송거점이면서 예상 수요에 대한 보관거점이다. 보관기능이 중심이고 스톡 포인트(하치장)라고도 한다.","src":"이론"},{"t":"배송센터(DC, Delivery Center): 배송의 중심지이다. 물품 보관기간이 짧고 입출고 빈도가 높다. 집배송센터·집배센터라고도 한다.","src":"이론"},{"t":"통과센터(DP, Depot, 데포): 소비지에 가까운 일시 보관장소이자 소규모 집배송 중계·배송처이다. 소비자에게 최종 배송을 한다. 크로스도킹 기능이 있다.","src":"이론"},{"t":"크로스도킹: 입고된 상품을 보관하지 않고 곧바로 소매점포에 배송한다. 보관·피킹 작업을 없애 물류비용을 크게 줄인다.","src":"이론"},{"t":"스톡 포인트: 대도시·지방 중소도시에 합리적 배송을 하려고 설립한 유통 중계기지이다. 제조업체나 유통업체가 재고품을 일시 보관하는 시설이다.","src":"이론"},{"t":"물류센터의 장점: 교차수송·중복수송이 감소하고, 상물 분리로 물류 효율화를 이루며, 유통가공과 적정 재고 유지가 가능하다.","src":"이론"}]},{"머리":"복합물류터미널·공동집배송센터","줄":[{"t":"복합물류터미널의 기능: 화물 혼재, 환적, 환적·혼재·유통가공·포장을 위한 단기 보관·가공, 최종 소비자 배송과 개별 기업의 배송센터 기능, 화물정보센터 기능 강화.","src":"이론"},{"t":"복합물류터미널은 창고단지·유통가공시설·물류사업자 업무용 시설을 결합한 종합물류기지 역할을 한다.","src":"기출 2020-10"},{"t":"복합화물터미널을 협의로는 운송수단 간 연계시설, 화물취급장, 창고시설 및 관련 편의시설 등을 뜻한다.","src":"기출 2020-10"},{"t":"공동집배송센터 기대효과: 차량 적재율 상승과 운송거리 단축으로 물류비 절감, 화물흐름 원활화·인력절감·공간활용 극대화, 토지효율·투자효율 극대화.","src":"이론"},{"t":"공동집배송센터는 법적 제약과 높은 지가로 개별 업체가 개발하기 어려울 때 유용하다.","src":"이론"},{"t":"공동집배송 운영효과: 배송물량 통합으로 적재효율 상승, 공동참여로 대량구매·계획매입, 보관 수요 통합 관리로 보관 공간·관리 비용 절감, 혼합배송으로 공차율 감소(영차율 증가), 물류작업 공동화로 물류비 절감.","src":"이론"}]},{"머리":"ICD·CY·CFS 보충","줄":[{"t":"ICD(내륙컨테이너기지): 항만터미널과 내륙운송수단의 연계가 편리한 산업지역에 있는 컨테이너 장치장이다. 컨테이너 화물 통관기능까지 갖춘다. 산업단지와 항만 사이를 잇는 복합물류터미널 역할을 한다.","src":"이론"},{"t":"ICD 기능: 내륙통관, 장치보관, 집화분류, 포장, 내륙운송, 정보제공.","src":"이론"},{"t":"ICD 장점: 항만보다 장치시설 토지 취득이 쉽고 시설비가 적어 컨테이너 장치료가 싸다. 내륙연계수송 강화와 하역 기계화로 노동생산성이 오른다. 항만의 통관 혼잡을 피해 통관이 빨라지고 통관비가 준다. 화물이 대단위화되어 운송 효율이 오른다.","src":"이론"},{"t":"ICD는 선사·트럭회사·관세사·포장회사·포워더를 유치해 운영하므로 내륙 항만이라 한다. 항만·공항이 아니어도 세관 통제하에 통관업무를 한다.","src":"이론"},{"t":"CY(Container Yard): 수출입용 컨테이너를 보관·취급하는 장소이다. CFS·마샬링 야드(부두선적대기장)·에이프런·샤시 및 트랙터 장치장까지 포함한다.","src":"이론"},{"t":"FCL 화물은 CY에서 대기한다. LCL 화물은 CFS에서 혼재작업을 해 FCL 화물로 만든 뒤 CY로 보낸다.","src":"이론"},{"t":"FCL(Full Container Load): 컨테이너 1대를 가득 채운 화물. LCL(Less than Container Load): 컨테이너 1대를 채우기에 부족한 화물.","src":"이론"},{"t":"CY에서 FCL의 인도·인수가 이루어지고, 해상운송인의 책임이 이곳에서 시작하거나 끝난다.","src":"이론"},{"t":"ODCY(Off-Dock Container Yard): 부두 밖의 CY. 컨테이너 터미널과 떨어져 항만의 시내·외곽에 있다. 장치보관 기능은 좋아지나 도심 교통난 가중, 항만통제 기능 약화가 문제로 남는다.","src":"이론"},{"t":"CFS(화물취급장): 수출 때 여러 송하인의 LCL 화물을 모아 혼재해 FCL 컨테이너로 만든다. FCL로 수입된 컨테이너는 화주별 LCL 화물로 분해해 인도를 준비한다.","src":"이론"},{"t":"CFS는 LCL 화물을 FCL 화물로 만들어 컨테이너에 적입(vanning, stuffing)하거나 적출(devanning, unstuffing)하는 장소이다.","src":"이론"},{"t":"CFS와 CY는 부두 외부에도 위치할 수 있다.","src":"기출 2020-11"}]},{"머리":"보세구역 보충","줄":[{"t":"보세구역: 세금이 보류된 구역이다. 관세를 내지 않고 세관장의 허가로 운영하는 특별지역이다. 수출입화물의 집화·분류·보관·운송을 효율화하려고 세관장이 지정하거나 특허한 장소이다.","src":"이론"},{"t":"보세구역에 물품을 반입·반출하려면 관세법 제157조에 따라 세관장에게 신고한다.","src":"이론"},{"t":"지정보세구역의 물품 장치기간은 6개월 범위에서 관세청장이 정한다.","src":"이론"}]}],"함정":[{"x":"마샬링(Marshalling) 기능과 선박의 양하 작업을 수행한다.","o":"마샬링(Marshalling)과 선박의 양하 작업은 컨테이너터미널(항만)의 기능이다. 복합물류터미널·물류터미널이 하는 일이 아니다.","src":"기출 2021-6 / 보충"},{"x":"임대 시설은 화차로 출하하기 위하여 일시 대기하는 화물의 보관을 위한 물류센 터이다.","o":"임대 시설: 임차(리스)해서 쓰는 물류센터. 화차 출하 전 일시 대기 화물을 보관하는 센터는 철도역 연계형의 설명이다.","src":"기출 2022-3 / 보충(추정)"},{"x":"장기보관 위주의 보관 기능을 강화한 시설이다.","o":"물류터미널·복합물류터미널은 환적·혼재·재포장·정보 기능을 하며 장기보관 위주의 시설이 아니다.","src":"기출 2022-5 / 기출 2022-5, 2024-3"},{"x":"배송센터는 장치보관, 수출입 통관, 선박의 적하 및 양하기능을 수행하는 육상운송 수단과의 연계 지원시설이다.","o":"배송센터는 보관·분류·배송·수집·유통가공을 한다. 장치보관·통관·선박 적양하는 ICD·항만의 기능이다.","src":"기출 2023-7 / 기출 2021-5, 2026-16"},{"x":"보관기능 위주로 운영되는 물류시설로 환적물량은 취급하지 않는다.","o":"복합물류터미널은 환적물량을 취급한다. 보관 위주 시설이 아니다.","src":"기출 2024-3 / 기출 2024-3, 2025-3"},{"x":"ICD 설명을 도시첨단물류단지에 붙인 선지(2024-4 선지 5)","o":"수출입 통관·집하·분류, 트럭회사·포워더 유치, 내륙 항만은 ICD의 설명이다.","src":"기출 2024-4"},{"x":"농수산물종합유통센터가 통관 기능도 수행한다.","o":"통관 기능은 없다. 수집·포장·가공·보관·수송·판매 기능이다.","src":"기출 2024-4"},{"x":"CY는 LCL 화물을 컨테이너에 넣고 꺼내는 시설이다.","o":"LCL 적입·FCL 분리는 CFS의 일이다. CY는 컨테이너를 인도·인수·보관하는 장소이다.","src":"기출 2024-4"},{"x":"특허보세구역: 일반 개인이 신청하면 지방자치단체장이 특허해 주는 보세구역.","o":"특허보세구역은 세관장이 특허한다.","src":"관세법 제174조"},{"x":"공동집배송단지가 혼합배송으로 차량의 공차율을 증가시킨다.","o":"혼합배송으로 공차율이 감소한다.","src":"기출 2023-2"},{"x":"공동집배송단지가 보관 수요 통합 관리로 업체별 보관 공간 및 관리 비용을 증가시킨다.","o":"보관 공간과 관리 비용이 줄어든다.","src":"기출 2023-2"},{"x":"ICD는 항만지역보다 창고 보관 시설용 토지 매입이 어렵다.","o":"항만지역보다 토지 매입이 쉽다.","src":"기출 2022-4 / 보충(추정)"},{"x":"ICD는 화물의 소단위화로 운송의 비효율이 발생한다.","o":"ICD는 화물을 대단위로 모아 운송 효율을 높인다.","src":"기출 2022-4 / 보충(추정)"},{"x":"복합물류터미널은 화물자동차·철도화차의 공차율이 증가하는 역효과가 상존한다.","o":"복합물류터미널은 공차율을 줄인다.","src":"기출 2025-3 / 보충(추정)"},{"x":"복합물류터미널은 환적기능보다 보관기능 위주이고 물류정보 기능은 포함하지 않는다.","o":"환적·화물정보센터 기능을 수행한다.","src":"기출 2025-3"},{"x":"스마트물류센터: 수출입컨테이너 내륙 통관기지로 항만터미널과 유사한 기능(2025-5 ㄷ)","o":"그 설명은 ICD이다. 스마트물류센터는 인증받은 첨단 물류창고이다.","src":"기출 2025-5"},{"x":"특허보세구역에 세관검사장이 포함된다.","o":"세관검사장은 지정보세구역이다. 특허보세구역은 보세창고·보세공장·보세전시장·보세건설장·보세판매장이다.","src":"관세법 제154조 / 기출 2026-7"},{"x":"통관을 하지 않은 내국물품을 보세창고에 장치하기 위해서는 항만법에 근거하여 해당 지방자치단체장의 허가를 받아야 한다.","o":"보세창고는 관세법에 근거해 세관장의 특허를 받아 설치한다. 항만법·지방자치단체장의 허가가 아니다.","src":"기출 2020-11"},{"x":"복합화물터미널은 최종 소비자 배송, 개별 기업의 배송센터 기능도 수행하지만 정보센터 기능은 수행하지 않는다.","o":"복합물류터미널은 화물정보센터 기능도 수행한다.","src":"기출 2020-10"},{"x":"ICD는 항만이나 공항이 아닌 내륙시설이라 공적 권한을 갖지 못한다.","o":"ICD도 항만처럼 세관 통제하에 통관업무를 한다.","src":"이론"},{"x":"물류센터를 구축하면 교차 및 중복수송이 증가한다.","o":"교차수송과 중복수송이 감소한다.","src":"이론"},{"x":"DP(Depot): 재고품의 보관거점으로 상품의 배송거점인 동시에 예상수요에 대한 보관거점이며 일명 하치장이라 부른다.","o":"그 설명은 스톡 포인트(SP)이다. 데포는 소비지 가까운 일시 보관장소이자 소규모 집배송 중계·배송처이다.","src":"이론"},{"x":"CY(Container Yard): LCL 화물을 모아서 FCL 화물로 만드는 취급장이다.","o":"LCL을 FCL로 만드는 곳은 CFS이다. CY는 FCL의 인도·인수 장소이다.","src":"이론"},{"x":"CFS(Container Freight Station)는 컨테이너 보세장치장, 마샬링 야드 등을 의미한다.","o":"CFS는 LCL 화물을 FCL 화물로 적입하거나 적출하는 컨테이너 화물 조작장소이다.","src":"이론"}]},"#3":{"묶음":[{"머리":"입지 선정 시 고려사항","줄":[{"t":"입지 선정 단계에서 우선 고려할 것: 지가, 운송비, 시장 규모, 각종 법적 규제.","src":"기출 2021-2"},{"t":"제품의 보관 위치 할당은 센터 내부 운영 문제이지 입지 선정의 우선 고려 사항이 아니다.","src":"기출 2021-2"},{"t":"수요와 공급을 효율적으로 연계할 수 있는 지역을 고른다.","src":"기출 2022-8"},{"t":"노동력 확보가 가능한 지역을 고른다.","src":"기출 2022-8"},{"t":"경제적·자연적·지리적 요인을 고려한다.","src":"기출 2022-8"},{"t":"운송수단의 연계가 쉬운 지역에 입지한다.","src":"기출 2022-8"},{"t":"토지 가격은 고려 요인 가운데 하나이며 최우선 조건이 아니다.","src":"기출 2022-8"},{"t":"입지선정 5요인: P(Product, 제품), Q(Quantity, 수량), R(Route, 경로), S(Service, 서비스), T(Time, 시간).","src":"이론"},{"t":"P-Q 분석: 화물이 어느 정도 양으로 흐르는지 보는 물류유형 분석이다. X축에 물품 종류, Y축에 수량을 놓는 파레토 법칙을 쓴다.","src":"이론"},{"t":"R 분석: 물량이 어떤 경로로 흐르는지 과거부터 현재까지 경향을 파악해 장래계획을 정한다. 연관 차트(Relationship Chart)를 쓴다.","src":"이론"},{"t":"S-T 분석: 주부문인 제조·판매 부문을 효율적으로 가동하려고 보조 부문이 갖출 기능을 정하는 기법이다.","src":"이론"},{"t":"입지선정 고려사항: 운송비를 고려한 비용 최소 위치, 물동량 분석, 시장을 형성하는 고객의 형태, 향후 자산 가치 상승 가능성, 지역 세금정책과 유틸리티(전기·상하수도·가스) 비용, 가용 노동인구와 평균 임금 수준.","src":"이론"}]},{"머리":"입지결정 기법 전체","줄":[{"t":"무게중심법(Center of Gravity): 수요지·공급지의 거리와 물동량을 고려해 총 운송비가 최소가 되는 좌표를 구한다. 총 운송비가 거리에 비례한다고 가정한다.","src":"기출 2021-4, 2023-8"},{"t":"무게중심법은 공급지·수요지의 위치와 반입·반출 물량이 주어져야 한다. 수송비를 입지요인으로 본다.","src":"기출 2023-8"},{"t":"톤-킬로법: 물동량의 무게와 거리를 고려해 수요처·배송센터까지의 거리와 운송량으로 입지를 평가한다. 주관적 요인은 반영하지 못한다.","src":"기출 2024-7, 2025-9"},{"t":"요인평정법(가중점수법): 접근성·지역환경·노동력 등 입지요인별로 가중치를 두고, 가중치를 곱한 요인별 점수로 후보지를 고른다.","src":"기출 2024-7, 2025-9, 2026-8"},{"t":"브라운 & 깁슨법: 입지 영향 요인을 필수적 요인·객관적 요인·주관적 요인으로 나누어 평가한다.","src":"기출 2021-4, 2024-7, 2025-9, 2026-8"},{"t":"총비용 비교법: 입지 대안별 예상비용을 산출해 총비용이 최소인 대안을 고른다.","src":"기출 2021-4, 2024-7, 2025-9, 2026-8"},{"t":"손익분기 도표법: 예상 물동량(입고량 또는 출고량)에 대한 고정비와 변동비를 산출해, 물동량에 따른 총비용이 최소인 대안을 고른다.","src":"기출 2021-4, 2023-9, 2024-7, 2026-8"},{"t":"체크리스트법은 입지 요인을 점검표로 평가하는 방법이다.","src":"기출 2023-9 / 보충"}]},{"머리":"계산: 무게중심법","줄":[{"t":"공식: X = Σ(물동량×X좌표) ÷ Σ물동량, Y = Σ(물동량×Y좌표) ÷ Σ물동량.","src":"기출 2022-6, 2023-17, 2025-8, 2026-10"},{"t":"공급지(생산공장)의 물동량은 수요지 물동량의 합으로 놓고 분자·분모에 모두 넣는다.","src":"기출 2022-6, 2023-17, 2026-10"},{"t":"풀이 순서: ① 공급지 물동량=수요량 합 ② 지점별 물동량×좌표 합 ③ 전체 물동량 합으로 나눔.","src":"기출 2022-6, 2023-17"},{"t":"예(2022-6): 시장 (50,10)·100, (20,50)·200, (10,10)·200, 공장 (100,150)·500 → X=61, Y=88.","src":"기출 2022-6"},{"t":"예(2026-10): 수요지 (5,80)·20, (10,40)·20, (20,10)·10, 공장 (80,60)·50 → (45, 55).","src":"기출 2026-10"}]},{"머리":"계산: 직각거리","줄":[{"t":"직각거리 = |x1−x2| + |y1−y2|. 일별 총이동거리 = Σ(직각거리 × 일별 배송횟수).","src":"기출 2021-16"},{"t":"예(2021-16): 센터 (6,4). 수요지1 (3,8)·2회 → 14, 수요지2 (8,2)·3회 → 12, 수요지3 (2,5)·2회 → 10. 합계 36km.","src":"기출 2021-16"}]},{"머리":"입지결정 기법 보충","줄":[{"t":"무게중심법 가정: 공급지·수요지 위치가 고정되고, 각 공급자에서 단일 물류센터로 반입되는 물동량과 센터에서 각 수요지로 반출되는 물동량이 정해져 있다.","src":"이론"},{"t":"무게중심법: 거리 × 거리당 운임 × 물동량으로 지점별 수송비를 구해 합산하고, 그 총운송비가 최소인 지점을 구한다. 두 지점 간 이동이 직선거리로 이루어진다고 본다.","src":"이론"},{"t":"체크리스트법: 양적 요인과 질적 요인을 동시에 고려해 중요도에 따라 평가점수가 가장 높은 입지를 고른다.","src":"이론"},{"t":"부하-거리법(완전 그리드 탐색법): 각 수요지에서 배송센터까지 직각거리에 수요지별 배송빈도(또는 인구)를 곱한 총계가 최소인 대안을 고른다.","src":"이론"},{"t":"손익분기도표법 적용: 총비용함수 TC = 고정비 + 단위당 변동비 × 물동량. 예상 물동량이 작으면 고정비가 낮은 지역, 크면 변동비가 낮은 지역이 유리하다.","src":"이론"},{"t":"손익분기도표 예: TC(A)=1,000+200Q, TC(B)=2,000+100Q, TC(C)=3,000+50Q(단위 만원, Q 만 톤). 물동량 10만 톤 이하는 A, 10~20만 톤은 B, 20~30만 톤은 C가 최적이다.","src":"이론"}]},{"머리":"계산: 무게중심법 보충","줄":[{"t":"수요량·공급량이 가중치다. 공장(공급지) 공급량도 수요지와 똑같이 분자·분모에 넣는다.","src":"기출 2020-18"},{"t":"예(2020-18): 공장1 (10,70)·200, 공장2 (40,40)·500, 수요지1 (20,50)·200, 수요지2 (30,20)·300, 수요지3 (50,30)·200. 가중치 합 1,400. X=45,000÷1,400≈32.1, Y=56,000÷1,400=40.0. 정답 (32.1, 40.0).","src":"기출 2020-18"}]}],"함정":[{"x":"토지 가격이 저렴한 지역을 최우선 선정조건으로 고려한다.","o":"토지 가격은 고려 요인의 하나일 뿐 최우선 선정조건이 아니다. 수요·공급 연계, 운송수단 연계, 노동력 확보 등을 함께 본다.","src":"기출 2022-8 / 기출 2021-2, 2022-8"},{"x":"시장경쟁력, 재고통합효과, 설비를 고려하는 동적 입지모형이다.","o":"무게중심법은 수송비를 고려하는 정적(static) 입지모형이다. 시장경쟁력·재고통합효과·설비를 함께 고려하는 것은 동적 모형이다.","src":"기출 2023-8 / 보충(추정)"},{"x":"톤-킬로법은 물동량의 무게와 거리를 고려한 방법으로 입지 제약, 환경 제약 등 의 주관적 요인을 반영할 수 있는 방법이다.","o":"톤-킬로법은 물동량의 무게와 거리를 고려하지만 입지·환경 제약 같은 주관적 요인은 반영하지 못한다. 주관적 요인은 요인평정법·브라운깁슨법에서 다룬다.","src":"기출 2024-7 / 기출 2024-7 / 보충"},{"x":"의사결정나무분석(Decision Tree Analysis): 설문지, 현장인터뷰 등을 통해 소비자들 로부터 의견을 청취하고, 파레토분석을 실시하여 선정하는 방법이다.","o":"설문지·현장인터뷰 등으로 소비자 의견을 듣는 것은 시장조사법이다. 의사결정나무는 의사결정 경로를 분기도로 나타내 기대가치를 비교한다.","src":"기출 2026-8 / 기출 2025-19 / 보충"},{"x":"제품의 보관 위치 할당(물류센터 입지 선정 단계에서 우선 고려할 사항으로)","o":"입지 선정이 아니라 센터 내부 운영·설계 단계의 문제이다.","src":"기출 2021-2"},{"x":"톤-킬로법은 입지 제약, 환경 제약 등의 주관적 요인을 반영할 수 있다.","o":"톤-킬로법은 주관적 요인을 반영하지 못한다.","src":"기출 2024-7 / 보충"},{"x":"톤-킬로법: 입지거점 대안별로 예상비용을 산출하고 총비용이 최소가 되는 대안을 선택(2025-9 선지 1)","o":"그 설명은 총비용 비교법이다.","src":"기출 2025-9"},{"x":"총비용 비교법: 입지요인에 주관적으로 가중치를 설정해 평가(2025-9 선지 3)","o":"그 설명은 요인평정법이다.","src":"기출 2025-9"},{"x":"요소분석법: 고정비와 변동비를 산출해 총비용이 최소인 대안 선택(2025-9 선지 4)","o":"그 설명은 손익분기 도표법이다.","src":"기출 2025-9"},{"x":"손익분기 도표법: 각 수요처와 배송센터까지의 거리와 운송량을 평가해 입지 선택(2025-9 선지 5)","o":"그 설명은 톤-킬로법 계열이다. 손익분기 도표법은 고정비·변동비 비교이다.","src":"기출 2025-9 / 보충(추정)"},{"x":"입지선정 5요인은 P(Product), Q(Quantity), R(Reliability), S(Service), T(Time)이다.","o":"R은 Route(경로)이다.","src":"이론"},{"x":"톤·킬로법은 공급지 및 수요지가 고정되어 있고, 각 공급지에서 단일 배송센터로 반입되는 물량과 배송센터에서 각 수요지로 반출되는 물동량이 정해져 있을 때 활용하는 기법이다.","o":"그 설명은 무게중심법이다. 톤·킬로법은 각 수요지에서 배송센터까지의 거리와 운송량을 평가해 총계가 최소인 입지를 고른다.","src":"이론"},{"x":"브라운·깁슨법은 물류센터 유지관리비용을 산출하고 총비용이 최소가 되는 대안을 선정하는 기법이다.","o":"그 설명은 총비용 비교법이다. 브라운-깁슨법은 필수적·객관적·주관적 요인을 고려한다.","src":"이론"},{"x":"총비용비교법은 입지에 영향을 주는 인자들을 필수적 요인, 객관적 요인, 주관적 요인 등을 고려하여 다수의 입지를 결정하는 기법이다.","o":"그 설명은 브라운-깁슨법이다.","src":"이론"}]},"#4":{"묶음":[{"머리":"건설 업무 단계","줄":[{"t":"입지분석단계: 지역분석, 시장분석, 정책 및 환경 분석, SWOT 분석.","src":"기출 2021-7"},{"t":"기능분석단계: 취급 물품 특성에 맞춰 물류센터 기능을 분석한다.","src":"기출 2021-7"},{"t":"투자효과분석단계: 시설 규모·운영 방식·경제적 투자 타당성을 분석한다.","src":"기출 2021-7"},{"t":"기본설계단계: 구체적 레이아웃과 작업방식을 설계한다.","src":"기출 2021-7"},{"t":"시공운영단계: 토목·건축 시공 후 테스트와 보완을 거쳐 운영한다.","src":"기출 2021-7"},{"t":"물류거점 분석 단계의 활동: 지역 분석, 수익성 분석, 투자 효과 분석, 거시환경 분석. 하역장비 설치는 시공 단계이다.","src":"기출 2022-12"},{"t":"계획·운영 3단계: 1단계 물류거점분석, 2단계 물류센터 설계, 3단계 시공 및 운영.","src":"이론"},{"t":"1단계 물류거점분석: 입지분석(지역분석→시장분석→법률적·행정적 조건분석), 물류거점 기능분석(적정 유치업종 선정, 센터 콘셉트 결정), 경제적 타당성분석(건설규모·운영방식 결정→건설계획 및 투자자금 분석→타당성분석).","src":"이론"},{"t":"경제적 타당성분석에는 NPV법, IRR법, 회수기간법 등을 적용한다.","src":"이론"},{"t":"2단계 설계: 기본설계(구조 및 운영시스템 결정, 주요 설비·기본설비 계획)와 상세설계(토목·건축 설계, 설비시공 설계).","src":"이론"},{"t":"3단계 시공·운영: 자금조달·민간투자방식 결정(BTO, BOT, BTL 등) → 시공(토목·건축 시공, 하역·운반 장비 설비시공, WMS 구축) → 완공 후 운영관리(준공·시운전 보완, 작업배치, 교육·훈련, 사후관리 A/S).","src":"이론"}]},{"머리":"설계 고려 특성·규모 결정 요인","줄":[{"t":"물류센터 설계 고려요인: 입하능력, 출하시간, 물품 취급횟수, 보관 면적.","src":"기출 2021-8"},{"t":"운영특성: 입고·보관·피킹·배송방법.","src":"기출 2022-7, 2023-5, 2024-8"},{"t":"물품특성: 제품의 크기·무게·가격.","src":"기출 2022-7, 2023-5, 2024-8"},{"t":"주문특성: 주문건수·주문빈도·주문크기.","src":"기출 2024-8, 2025-2"},{"t":"설비특성: 설비종류·자동화 수준.","src":"기출 2022-7, 2023-5, 2025-2"},{"t":"환경특성: 지리적 위치·입지 제약·환경 제약.","src":"기출 2023-5, 2025-2"},{"t":"규모 결정 영향 요인: 자재취급시스템 형태, 통로 요구조건, 재고배치, 현재 및 미래의 제품 출하량, 사무실 공간.","src":"기출 2023-11"},{"t":"규모 산정에는 목표 재고량과 서비스 수준을 함께 고려한다.","src":"기출 2022-7 / 보충(추정)"},{"t":"입지 결정에서는 관련 비용의 최소화를 고려한다.","src":"기출 2022-7"},{"t":"관리 특성: 재고정책, 고객 서비스 목표, 투자 및 운영비용.","src":"이론"},{"t":"주문 특성: 주문건수, 주문빈도, 주문의 크기, 처리속도, 출하시간.","src":"이론"},{"t":"설비 특성: 설비종류, 운영방안, 자동화 수준. 환경 특성: 지리적 위치, 입지제약, 환경제약.","src":"이론"},{"t":"물류센터 설계 때 고려할 것: 목표재고량, 고객서비스 수준, 입하능력, 경쟁의 정도, 향후 물동량 증감. 동선 패턴을 정하는 레이아웃도 고려한다.","src":"이론"},{"t":"설계 고려요소(물류시스템 요소): 서비스 수준(리드타임, 주문마감시간, 납품시간, 주문단위), 마케팅전략과 유통구조 분석, 거점기능 및 수·배송수단, 재고관리, 거점 수와 물류비 관계.","src":"이론"},{"t":"물류센터 수가 늘면: 재고유지비용 증가, 수송비용 증가, 배송비용 감소, 시설투자·관리비용 증가, 안전재고 합 증가. 총비용은 감소하다가 증가한다.","src":"이론"},{"t":"물류센터를 통합하면 리스크풀링 효과로 안전재고가 감소한다. 센터 수는 총비용이 최소가 되는 점에서 정한다.","src":"이론"},{"t":"물류창고 수가 늘면 고객 접근성이 높아지고 창고 고정비가 늘어난다. 수가 줄면 안전재고의 합이 줄어든다.","src":"이론"}]},{"머리":"창고(레이아웃) 설계의 기본원칙","줄":[{"t":"직진성의 원칙: 물품·통로·운반기기·사람의 흐름 방향을 직진 중심으로 설계한다.","src":"기출 2025-10, 2026-9"},{"t":"모듈화의 원칙: 화물형태·운반기기·랙·통로입구·기둥간격을 모듈화한다.","src":"기출 2025-10, 2026-9"},{"t":"물품취급 횟수 최소화의 원칙: 취급·운반을 집합화·공동화한다.","src":"기출 2025-10, 2026-9"},{"t":"물품이동 간 고저간격 축소의 원칙: 흐름 과정의 높낮이 차와 횟수를 줄인다.","src":"기출 2025-10, 2026-9"},{"t":"역행교차 회피의 원칙: 물품·운반기기·사람의 흐름이 서로 교차하거나 역주행하지 않게 배치한다.","src":"기출 2025-10, 2026-9"},{"t":"레이아웃: 서비스·생산의 흐름에 맞춰 건물시설·기계설비·통로·차고·사무실 등의 위치를 공간적으로 배치하는 것이다. 통로면에 보관하는 것이 창고 내 레이아웃의 기본원칙이다.","src":"이론"},{"t":"다른 구성의 5원칙: 직진성, 역행교차 회피, 취급횟수 최소화, 중력이용(위에서 아래로 움직이게 하고 무거운 것은 하단에 배치), 모듈화(운반기기·랙·통로입구·기둥간격의 규격 정합성).","src":"이론"},{"t":"물품이동 간 고저간격은 최소화한다. 최대화가 아니다.","src":"기출 2020-23"},{"t":"모듈화: 다양한 규격·종류·치수를 계열화·단순화·통합화·그룹핑하는 것이다.","src":"이론"},{"t":"레이아웃 설계 시 고려: 작업성과 보관성 중 우선과제 결정, 고회전율 물품은 고정 로케이션·저회전율 물품은 프리 로케이션, 랙 구간은 가능한 크게, 선입선출 선정과 규격화, 랙 해체·조립 용이.","src":"이론"},{"t":"One Way 방식: 입고구와 출고구가 달라 물품이 일방통행으로 창고 내를 이동해 출구로 나간다.","src":"이론"},{"t":"U Turn 방식: 입고구와 출고구가 같거나 같은 방향이다. 보관 후 입고 반대 방향으로 출고한다. 입출고 사이클 타이밍은 줄지만 입출고 때 혼란해질 수 있다.","src":"이론"}]},{"머리":"투자타당성 분석 기법","줄":[{"t":"순현재가치법(NPV): 장래 현금흐름의 현재가치에서 초기 투자비용을 뺀 값.","src":"기출 2022-9, 2026-6"},{"t":"내부수익률법(IRR): 편익의 현재가치 합계와 비용의 현재가치 합계가 같아지는(NPV=0) 할인율.","src":"기출 2022-9, 2026-6"},{"t":"투자수익률(ROI): 순수익을 총투자비로 비교한다.","src":"기출 2026-6"},{"t":"비용편익비(B/C): 편익÷비용. 클수록 타당성이 높다.","src":"기출 2026-6 / 보충"},{"t":"자본회수기간법: 투자비를 회수하는 데 걸리는 기간을 본다.","src":"기출 2022-9 / 보충"},{"t":"물류시설 투자의 편익: 운송·보관·하역 비용 절감 등. 비용: 토지 구입비, 건설비, 운영·유지관리비 등.","src":"기출 2026-6"},{"t":"브라운깁슨법·손익분기점법은 입지·비용 분석 기법이며 IRR이 아니다.","src":"기출 2022-9"}]},{"머리":"공공 물류시설 민간투자사업 방식","줄":[{"t":"BTO(Build Transfer Operate): 건설 후 소유권을 국가·지방자치단체에 넘기고, 일정 기간 시설을 운영한 수익으로 투자비를 회수한다.","src":"기출 2023-6"},{"t":"BOT(Build Operate Transfer): 건설 후 투자비를 회수할 때까지 관리·운영하고, 계약기간이 끝나면 국가에 양도한다. 운영 기간 만료 시 소유권이 국가·지방자치단체에 귀속된다.","src":"기출 2023-6, 2026-4"},{"t":"BOO(Build Own Operate): 준공과 동시에 소유권과 운영권이 사업시행자에게 인정된다.","src":"기출 2026-4"},{"t":"BLT(Build Lease Transfer): 건설 후 일정 기간 국가·지방자치단체에 임대해 투자비를 회수하고, 임대기간이 끝나면 소유권을 넘긴다.","src":"기출 2023-6, 2026-4"},{"t":"BTL(Build Transfer Lease): 준공과 동시에 소유권이 국가에 귀속되고, 사업시행자에게 일정 기간 시설관리운영권을 인정하되 국가가 임차해 사용·수익한다.","src":"기출 2026-4 / 보충"}]},{"머리":"투자타당성 분석 기법 보충","줄":[{"t":"NPV = 장래 기대현금유입의 현재가치 − 장래 기대현금유출의 현재가치. 독립 투자안은 NPV>0이면 채택한다. 상호배타적 투자안은 NPV>0인 안 중 NPV가 가장 큰 안을 채택한다.","src":"이론"},{"t":"IRR: NPV를 0으로 만드는 할인율이다. IRR이 요구수익률 이상이면 채택하고, IRR이 높은 대안일수록 수익성이 좋다.","src":"이론"},{"t":"수익성지수(PI) = 현금유입의 현재가치 ÷ 현금유출의 현재가치. PI>1이면 채택한다.","src":"이론"}]},{"머리":"민간투자방식 보충","줄":[{"t":"BOT: 가장 보편적인 방식이다. 사업시행자가 일정 기간 소유·운영하고 계약기간이 끝나면 국가 등에 넘긴다(선 운영 후 이전).","src":"이론"}]},{"머리":"보관효율·공간활용 손실률","줄":[{"t":"보관시스템 하드웨어 방안: 창고 상부공간 활용(랙 높이 상향, 적층랙), 통로 없는 저장공간(드라이브인 랙, 이동랙), 입체적 저장(고층랙).","src":"이론"},{"t":"소프트웨어 방안: 통로면적 축소(드라이브인 랙 등 설치 후 통로면적 조정), 수납설비 내 불필요한 공간 배제(부품·박스·파렛트 크기를 고려한 설비), 프리 로케이션 시스템 채택.","src":"이론"},{"t":"총용적 = 랙용적 + 통로용적 + 높이로스. 이 중 높이로스의 비율이 가장 낮다.","src":"이론"},{"t":"사용용적 = 총용적 − 높이로스. 랙용적 = 실질용적 + 랙 공간로스.","src":"이론"},{"t":"공간활용 손실률 = 통로면적 ÷ 전체면적 × 100. 랙 높이만 주어지고 창고 높이가 주어지지 않으면 바닥면적만으로 계산한다.","src":"이론"},{"t":"예: 길이 50m, 폭 16m(2+3.5+5+3.5+2)면 전체 800㎡. 통로 (3.5+3.5)×45+16×5=395㎡. 손실률 395÷800=49.375%.","src":"이론"},{"t":"ABC 배치: A그룹은 소수 대형매출 상품이며 발주간격이 짧고 정기발주시스템을 적용한다. B그룹은 중간 상품이며 발주점방식 정량발주시스템을 적용한다. C그룹은 다수 소형매출 상품이며 Two Bin System으로 관리한다.","src":"이론"}]}],"함정":[{"x":"기본설계단계: 구체적인 레이아웃과 작업방식, 물류비용 정산방법을 설계한다.","o":"기본설계단계: 구체적인 레이아웃과 작업방식, 설비 설계를 한다. 물류비용 정산방법은 기본설계 내용이 아니다.","src":"기출 2021-7 / 보충(추정)"},{"x":"물류센터의 규모 산정 시 목표 재고량은 고려하나 서비스 수준은 고려 대상이 아니다.","o":"물류센터 규모를 정할 때 목표 재고량과 서비스 수준을 모두 고려한다.","src":"기출 2022-7 / 보충(추정)"},{"x":"주문특성은 재고정책, 고객서비스 목표, 투자 및 운영 비용을 반영한다.","o":"주문특성은 주문건수·주문빈도·주문크기를 반영한다.","src":"기출 2023-5 / 기출 2024-8"},{"x":"화물보험 가입 용이성, 신용장 개설 편의성 등 보험ㆍ금융 회사 접근 특성을 고 려한다.","o":"물류센터 설계 고려 특성은 운영·물품·주문·설비·환경이다. 보험·금융 회사 접근 특성은 해당하지 않는다.","src":"기출 2024-8 / 기출 2023-5, 2024-8"},{"x":"비용편익비(Benefit Cost Ratio)는 편익을 비용으로 나눈 비율로, 비용편익비가 작을수록 높은 투자 타당성을 갖는다.","o":"비용편익비(B/C)는 편익÷비용이며 1보다 크고 클수록 투자 타당성이 높다.","src":"기출 2026-6 / 보충"},{"x":"하역장비 설치(물류거점 분석 단계의 활동으로)","o":"하역장비 설치는 시공 단계이다. 거점 분석은 지역·수익성·투자효과·거시환경 분석이다.","src":"기출 2022-12"},{"x":"운영 요인: 지리적 위치, 입지 제약, 인구 등(2025-2 ㄱ)","o":"그 내용은 환경 요인이다. 운영 요인은 입고·보관·피킹·배송방법이다.","src":"기출 2025-2"},{"x":"환경 요인: 입고 방법, 보관 방법, 피킹 방법 등(2025-2 ㄹ)","o":"그 내용은 운영 요인이다.","src":"기출 2025-2"},{"x":"역행교차 회피의 원칙: 흐름의 배치가 서로 교차하거나 역주행이 가능하도록 설계(2025-10 선지 5)","o":"교차·역주행이 없도록 설계한다. 2026-9의 「역행교차 활성화 원칙」도 틀린 말이다.","src":"기출 2025-10, 2026-9"},{"x":"BLT: 준공과 동시에 소유권이 국가에 귀속되고 사업시행자에게 운영권을 인정하되 국가가 임차(2026-4 ㄷ)","o":"그 설명은 BTL이다. BLT는 임대 기간 후 소유권을 이전한다.","src":"기출 2026-4 / 보충"},{"x":"창고설계의 기본원칙: 물품이동 간 고저간격 최대화의 원칙","o":"물품이동 간 고저간격 최소화(축소)의 원칙이다. 직진성·모듈화·역행교차 회피·물품 취급 횟수 최소화·고저간격 최소화가 기본원칙이다.","src":"기출 2020-23"},{"x":"물류창고의 수가 증가할수록 수송비용은 감소하며 배송비용은 증가한다.","o":"창고 수가 늘면 수송비용은 증가하고 배송비용은 감소한다.","src":"이론"},{"x":"일반적인 물류센터의 작업 공정 순서는 입하→피킹→검품→보관→격납→포장→출하이다.","o":"입하→격납(인입)→보관→피킹→검품→포장→출하 순이다.","src":"이론"}]},"#5":{"묶음":[{"머리":"창고의 기능","줄":[{"t":"수급조정 기능: 생산과 소비의 시간적 간격을 조정해 일정량이 체류하게 한다. 시간적 효용을 창출한다.","src":"기출 2022-16, 2023-12"},{"t":"가격조정 기능: 수요와 공급을 조정해 가격안정을 도모한다.","src":"기출 2022-16, 2023-12"},{"t":"연결 기능: 물류활동을 연결하는 터미널 역할을 한다.","src":"기출 2022-16"},{"t":"신용기관적 기능: 재고(안전재고)를 확보해 품절을 막고 기업 신용을 높인다.","src":"기출 2022-16, 2023-12"},{"t":"물품을 안전하게 보관하거나 현상을 유지하는 역할(보존 기능).","src":"기출 2023-12"},{"t":"물품을 한 장소에서 다른 장소로 옮겨 장소적 효용을 만드는 것은 운송의 기능이다.","src":"기출 2023-12"},{"t":"보관 기능(품질 특성·영업전략), 품절 예방, 포장·라벨 부착·검품, 운송연계 기능 모두 창고 기능이다.","src":"기출 2024-15"}]},{"머리":"소유·운영 주체별 창고","줄":[{"t":"자가창고: 입지·시설·장비를 자사 물류시스템에 맞게 설계·운영한다. 건설·설비 고정비용이 든다.","src":"기출 2023-13, 2025-12"},{"t":"영업창고: 타인의 화물을 보관한다. 이용자는 초기 건설·설비투자 부담이 없고 비용지출이 명확하다.","src":"기출 2024-14, 2025-12, 2023-13"},{"t":"임대창고: 특정 보관시설을 임대하거나 리스하여 물품을 보관한다. 시장환경에 따라 보관장소를 탄력적으로 운영하기 어렵다.","src":"기출 2022-15, 2023-13, 2025-12"},{"t":"공공창고: 공공기관이 설치·운영하는 창고.","src":"보충(추정)"}]},{"머리":"용도·형태별 창고","줄":[{"t":"보세창고: 관세법에 근거하며 세관장의 특허를 받아 수출입화물을 취급한다. 외국물품·통관 예정 물품을 장치한다.","src":"관세법 제174조, 제183조 / 기출 2023-13, 2025-12"},{"t":"내국물품은 운영인이 세관장에게 신고하면 보세창고에 장치할 수 있다. 1년(제2항 단서 물품은 6개월) 이상 계속 내국물품만 장치하려면 세관장의 승인을 받아야 한다.","src":"관세법 제183조"},{"t":"유통창고: 생산된 제품의 집하·배송 기능을 갖추고 보관·가공·재포장을 한다.","src":"기출 2023-13"},{"t":"자동화창고: 입하부터 출하까지 자동화되고 유닛로드로 처리한다.","src":"기출 2025-12"},{"t":"야적창고: 물품을 노지에 보관한다.","src":"기출 2024-14"},{"t":"수면창고: 하천이나 해수면을 이용해 물품을 보관한다.","src":"기출 2024-14"},{"t":"위험물창고: 고압가스·유독성 물질 등을 보관한다.","src":"기출 2024-14"},{"t":"냉동냉장창고 온도등급에는 C1·C2·C3·F급이 있다. D급은 없다.","src":"기출 2026-14"}]},{"머리":"창고의 개념·역할·기능","줄":[{"t":"창고(warehouse): 물품을 보관하기 위한 장소로, 물품의 멸실과 훼손을 방지하는 보관시설 또는 보관장소이다.","src":"이론"},{"t":"물류창고업 등록: 전체 바닥면적 합계 1천㎡ 이상인 보관시설 또는 전체면적 합계 4천500㎡ 이상인 보관장소의 물류창고를 소유·임차해 물류창고업을 경영하려는 자는 국토교통부장관 또는 해양수산부장관에게 등록한다.","src":"이론"},{"t":"물류시스템에서 창고의 역할: 생산과 판매 사이의 일시적 완충, Link와 Link를 잇는 거점(Node).","src":"이론"},{"t":"창고가 제공하는 기능: 혼재(consolidation), 제품믹싱(product mixing), 크로스도킹, 생산·판매 완충, 운송지연·벤더 파업 같은 긴급상황 대비.","src":"이론"},{"t":"창고 기능 8가지: 보관·저장, 수급조절, 가격조정, 비용절감, 유통가공, 거점, 신용기관적, 매매기관적.","src":"이론"},{"t":"비용절감 기능: 최적 입지로 수·배송 비용을 줄인다.","src":"이론"},{"t":"유통가공 기능: 유통단계에서 보존기능을 강화하고 가공으로 부가가치를 만든다.","src":"이론"},{"t":"매매기관적 기능: 제품 매매를 통해 금융을 유통시킨다.","src":"이론"}]},{"머리":"구조·보관형태·보관기능별 분류","줄":[{"t":"구조별: 재래식 창고(내부가 시스템적으로 연결되지 않음), 기계식 창고(랙·지게차·크레인·컨베이어로 기계화), 자동화 창고(정보시스템과 하역시스템이 온라인으로 일체화).","src":"이론"},{"t":"자동화 창고와 기계식 창고의 차이는 정보시스템과 일체화되어 있는지이다. 제어방식은 온라인·오프라인으로 나눈다.","src":"이론"},{"t":"자동화 창고는 규모에 따라 자동창고와 간이 자동화 창고로 나눈다. 간이 자동화 창고는 기존 창고에 랙을 설치해 제한적 효과를 얻는다.","src":"이론"},{"t":"보관형태별: 보통창고, 저장창고, 야적창고, 위험물창고, 수면창고, 정온창고, 냉동·냉장창고, 간이창고.","src":"이론"},{"t":"보통창고: 상온 제품과 원부자재를 보관한다. 저장창고: 저장 중심의 탱크시설이며 곡물(사일로)·분립체·액체 등을 보관한다.","src":"이론"},{"t":"야적창고: 담장 등이 설치된 옥외창고에 목재·컨테이너 등을 야적한다. 위험물창고: 소방법·고압가스 취급법 등으로 지정된 위험물을 보관한다.","src":"이론"},{"t":"정온창고: 온도·습도를 일정하게 조정하는 창고(10~20°C). 냉동·냉장창고: 냉각설비를 갖춘 창고(10°C 이하). 온도 모니터링, 유통기한 관리, 콜드체인 관리를 고려한다.","src":"이론"},{"t":"간이창고: 텐트 등으로 된 간이구조의 창고이다.","src":"이론"},{"t":"보관기능별: 저장창고(저장 중심의 재래형), 보세창고, 유통창고.","src":"이론"},{"t":"유통창고: 조립·포장·분류·유통가공 작업을 하며 회전율이 높은 완제품 소비재를 다룬다.","src":"이론"}]},{"머리":"운영형태별 창고 보충","줄":[{"t":"자가창고는 수요가 안정적이거나 특수한 창고보관기술이 필요할 때 유리하다.","src":"이론"},{"t":"영업창고: 위탁받은 물품을 보관하고 보관료를 받는다. 화물인도·보관·선적과 보관 관련 서비스를 제공한다.","src":"이론"},{"t":"리스창고: 단기 영업창고 이용과 장기 자가창고 건설·운영의 중간 선택이다. 사용자가 보관공간과 운영을 직접 통제할 수 있다.","src":"이론"},{"t":"공공창고: 국가·지방단체가 공익 목적으로 건설한 창고. 공립창고, 관설상옥, 관설보세창고, 공공임대창고가 있다.","src":"이론"},{"t":"자가창고 장점: 물품의 효율적 관리와 높은 유연성, 자사에 맞는 최적 보관, 충분한 고객서비스, 창고운영 노하우 축적, 기계 합리화·생력화, 건축 시 입지선정 폭이 넓음.","src":"이론"},{"t":"자가창고 단점: 초기 투자비가 크고, 창고 규모 확장에 제약이 있고, 종업원 고정 배치로 인건비·관리비 부담이 크고, 계절변동에 비탄력적이다.","src":"이론"},{"t":"영업창고 장점: 필요한 보관공간을 언제 어디서든 이용, 전문업체의 전문적 관리, 투자비용 지출 불필요, 입지선정이 쉽고 탄력적 이용, 재고분실·파손의 보상규정이 확립.","src":"이론"},{"t":"영업창고 단점: 시설 변경의 비탄력성, 자사 특유의 설비기능 이용 곤란, 통합물류시스템과의 연계 약함, 치밀한 고객서비스 곤란, 시간·시스템 탄력성 부족, 재고품 관리 소홀.","src":"이론"},{"t":"저장량과 비용: 비용은 저장량에 비례해 늘고, 자가창고·자동화창고는 완만하게, 영업창고는 급격하게 늘어난다.","src":"이론"},{"t":"단기 물동량 증가에는 영업창고를 활용한다. 지속적 물동량 증대로 장기 보관시설이 필요하면 자가창고·자동화창고가 유리하다.","src":"이론"},{"t":"연간 처리량 기준 단위당 비용: 단기는 영업창고→임대창고→자가창고→자동화창고 순으로, 장기는 자동화창고→자가창고→임대창고→영업창고 순으로 유리하다.","src":"이론"}]}],"함정":[{"x":"보세창고는 지방자치단체장의 허가를 받은 경우에는 통관되지 않은 내국물품도 장치할 수 있다.","o":"보세창고는 외국물품이나 통관을 하려는 물품을 장치하고, 내국물품은 운영인이 세관장에게 신고하면 장치할 수 있다. 지방자치단체장의 허가가 아니다.","src":"기출 2022-15 / 관세법 제183조"},{"x":"영업창고는 임대료를 획득하기 위해 건립되므로 자가창고에 비해 화주 입장의 창고설계 최적화가 가능하다.","o":"화주 입장에서 창고설계 최적화가 가능한 것은 자가창고이다. 영업창고는 보관료를 받고 타인 화물을 보관한다.","src":"기출 2022-15 / 기출 2023-13, 2025-12"},{"x":"자가창고는 영업창고에 비해 창고 확보와 운영에 소요되는 비용 및 인력문제와 화물량 변동에 탄력적으로 대응할 수 있다.","o":"자가창고는 영업창고에 비해 건설·운영 비용과 인력 부담이 크고 물량 변동에 탄력적으로 대응하기 어렵다.","src":"기출 2022-15 / 기출 2023-13 / 보충"},{"x":"공공창고는 특정 보관시설을 임대하여 물품을 보관하는 창고형태로 민간이 설치 및 운영한다.","o":"공공창고: 정부·지방자치단체 등 공공기관이 설치·운영하는 창고. 시설을 임대하여 보관하는 것은 임대창고이다.","src":"기출 2022-15 / 보충(추정)"},{"x":"물품을 한 장소에서 다른 장소로 이동시키는 물리적 행위를 통해 장소적 효용을 창출한다.","o":"물품을 장소 간 이동시켜 장소적 효용을 창출하는 것은 운송의 기능이다. 창고는 시간적 효용을 창출한다.","src":"기출 2023-12 / 기출 2023-12, 2022-2"},{"x":"영업창고 이용자는 초기에 창고건설 및 설비투자와 관련하여 고정비용이 발생한다.","o":"영업창고 이용자는 초기 건설·설비투자 고정비용이 들지 않는다.","src":"기출 2023-13 / 기출 2025-12"},{"x":"영업창고: 비용지출이 명확하고 초기 창고 건설 및 설비투자 비용이 발생한다.","o":"영업창고는 비용지출이 명확하고 초기 건설·설비투자가 필요 없다.","src":"기출 2025-12 / 기출 2023-13"},{"x":"리스창고: 자기의 화물을 보관하기 위해 설치한 창고.","o":"자기 화물 보관용은 자가창고이다. 리스창고는 임차한 창고이다.","src":"기출 2024-14 / 보충"},{"x":"D급(냉동냉장창고 온도 분류 등급으로)","o":"D급은 없다. C1·C2·C3·F급이 있다.","src":"기출 2026-14"},{"x":"자가창고는 영업창고에 비해 낮은 고정비를 갖기 때문에 재무유동성이 향상된다.","o":"자가창고는 토지 구입과 설비투자로 고정비가 높아 재무유동성이 약화된다.","src":"이론"},{"x":"영업창고는 물류 및 정보시스템 관점에서 통합물류시스템과의 연결성이 자가창고에 비해 강하다.","o":"통합물류시스템과의 연결성이 강한 쪽은 자가창고이다. 영업창고는 연계가 약하다.","src":"이론"},{"x":"관세법에 근거하여 창고업자가 국세청의 허가를 받아 세관의 감독하에 수입화물을 보관하는 창고를 보세창고라 한다.","o":"보세창고는 관세법에 근거해 세관장의 허가(특허)를 얻어 수출입화물을 취급한다. 국세청 허가가 아니다.","src":"이론"},{"x":"창고입지의 다섯 가지 요인은 P(Product), Q(Quantity), R(Reliability), S(Service), T(Time)이다.","o":"R은 Route이다.","src":"이론"},{"x":"창고 기능: 물품의 수급을 조정하여 가격안정을 도모하는 것은 수급조정기능이다.","o":"수급을 조정해 가격안정을 도모하는 것은 가격조정기능이다. 수급조정 기능은 생산과 소비의 시간적 간격을 조정한다.","src":"이론"}]},"#6":{"묶음":[{"머리":"랙 종류 전체","줄":[{"t":"파렛트 랙(Pallet Rack): 파렛트 화물을 보관하는 기본 랙.","src":"기출 2022-10, 2022-14"},{"t":"실렉티브 랙(Selective Rack): 모든 파렛트에 직접 접근하는 기본형 랙. 경량 다품종 회전랙이 아니다.","src":"기출 2021-17 / 보충"},{"t":"드라이브인 랙(Drive-in Rack): 지게차가 한 방향에서 2개 이상 깊이의 랙에 들어가 보관·반출한다.","src":"기출 2022-10"},{"t":"드라이브스루 랙(Drive-through Rack): 지게차가 랙의 한 방향으로 진입해 반대 방향으로 퇴출할 수 있다.","src":"기출 2021-17, 2025-15"},{"t":"플로우 랙(Flow Rack): 적입과 인출이 반대 방향에서 이루어지는 선입선출 랙. 롤러·휠이 달리고 중력으로 미끄러진다.","src":"기출 2021-17, 2023-10, 2024-12, 2025-15"},{"t":"캔틸레버 랙(Cantilever Rack, 암 랙): 긴 철재·목재·파이프 같은 장척물 보관에 효율적이다.","src":"기출 2021-17, 2022-10, 2024-12, 2025-15"},{"t":"적층 랙(Mezzanine Rack): 천장이 높은 창고에서 복층 구조로 설치해 공간 활용도를 높인다.","src":"기출 2021-17, 2022-10, 2024-12, 2025-15"},{"t":"캐러셀(Carousel) 랙: 랙 자체가 수평 또는 수직으로 회전해 저장 위치가 입출고(피킹)점으로 이동한다. 가벼운 다품종 소량품에 쓴다.","src":"기출 2022-10, 2024-12, 2026-11"},{"t":"모빌 랙(Mobile Rack): 필요한 통로만 열어 쓰고 불필요한 통로를 없애 면적 효율이 높다. 바닥면·용적 효율이 높고 복수 통로를 둘 수 있다.","src":"기출 2023-10, 2025-15"},{"t":"슬라이딩 랙, 자동 슬라이딩 랙, 고층 랙, 트랜스 로보 시스템도 랙·보관 장비로 출제됐다.","src":"기출 2022-14, 2025-31"},{"t":"이중깊이저장랙(Double Deep Rack) 작업에는 리치포크(Reach Fork) 어태치먼트가 필요하다.","src":"기출 2026-31"},{"t":"랙(KS T 0001): 물품을 보관하려고 쓰는 기둥과 선반으로 구성된 구조물이다. 랙 종류는 KS T 2023이 제시한다. 자동창고와 랙 창고의 주요부를 이룬다.","src":"이론"},{"t":"파렛트 랙: 파렛트에 쌓은 물품을 보관한다. 범용성이 있어 화물 종류가 많아도 유연하고 선입선출에 유리하다. 용적효율이 낮고 바닥면적 활용이 비효율적이다.","src":"이론"},{"t":"파렛트 랙은 파렛트 화물을 그대로 지게차로 랙의 셀마다 격납해 보관한다.","src":"이론"},{"t":"드라이브인 랙: 로드빔을 제거해 지게차가 랙 안으로 진입한다. 지게차 통로면적이 줄어 보관효율이 높다.","src":"이론"},{"t":"드라이브인 랙은 소품종 다량 또는 로트 단위 입출고 화물에 최적이다. 계절적 수요 제품과 회전율 낮은 품목에 맞는다. 양쪽에 출입구를 두면 드라이브스루 랙이 된다.","src":"이론"},{"t":"드라이브인 랙은 적재공간이 지게차 통로로 쓰이므로 선입선출이 어렵다.","src":"기출 2020-26"},{"t":"적층 랙(Mezzanine Rack): 통로와 선반을 복층식으로 겹쳐 쌓는다. 면적효율과 공간 활용성이 좋고 입출고·재고관리가 쉽다. 최소의 통로로 최대로 높이 쌓을 수 있어 경제적이다.","src":"이론"},{"t":"회전 랙(Carousel Rack): 피킹할 때 피커를 고정하고 랙 자체가 순환·회전한다. 수평 또는 수직으로 돌아 소정의 입출고 장소로 이동한다. 다품종·소량·경량 화물에 맞고 작업자의 이동이 최소화된다.","src":"이론"},{"t":"슬라이딩 랙: 파렛트 화물을 한쪽에서 넣으면 중력으로 미끄러져 반대쪽에서 반출된다. 한쪽 입고·다른 쪽 출고라 이상적인 선입선출이며 면적·용적효율이 양호하다. 다품종 소량에 부적합하고 설치비용이 많이 든다.","src":"이론"},{"t":"모빌 랙: 레일 등으로 직선 수평 이동해 통로를 대폭 줄인다. 한정된 공간을 최대로 쓰고 다품종·소량·경량 화물에 맞으며 상면 면적률·용적률 효율이 높다.","src":"이론"},{"t":"이동랙은 수동식과 자동식이 있고 다품종 소량 물품 보관에 맞는다.","src":"기출 2020-26"},{"t":"캔틸레버 랙(암 랙, 외팔걸이 랙): 장척물 보관용이다. 파렛트 단위 화물에는 쓸 수 없다. 기둥이 없어 공간 낭비가 없고 재고검사·관리가 쉽다. 구르기 쉬운 화물의 유실을 막으려고 스토퍼를 붙인다.","src":"이론"},{"t":"플로우 랙: 선반의 롤러 컨베이어·레일 등으로 동력 또는 중력에 의해 보관물이 출구 또는 입구 쪽으로 이동한다. 슬라이딩 랙이라고도 하며 적입과 인출이 반대방향에서 이루어지는 선입선출 방식이다. 박스형과 파렛트형이 있다.","src":"이론"},{"t":"하이 스택 랙: AS/RS에서 주로 쓴다. 상품을 대량으로 취급하고 건물 층고에 여유가 있을 때 쓴다. 좁은 통로에 높게 적재해 바닥면 사용과 공간활용이 좋다.","src":"이론"},{"t":"평치보관(Block Storage): 창고 바닥에 화물을 쌓는 방법이다. 소품종 다량 물품 입출고에 맞고 특별한 자동화 설비가 필요 없다. 공간 활용률이 낮은 것이 단점이다.","src":"이론"},{"t":"랙 적재하중 기준: 중량 랙 500kg 초과, 중간 랙 150kg 초과 500kg 이하, 경량 랙 150kg 이하.","src":"이론"}]},{"머리":"오더피킹 출고형태별 적재방식 장비","줄":[{"t":"제1형태(P→P, 파렛트 보관·파렛트 출고): 트랜스 로보, 파렛트 랙, 드라이브인 랙, 고층 랙. 암 랙은 아니다.","src":"기출 2022-14"},{"t":"제4형태(C→C, 케이스 보관·케이스 출고): 자동 슬라이딩 랙, 슬라이딩 랙, 캐로셀 랙, 모빌 랙. 암 랙은 아니다.","src":"기출 2025-31"}]},{"머리":"보관시스템 유형(품목수-수량-회전수)","줄":[{"t":"ABC군으로 보관품목수·보관수량·회전수를 분류해 보관시스템을 구분한다.","src":"이론"},{"t":"A-A-A형: 품목수가 적고 보관량·회전율이 높다. 맥주·음료수·사탕·시멘트처럼 입출고가 빠른 제품이다. 플로우 랙 등을 쓴다.","src":"이론"},{"t":"A-A-C형: 대량 재고를 갖고 회전수가 적은 제품이다.","src":"이론"},{"t":"A-C-A형: 회전수만 높고 보관량이 적다. 임시출고→피킹→재출고에 많이 쓴다.","src":"이론"},{"t":"A-C-C형: 수량과 회전수가 적은 제품이다.","src":"이론"},{"t":"B-B-B형: 품목수·수량·회전수가 모두 보통이라 설비가 간단하고 레이아웃 변경이 쉽다.","src":"이론"},{"t":"C-A-A형: 품목수와 회전수가 많아 관리가 복잡하다. 고층 랙·모노레일·스태커 크레인 조합과 컴퓨터 운영이 효율적이다.","src":"이론"},{"t":"C-A-C형: 재고 품목수와 재고량은 많지만 회전수가 적다. 고층 랙과 모노레일 스태커 크레인이 유리하다.","src":"이론"},{"t":"C-C-A형: 품목수는 많고 보관량은 적고 이동이 많다. 고층랙시스템으로 보관하고, 개별출고에서 피킹은 머신(오더피킹)과 수동으로 한다.","src":"이론"},{"t":"C-C-C형: 재고량·이동이 모두 적고 품목수가 많아 관리가 어렵다. 파렛트에 직접 쌓는 것이 유리하다.","src":"이론"}]},{"머리":"격납장 유형","줄":[{"t":"제1유형: 소품종 대량품이고 선입선출이 크지 않을 때. 적치장 안쪽부터 순서대로 쌓고 출고할 때 가까운 곳부터 꺼낸다.","src":"이론"},{"t":"제2유형: 선입선출이 어느 정도 필요할 때. 2열 또는 3열 병렬로 정리해 입출고한다.","src":"이론"},{"t":"제3유형: 재고량이 많아질 때 피킹 순회거리를 줄이려고 동일 품종을 정면에, 폭은 좁게 깊이는 길게 적치한다. 빼내기 어려우면 플로우 랙을 쓴다.","src":"이론"},{"t":"제4유형: 재고 종류가 많아질 때 피킹 순회거리를 줄이려고 동일 품목을 폭은 좁게 깊이는 적게 적치한다. 제3유형과 같은 방식이며 피킹·출고가 곤란하면 플로우 랙을 쓴다.","src":"이론"},{"t":"제5유형(피킹장/격납장 더블빈방식): 제3·4유형에서 물품을 대량으로 쌓으면 피킹 순회거리가 길어지는 문제를 풀려고 피킹장과 격납장을 분리해 2단 적재한다.","src":"이론"},{"t":"제6유형: 피킹용 선반 상단부에 예비 물품을 파렛트로 적재한다. 하단 선반이 비면 상단 파렛트를 하단으로 옮기고 상단에 새 파렛트를 보충한다.","src":"이론"}]},{"머리":"도크(Dock)","줄":[{"t":"도크: 컨테이너·트럭 등 운송수단에 지게차 같은 물류장비가 접근하기 쉽게 하고 화물 상·하역을 효과적으로 하는 설비이다.","src":"이론"},{"t":"플러시 도크(Flush Dock): 일반적인 입출하 형태. 문 출입구를 중심으로 트럭 후면·측면에서 상하차한다.","src":"이론"},{"t":"핑거 도크(Finger Dock): 많은 트레일러를 한꺼번에 처리하려는 도크. 도크 양쪽에 트레일러 등을 맞대고 상하차한다.","src":"이론"},{"t":"드라이브인 도크(Drive-in Dock): 문이 열리면 트럭·트레일러가 공장·창고 내부로 들어가고, 문을 닫고 하역한다. 악천후에 유용하다.","src":"이론"}]},{"머리":"계산: 도크 수·출하도크 길이·선입선출 재료비","줄":[{"t":"필요 도크 수 = 월간(연간) 트럭 출입대수 × 대당 1일 작업시간 × (1+안전계수) ÷ (월간 작업일수 × 1일 작업시간).","src":"이론"},{"t":"예: 월 2,000대, 월 20일, 1일 10시간, 트럭당 4시간, 안전계수 0.2 → 2,000×4×1.2÷(20×10)=48개.","src":"이론"},{"t":"출하도크 길이 = 필요 트럭 수 × 트럭 1대당 도크 점유길이. 필요 트럭 수 = 1일 출고물동량 ÷ 트럭 1대 유효적재량 ÷ 출고회전수.","src":"이론"},{"t":"예: 7,280박스 ÷ 280박스 = 26대, 2회전이므로 13대. 13×3.0m = 39m.","src":"이론"},{"t":"선입선출법(FIFO): 먼저 입고된 것부터 출고한다. 물가 변동과 관계없이 재고평가가 된다. 후입선출법(LIFO): 나중에 입고된 물품이 먼저 출고된다고 가정해 평가한다.","src":"이론"},{"t":"FIFO 출고 재료비 예: 5/2 매입 50개 $100, 5/10 매입 50개 $120, 5/15 출고 60개 = 50×100+10×120 = $6,200. 5/20 매입 50개 $140, 5/24 출고 70개 = 40×120+30×140 = $9,000. 합계 $15,200.","src":"이론"}]}],"함정":[{"x":"실렉티브랙(Selective Rack): 경량 다품종 물품의 입출고에 적합한 수평 또는 수직의 회전랙이다.","o":"실렉티브랙: 각 파렛트에 직접 접근해 입출고하는 가장 기본적인 파렛트 랙이다. 경량 다품종 회전은 캐러셀 설명이다.","src":"기출 2021-17 / 기출 2021-17 / 보충"},{"x":"파렛트 랙(Pallet Rack): 파렛트 화물을 한쪽 방향에서 넣으면 중력에 의해 미끄 러져 인출할 때는 반대방향에서 화물을 반출할 수 있다.","o":"파렛트 랙: 파렛트 화물을 보관하는 기본 랙. 한쪽에서 넣어 반대쪽으로 인출하는 중력식 랙은 플로우 랙이다.","src":"기출 2022-10 / 기출 2021-17, 2025-15"},{"x":"파렛트가 랙 내에서 경사면을 이용하여 이동하는 방식으로 선입선출이 요구되는 제품에 적합하다.","o":"파렛트가 경사면으로 이동하는 선입선출 랙은 플로우 랙이다. 모빌랙(이동랙)은 불필요한 통로를 없애 면적 효율을 높인다.","src":"기출 2023-10 / 기출 2023-10, 2025-15"},{"x":"직선으로 수평 이동하는 랙이며, 도서관 등에서 통로면적을 절약하는데 효과적 이다.","o":"도서관식으로 직선 수평 이동하며 통로 면적을 줄이는 랙은 모빌 랙 계열의 설명이다. 이 문항의 지문은 랙 이름이 빠져 있다.","src":"기출 2024-12 / 출제 오답(바른 설명 미확인, 검수 필요)"},{"x":"선입선출의 목적으로 격납 부분에 롤러, 휠 등을 장착하여 반입과 반출이 반대 방향에서 이루어진다.","o":"롤러·휠로 반입·반출이 반대 방향에서 이루어지는 선입선출 랙은 플로우 랙이다. 이 문항 지문은 랙 이름이 빠져 있다.","src":"기출 2024-12 / 기출 2021-17, 2025-15 / 검수 필요"},{"x":"랙 자체가 수평 또는 수직방향으로 회전하여 저장 위치가 지정된 입출고장소로 이동 가능한 랙이며, 가벼운 다품종 소량품에 많이 적용된다.","o":"랙 자체가 회전하며 입출고점으로 이동하는 랙은 캐러셀이다. 이 문항 지문은 랙 이름이 빠져 있다.","src":"기출 2024-12 / 기출 2026-11 / 검수 필요"},{"x":"파이프, 목재 등의 장척물 보관에 적합하도록 랙 구조물에 암(arm)이 설치되어 있다.","o":"파이프·목재 등 장척물용 암이 달린 랙은 캔틸레버 랙(암 랙)이다. 이 문항 지문은 랙 이름이 빠져 있다.","src":"기출 2024-12 / 기출 2022-10 / 검수 필요"},{"x":"플로우 랙 설명을 파렛트 랙에(2022-10)","o":"파렛트 랙은 기본 보관 랙이다. 한쪽에서 넣어 중력으로 반대쪽에서 꺼내는 것은 플로우 랙이다.","src":"기출 2022-10"},{"x":"드라이브스루 랙: 천정이 높은 창고의 공간 활용도를 높이기 위한 복층구조의 랙(2025-15)","o":"복층구조 랙은 적층 랙이다. 드라이브스루 랙은 한 방향 진입, 반대 방향 퇴출이다.","src":"기출 2025-15"},{"x":"적층 랙: 지게차가 랙의 한 방향으로 진입해서 반대 방향으로 퇴출(2025-15)","o":"그 설명은 드라이브스루 랙이다.","src":"기출 2025-15"},{"x":"암 랙(Arm Rack)을 파렛트 단위 입출고(P→P)·케이스 단위(C→C) 적재 장비로","o":"암 랙은 두 경우 모두 해당하지 않는다(장척물용).","src":"기출 2022-14, 2025-31"},{"x":"평치저장(Block Storage): 창고 바닥에 화물을 보관하는 방법으로 소품종 다량 물품 입출고에 적합하며, 공간 활용도가 우수하다.","o":"평치저장은 소품종 다량 물품에 맞고 자동화 설비가 필요 없지만 공간 활용률이 낮다.","src":"기출 2020-26"}]},"#7":{"묶음":[{"머리":"AS/RS 구성 장치","줄":[{"t":"랙: 자동화 창고에서 화물 보관 구조물. 빌딩 랙(Building Rack)과 유닛 랙(Unit Rack)이 있다.","src":"기출 2023-16"},{"t":"스태커 크레인(Stacker Crane): 랙과 랙 사이 통로를 왕복하며 수평·수직으로 동시에 움직인다. 승강장치와 포크장치가 달린 핵심 입출고 장치이며 컴퓨터로 저장·반출한다.","src":"기출 2021-13, 2023-16, 2024-31, 2026-12"},{"t":"트래버서(Traverser): 스태커 크레인을 다른 통로로 옮겨 주는 횡행 장치.","src":"기출 2023-16 / 보충(추정)"},{"t":"무인반송차(AGV): 무인으로 물품을 운반·이동한다. 고정경로 혹은 유도방식으로 보관/반출 품목을 입출고 컨베이어와 연결한다.","src":"기출 2023-16, 2024-30, 2026-12"},{"t":"보관단위(Unit): 파렛트형, 버킷형, 레인형, 셀형.","src":"기출 2023-16"},{"t":"셀(Cell): 랙 속에서 화물이 저장되는 단위 공간.","src":"기출 2026-12"}]},{"머리":"운행 명령 방식","줄":[{"t":"단일명령(Single Command): 스태커 크레인이 1회 운행에 입고나 출고 중 하나만 수행한다.","src":"기출 2021-13, 2026-12"},{"t":"이중명령(Dual Command): 1회 운행으로 저장과 반출을 모두 수행한다.","src":"기출 2021-13, 2026-12"}]},{"머리":"저장위치 할당 방식 전체","줄":[{"t":"임의위치저장(Randomized Storage): 입출고 빈도와 상관없이 빈 위치에 임의로 저장한다. 전체 저장 소요 공간이 적다.","src":"기출 2021-13, 2024-11, 2026-13"},{"t":"지정위치저장(Dedicated Storage): 품목별 저장 소요 공간과 단위시간당 평균 입출고 횟수를 고려해 저장위치를 미리 지정한다. 소요 공간이 임의위치저장보다 크거나 같다.","src":"기출 2024-11, 2026-13"},{"t":"등급별저장(Class-based Storage): 입출고 빈도 기준으로 등급을 나누고, 빈도 높은 등급을 입출고점 가까이 둔다. 같은 등급 안에서는 임의위치저장을 쓴다.","src":"기출 2024-11, 2026-13"},{"t":"근거리 우선저장(Closest Open Location Storage): 입출고점에 가장 가까운 빈 곳부터 할당한다.","src":"기출 2026-13"}]},{"머리":"계산: 가동률","줄":[{"t":"가동률 = 처리 소요시간 ÷ 가용시간. 이중명령 1회는 저장 1건과 반출 1건을 처리한다.","src":"기출 2024-10"},{"t":"풀이 순서: ① 전체 지시(저장+반출) 건수 ② 이중명령 비율만큼 쌍으로 묶어 이중명령 횟수 ③ 나머지는 단일명령 횟수 ④ 횟수×사이클 시간 합 ÷ 60분.","src":"기출 2024-10"},{"t":"예(2024-10): 저장 10+반출 10=20건. 이중 60% → 12건=6회×5분=30분. 단일 8회×3분=24분. 합계 54분 ÷ 60분 = 90%.","src":"기출 2024-10"}]},{"머리":"계산: 저장소요공간","줄":[{"t":"임의위치저장 소요공간 = 기간별 전 품목 필요공간 합계 중 최댓값.","src":"기출 2026-33"},{"t":"지정위치저장 소요공간 = 품목별 기간 최대 필요공간의 합.","src":"기출 2026-33"},{"t":"예(2026-33): 주별 합 105·104·107·106·110 → 임의 110. 품목별 최대 A26·B25·C22·D36·E26 → 지정 135.","src":"기출 2026-33"}]},{"머리":"AS/RS 개념·도입배경·특징","줄":[{"t":"자동화창고(AS/RS): 화물의 입·출고, 저장, 검수, 분류작업 등을 컴퓨터가 자동으로 조작하는 창고이다.","src":"이론"},{"t":"스태커 크레인 제어를 반자동 또는 자동으로 하는 입체자동창고와 입체기계화창고를 총칭한다. 최근에는 고층 랙을 쓰는 무인입체 자동창고로 발전하고 있다.","src":"이론"},{"t":"도입배경: 인력절감, 다품종 소량주문 대응과 배송 신속화, 토지사용 효율 증대, 지가 상승으로 고층 입체 자동화 창고 필요, 제조부문 자동화와 균형, 저장형 창고에서 유통형 창고로의 기능 변화.","src":"이론"},{"t":"특징: 단위화·규격화된 물품 보관으로 효율적 재고관리와 선입선출 입출고관리, 다품종 소량주문·다빈도 배송 대응, 생산라인과의 동기성·적정재고·부품 공급기능, 프리 로케이션으로 공간 절감과 시스템 유연성.","src":"이론"},{"t":"특징: 보관보다 물품의 흐름에 중점을 두고 설계한다. 고층 적재로 단위면적당 보관효율이 좋다. 처리할 물품의 치수·포장·중량을 고려해 설계한다.","src":"이론"},{"t":"장점: 작업효율 향상·인력 절감·하역비 절감, 정확한 입출고와 재고관리, 고층화·입체화로 보관효율 향상, 선입선출의 정확성, 제품의 안정적 관리.","src":"이론"},{"t":"단점: 다양한 규격의 화물을 취급하는 창고에는 맞지 않는다. 화물 형태·종류·화물량·창고 위치가 바뀌면 유연성이 떨어진다. 일부 기계가 고장 나면 전체 시스템에 영향을 준다. 기존 건물에 설치하기 어렵다. 초기 투자비용이 많이 든다.","src":"이론"},{"t":"스태커 크레인: 주행장치·승강장치·포크장치로 구성된 입출고 기기이다. 수동·반자동·자동식이 있다. 제품 종류가 많고 회전수가 높을 때 바람직한 보관하역시스템이다.","src":"이론"},{"t":"대기점(home position): 스태커 크레인의 대기 장소. 컨베이어: 화물의 연속이동장치. 버킷: 화물의 입출고·보관용 상자. 랙: 화물 적재용 선반 구조물.","src":"이론"},{"t":"트래버서: 스태커 크레인을 횡으로 이동시키는 장치. 무인반송차(AGV): 화물을 목적 장소까지 이동시키는 자동주행장치.","src":"이론"}]},{"머리":"운행 명령 방식·계산 보충","줄":[{"t":"단일명령은 입고나 출고를 별도 지시에 따라 분리해 한 가지씩 수행한다. 이중명령은 입고를 마친 뒤 출고명령을 받아 해당 파렛트를 싣고 입출고점으로 돌아온다.","src":"이론"},{"t":"시간당 처리개수: 단일명령은 60분 ÷ 단일시간. 이중명령은 60분 ÷ 이중시간 × 2개(왕복 2개 처리). 단일·이중 횟수 비율로 가중평균한다. 가동률이 주어지면 마지막에 곱한다.","src":"이론"},{"t":"예(이론): 단일 2분, 이중 3.2분, 단일횟수가 이중횟수의 2배. 30×2/3 + 37.5×1/3 = 32.5개.","src":"이론"},{"t":"예(2020-20): 단일 2분(시간당 30개), 이중 3.5분(60÷3.5×2≈34.3개), 단일횟수 3배, 가동률 95%. (30×3/4 + 34.3×1/4)×0.95 ≈ 29.5 → 정답 30개.","src":"기출 2020-20"},{"t":"평균가동률 예(이론): 단일 3분, 이중 5분, 시간당 입고·출고 각 10건, 이중 80%. 단일 10×20%×3×2=12분, 이중 10×80%×5=40분. (12+40)÷60=86.7%.","src":"이론"}]},{"머리":"로케이션 관리·저장위치 보충","줄":[{"t":"로케이션: 배치된 지역·위치에 주소를 부여하는 것이다. 방법은 프리, 존, 고정, 혼합형 로케이션이 있다.","src":"이론"},{"t":"프리 로케이션(Free Location): 품목과 랙 사이에 특별한 연관관계를 정하지 않는다. 저회전율 물품에 주로 적용한다.","src":"이론"},{"t":"존 로케이션(Zone Location): 일정 품목군에 보관 구역을 정하고, 구역 안에서는 프리 로케이션을 쓰는 절충식이다.","src":"이론"},{"t":"고정 로케이션(Fixed Location): 선반번호마다 품목을 정해 보관한다. 수작업으로 관리하는 경우가 많고 고회전율 물품에 적용한다.","src":"이론"},{"t":"혼합형 로케이션(Free & Fixed): 일부는 프리, 일부는 고정 로케이션으로 운영하는 절충형이다.","src":"이론"},{"t":"임의위치저장은 지정위치저장보다 편리하고 공간을 집약적으로 쓴다. 정확도 측면에서는 한계가 있다.","src":"이론"},{"t":"지정위치저장은 임의위치저장보다 전체적으로 공간이 여유 있어야 한다.","src":"이론"},{"t":"저장소요공간 예(이론): 주별 3품목 합이 51·73·76·57·53·89이면 임의위치 89㎡. 품목별 최대 A34·B25·C35의 합 94㎡가 지정위치.","src":"이론"},{"t":"예(2020-19): 월별 4품목 합 80·66·67·65·77 → 임의위치 80. 품목별 최대 A27·B22·C20·D23 → 지정위치 92.","src":"기출 2020-19"}]}],"함정":[{"x":"스태커 크레인(Stacker Crane): 창고의 통로 공간을 수평 방향으로만 움직이는 저장/반출 기기이다.","o":"스태커 크레인: 랙 사이 통로를 수평 방향과 수직 방향으로 함께 움직이는 저장/반출 기기이다.","src":"기출 2021-13 / 기출 2024-31, 2026-12"},{"x":"단일명령(Single Command) 방식: 1회 운행으로 저장과 반출 작업을 동시에 수행 하는 방식이다.","o":"단일명령 방식: 1회 운행에 저장 또는 반출 중 하나만 수행한다.","src":"기출 2021-13 / 기출 2026-12"},{"x":"이중명령(Dual Command) 방식: 2회 운행으로 저장과 반출 작업을 순차적으로 모두 수행하는 방식이다.","o":"이중명령 방식: 1회 운행으로 저장과 반출을 모두 수행한다.","src":"기출 2021-13 / 기출 2026-12, 2024-10"},{"x":"지정위치저장(Dedicated Storage) 방식: 물품의 입출고 빈도를 기준으로 저장위치를 등급(Class)으로 나누고 등급별로 저장위치를 결정하는 방식이다.","o":"지정위치저장 방식: 품목마다 저장위치를 고정해 둔다. 입출고 빈도로 등급을 나누어 등급별로 위치를 정하는 것은 등급별저장 방식이다.","src":"기출 2021-13 / 기출 2024-11, 2026-13"},{"x":"트래버서(Traverser)는 보관품의 입출고 시 작업장부터 랙까지 연결시켜주는 반송장치이다.","o":"트래버서(Traverser): 스태커 크레인을 다른 통로로 옮겨 주는 횡행 장치이다. 작업장에서 랙까지 연결 반송하는 것은 컨베이어·AGV 등이다.","src":"기출 2023-16 / 보충(추정)"},{"x":"등급별저장(class-based storage)방식은 보관품목의 단위당 경제적 가치를 기준 으로 등급을 설정한다.","o":"등급별저장은 입출고 빈도(회전율)를 기준으로 등급을 나눈다.","src":"기출 2024-11 / 기출 2026-13"},{"x":"이중명령(Dual Command) 방식: 스태커 크레인이 입고나 출고를 2개씩 수행하는 방식이다.","o":"이중명령 방식: 스태커 크레인이 1회 운행으로 입고와 출고를 각 1건씩 함께 수행한다.","src":"기출 2026-12 / 기출 2024-10, 2026-12"},{"x":"트래버서: 보관품의 입출고 시 작업장부터 랙까지 연결시켜 주는 반송장치(2023-16)","o":"트래버서는 스태커 크레인을 통로 간 옮기는 장치이다. 작업장-랙 연결은 컨베이어·AGV가 한다.","src":"기출 2023-16 / 보충(추정)"},{"x":"지정위치저장 방식: 입출고 빈도를 기준으로 등급으로 나누고 등급별로 저장위치를 결정","o":"그 설명은 등급별저장이다.","src":"기출 2021-13"},{"x":"등급별저장 방식은 단위당 경제적 가치를 기준으로 등급을 설정한다.","o":"입출고 빈도(회전율)를 기준으로 등급을 설정한다.","src":"기출 2024-11"},{"x":"트래버서(Traverser)는 화물을 지정된 입출고 지점까지 수직으로 이동시키는 자동 주행장치이다.","o":"트래버서는 스태커 크레인을 횡으로 이동시키는 장치이다. 화물을 입출고 지점까지 수직으로 이동시키는 것은 스태커 크레인이다.","src":"기출 2020-14"},{"x":"자동화창고는 물류의 흐름보다는 보관에 중점을 두고 설계해야 한다.","o":"자동화창고는 보관보다 물류의 흐름에 중점을 두고 설계한다.","src":"기출 2020-15"}]},"#8":{"묶음":[{"머리":"오더피킹 방식 전체","줄":[{"t":"1인 1건 피킹(싱글 오더 피킹): 피커 한 사람이 주문 전표 1건에 요구된 물품을 모두 피킹한다.","src":"기출 2024-17, 2026-15"},{"t":"일괄 오더 피킹: 여러 건의 주문 전표를 모아 한꺼번에 피킹한다.","src":"기출 2021-10, 2024-17"},{"t":"총량 오더 피킹: 여러 주문을 합산해 품목별 총량을 한 번에 피킹하고 주문별로 나눈다. 1건의 주문마다 모으는 방식이 아니다.","src":"기출 2024-17 / 보충"},{"t":"존(Zone) 피킹: 피커마다 담당 구역(선반 작업범위)을 정해 두고 자기 구역의 물품만 피킹한다.","src":"기출 2021-10, 2024-17"},{"t":"릴레이(Relay) 피킹: 전표에서 해당 피커가 담당하는 품목(분담한 물품 종류)만 피킹하고 다음 피커에게 넘긴다.","src":"기출 2021-10, 2024-17, 2026-15"},{"t":"디지털 피킹(DPS): 전표 없이 피킹하는 방식. 다품종 소량·다빈도 피킹에 효과적이다.","src":"기출 2021-10, 2026-18"},{"t":"차량탑승피킹: 피킹트럭에 탑승해 피킹한다. 보관시설의 공간활용도가 높다.","src":"기출 2021-10 / 보충(추정)"}]},{"머리":"DPS · DAS","줄":[{"t":"DPS(Digital Picking System): 피킹 대상 품목 수량을 디지털 표시기에 표시해 피킹하도록 지원한다.","src":"기출 2023-15, 2026-18"},{"t":"DPS 구성: 표시장치(수량표시부)와 응답장치. 표시된 수량만큼 피킹한 뒤 완료버튼을 누른다.","src":"기출 2026-18"},{"t":"DPS는 작동방식에 따라 대차식, 구동 컨베이어식, 무구동 컨베이어식으로 나눈다.","src":"기출 2023-15"},{"t":"DPS는 소품종 대형·소빈도가 아니라 다품종 소량·다빈도 품목에 효과적이다.","src":"기출 2021-10, 2026-18"},{"t":"DAS(Digital Assorting System): 분배할 물품의 순서에 따라 작업자에게 분류정보를 제공해 신속한 분배를 지원한다.","src":"기출 2023-15"},{"t":"멀티 다품종 DAS: 많은 고객에게 배송하기 위한 분배 과정을 지원하며 합포장에 적합하다.","src":"기출 2023-15"}]},{"머리":"자동분류시스템","줄":[{"t":"분류시스템: 화물을 품종별·발송처별·고객별·목적지별로 식별·구분한다. 소량·다빈도 배송 요구가 늘며 중요도가 커진다.","src":"기출 2021-34"},{"t":"분류 방식 중 동작에 의한 분류: 밀어내는 방식, 다이버트 방식, 이송 방식, 틸트 방식. 바코드 방식은 동작에 의한 분류가 아니다.","src":"기출 2024-36, 2025-34"},{"t":"팝업(Pop-up) 방식: 컨베이어 아래의 롤러·휠·체인 사이 분기장치가 올라와 물품을 들어 올려 방향을 바꾼다. 하부면 손상에 약한 화물에는 부적합하다.","src":"기출 2021-11, 2023-38, 2026-35"},{"t":"푸시오프(Push-off) 방식: 분류지점에 직각 방향으로 암(Arm)을 설치해 밀어낸다.","src":"기출 2023-38"},{"t":"슬라이딩슈(Sliding-shoe) 방식: 반송면 아래 슈가 단위화물과 함께 이동하면서 압출한다. 전환 흐름이 부드러워 손상 가능성이 낮다.","src":"기출 2021-11, 2023-38, 2025-13"},{"t":"크로스벨트(Cross-belt) 방식: 레일을 주행하는 연속된 캐리어 위 소형 벨트컨베이어를 레일과 교차하는 방향으로 구동해 분류한다.","src":"기출 2022-29, 2023-38, 2026-35"},{"t":"틸팅(Tilting) 방식: 트레이·슬라이드 등을 경사지게 해 화물을 떨어뜨려 분류한다. 트레이 틸팅은 고속 주행 트레이를 기울인다.","src":"기출 2021-11, 2025-13, 2026-35"},{"t":"다이버터(Diverter) 방식: 안내판·바를 설치해 화물이 가로막혀 방향을 바꾸게 한다. 다양한 형상의 화물을 분류할 수 있고 구조가 팝업보다 단순하다.","src":"기출 2021-11, 2022-29, 2026-35"},{"t":"다이버터 바 스윙 방식: 컨베이어 측면에 바를 설치해 목적방향으로 화물을 이동시킨다.","src":"기출 2026-35"}]},{"머리":"오더피킹 개념·자동화·방식 보충","줄":[{"t":"오더피킹: 보관 중인 재고에서 거래처로부터 수주받은 물품을 주문별로 모아 피킹(꺼내는 것)해 출하하는 과정이다. 넓은 의미로는 서류의 흐름, 물품의 피킹·정돈·포장, 배송지역별 차량 적재까지 포함한다.","src":"이론"},{"t":"오더피킹의 가장 중요한 과제: 고객의 주문내역과 일치하도록 상품을 모아 지정한 납기일 내에 배송하는 것이다.","src":"이론"},{"t":"오더피킹 자동화 시 고려사항: 취급화물의 형상·규격·중량, 피킹 규모, 적용기기의 성능, 투자대비 효과.","src":"이론"},{"t":"싱글 오더 방식: 1건의 주문마다 물품을 피킹해 모은다. 1인 1건 방식이나 릴레이 방식으로도 할 수 있다.","src":"이론"},{"t":"총량 피킹: 일정 기간(몇 시간 또는 하루)의 주문전표를 한데 모아 피킹한다. 한곳에 모은 전표의 물품을 1인이 전부 피킹하며 릴레이식·그룹식이 있다. 물품의 무게만 피킹하는 방식이 아니다.","src":"이론"},{"t":"사람/피킹 방식(인력): 피커가 보관 장소를 순회하며 피킹한다. 다품종 소량 피킹에 많이 쓰나 물품 파악이 어렵고 시간이 오래 걸린다.","src":"이론"},{"t":"기계/피킹 방식: 물품을 사람에게 오게 하는 방법이다. 회전선반, 미니로드시스템을 쓴다.","src":"이론"},{"t":"씨뿌리기(파종) 방식: 품목별로 일괄 피킹해 거래처별로 뿌리는 분류방식이다. 따내기(거두기) 방식: 주문 거래처별 순으로 피킹한다.","src":"이론"},{"t":"DPS는 따내기방식을 디지털 시스템화한 것이고, DAS는 씨뿌리기방식을 디지털 시스템화한 것이다.","src":"이론"},{"t":"어소트(assort) 방식: 집하된 물품을 주문별로 배분하는 방식이다.","src":"이론"}]},{"머리":"오더피킹 출고유형별 장비","줄":[{"t":"출고유형 7가지: ① 파렛트→파렛트(P→P) ② 파렛트→파렛트+케이스(P→P+C) ③ 파렛트→케이스(P→C) ④ 케이스→케이스(C→C) ⑤ 케이스→케이스+단품(C→C+SC) ⑥ 케이스→단품(C→SC) ⑦ 단품→단품(SC→SC).","src":"이론"},{"t":"유형 2(P→P+C) 장비: 스태커 크레인, 파렛트 피킹포크 등.","src":"이론"},{"t":"유형 3(P→C) 장비: MH 로봇, 컨베이어, 피킹크레인, 피킹용 포크리프트, 파렛트 슬라이딩 랙과 컨베이어.","src":"이론"},{"t":"유형 5(C→C+SC)는 유형 4와 유형 6을 조합한 형태이다. 유형 6(C→SC)은 수작업과 기계를 적절히 활용하며 손수레·대차를 쓴다.","src":"이론"},{"t":"유형 7(SC→SC): 다품종 소량 피킹이며 자동화가 어렵다.","src":"이론"},{"t":"유형 1(P→P) 장비: 파렛트 랙, 파렛트 슬라이딩 랙, 드라이브인 랙, 캐로셀 포크리프트, 스태커 크레인, 트랜스 로보시스템. 유형 4(C→C) 장비: 슬라이딩 랙(회전선반), 자동 슬라이딩 랙, 캐로셀 미니 스태커 크레인, 모빌 랙.","src":"이론"}]},{"머리":"DPS · DAS 보충","줄":[{"t":"DPS: 피킹할 물품·품목수를 컴퓨터와 디지털 표시기로 보여 주어 작업전표 없이 피킹한다. 물품보관셀에 표시기를 설치하고 작업자가 표시량만큼 피킹한다.","src":"이론"},{"t":"DPS 도입효과: 다품종 소량·다빈도 피킹 화물에 유리, 품목 증가·변경에도 정확, 피킹 신속·정확, 작업자 교체 시 혼란 감소와 갑작스런 물량 대응, 적량 적기 공급.","src":"이론"},{"t":"DPS 중 대차식 DPS의 초기 설치비가 가장 적게 든다.","src":"이론"},{"t":"DAS: 동일한 제품을 피킹한 후 거래처별로 분배하는 시스템이다. 디지털 표시기에 표시된 수량만큼 뿌리는(분배하는) 방식이며 별도 작업지시서가 필요 없다.","src":"이론"},{"t":"DAS는 물품을 주문별로 분배하는 파종식, DPS는 주문별로 피킹하는 채취식으로 볼 수 있다.","src":"이론"},{"t":"DAS 장점: 적은 인원으로 빠른 분배가 가능해 물류비용 절감, 소품종 대량출하에 적합. 단점: 보관장소와 주문별 분배장소가 별도로 필요하다.","src":"이론"},{"t":"멀티 분배 DAS: 고객별 주문상품을 합포장하기에 적합하다. 멀티 다품종분배 DAS: 아이템 수가 많은 의류업 품목처럼 많은 고객에게 배송할 때 분배를 지원하고 합포장에 적합하다. 잔량표시로 박스 수를 줄일 수 있다.","src":"이론"},{"t":"멀티 릴레이 분배 DAS: 냉장·신선식품, 생산형 물류센터의 입고수량을 통로별·점포별로 분배한다.","src":"이론"}]},{"머리":"분류시스템·분류기 보충","줄":[{"t":"분류(sorting): 개개의 정보를 가진 물품을 그 정보에 따라 구분해 정해진 장소에 모으는 작업이다. 미국 운반관리협회 정의: 특정 목적지로 운반할 제품을 식별·구분하고 유도하는 행위.","src":"이론"},{"t":"분류시스템 도입배경: 다품종·소량·다빈도·다배송처로 분류의 중요성이 커졌다. 물류 속도를 높여 고객 요구에 대처하고, 다량의 물품을 단시간에 수동 분류할 때 생기는 오류를 줄이려고 도입한다.","src":"이론"},{"t":"다이버터 방식: 외부 안내판(Arm)을 회전시켜 컨베이어에 가이드 벽을 만들어 이동시킨다. 화물 형상과 관계없이 분류할 수 있고 팝업 방식보다 구조가 단순하다.","src":"이론"},{"t":"팝업 방식(돌출롤러 방식): 여러 롤러·휠 등을 이용해 물품이 특정 위치를 지날 때 분기장치가 들어 올려 방향을 바꾼다. 컨베이어 아래에서 벨트·롤러·휠·핀 등이 튀어나온다. 화물 하부면에 충격을 주는 단점이 있다.","src":"이론"},{"t":"틸팅 방식(경사트레이 방식): 레일을 주행하는 트레이·슬라이드 일부를 경사지게 해 화물을 떨어뜨린다. 우체국·통신판매에서 많이 쓴다. 고속처리가 가능하나 중력에 의한 파손품이 생길 수 있다.","src":"이론"},{"t":"크로스벨트 방식: 레일 위를 주행하는 연속된 캐리어(소형 벨트컨베이어 장착)를 레일과 교차하는 방향으로 구동하는 고속 분류방식이다. 통신판매·의약품·화장품에 많이 쓴다.","src":"이론"},{"t":"밀어내는 방식(Pusher Type): 암(Arm)으로 컨베이어 흐름 방향에 직각으로 화물을 밀어낸다.","src":"이론"},{"t":"슬랫 컨베이어 방식: 컨베이어에서 이동하는 슬랫으로 밀어서 분류한다. 충격이 커서 깨지기 쉬운 물건에는 부적합하다.","src":"이론"},{"t":"저개방식은 레일을 주행하는 트레이 등의 바닥면을 개방해 단위화물을 방출한다.","src":"기출 2020-27"},{"t":"저개방식은 레일을 주행하는 트레이 등의 바닥면을 개방해 단위화물을 방출한다(저개식 소팅 컨베이어).","src":"기출 2020-27"}]}],"함정":[{"x":"차량탑승피킹: 파렛트 단위로 피킹하는 유닛로드시스템(Unit Load System)이며, 피킹트럭에 탑승하여 피킹함으로써 보관시설의 공간활용도가 낮다.","o":"차량탑승피킹: 피킹트럭에 탑승해 고층 랙에서 피킹하므로 보관시설의 공간활용도가 높다.","src":"기출 2021-10 / 보충(추정)"},{"x":"다이버터(Diverter) 방식은 팝업 방식에 비하여 구조가 상대적으로 복잡하다.","o":"다이버터 방식은 가이드벽·바로 방향을 바꾸는 단순한 구조이고 팝업 방식이 구조가 상대적으로 복잡하다.","src":"기출 2021-11 / 기출 2021-11"},{"x":"크로스벨트(Cross belt) 방식: 컨베이어 반송면의 아래 방향에서 벨트 등의 분기장 치가 나오는 방식으로 하부면의 손상 및 충격에 취약한 화물에는 적합하지 않다.","o":"크로스벨트 방식: 레일을 주행하는 캐리어 위 소형 벨트컨베이어를 교차 방향으로 구동해 분류한다. 아래에서 분기장치가 나오는 것은 팝업 방식이다.","src":"기출 2022-29 / 기출 2022-29, 2023-38, 2026-35"},{"x":"팝업(Pop-up) 방식: 레일을 주행하는 연속된 캐리어 상의 소형벨트 컨베이어를 레일과 교차하는 방향으로 구동시켜 단위화물을 내보내는 방식이다.","o":"팝업 방식: 컨베이어 아래에서 휠·체인 등 분기장치가 올라와 방향을 바꾼다. 소형벨트를 교차 구동하는 것은 크로스벨트 방식이다.","src":"기출 2022-29 / 기출 2023-38, 2026-35"},{"x":"틸팅(Tilting) 방식: 반송면에 튀어나온 기구를 넣어 단위화물을 함께 이동시키면 서 압출하는 방식이다.","o":"틸팅 방식: 트레이·슬라이드 등을 기울여 화물을 떨어뜨린다. 반송면의 기구가 화물과 함께 이동하며 압출하는 것은 슬라이딩슈 방식이다.","src":"기출 2022-29 / 기출 2023-38, 2025-13"},{"x":"슬라이딩슈(Sliding-shoe) 방식: 여러 형상의 화물을 수직으로 나누어 강제적으 로 분류하므로 충격에 취약한 정밀기기나 깨지기 쉬운 물건은 피해야 한다.","o":"슬라이딩슈 방식은 화물을 부드럽게 전환시켜 손상 가능성이 낮다.","src":"기출 2022-29 / 기출 2021-11"},{"x":"멀티 릴레이 DAS는 주문 단위로 출하박스를 투입하여 피킹하는 방식으로 작업 자의 이동이 최소화된다.","o":"멀티 릴레이 DAS: 구역별 작업자가 이어서 분배하는 방식으로 이 설명은 어울리지 않는다.","src":"기출 2023-15 / 출제 오답(바른 설명 미확인)"},{"x":"틸팅 방식(Tilting Type)은 벨트, 트레이, 슬라이드 등의 바닥면을 개방하여 물품을 분류한다.","o":"틸팅 방식은 트레이·벨트·슬라이드 등을 기울여 분류한다. 바닥면을 개방하는 방식과는 다르다.","src":"기출 2023-38 / 기출 2025-13, 2026-35 / 보충(추정)"},{"x":"다이버터 푸셔 방식(Diverter Pusher Type)은 컨베이어 하부에 푸셔(Pusher)를 설치하여 분류지점에 화물이 위치하면 푸셔로 화물을 들어올려 방향을 전환시켜 주는 방식이다.","o":"다이버터 푸셔 방식은 컨베이어 측면에서 푸셔로 화물을 밀어 방향을 바꾼다. 하부에서 들어올리는 것은 팝업 방식이다.","src":"기출 2026-35 / 기출 2026-35 / 보충(추정)"},{"x":"총량 오더 피킹: 1건의 주문마다 물품을 피킹해서 모으는 방법","o":"1건 주문마다 모으는 것은 1인 1건 피킹이다. 총량 피킹은 여러 주문의 품목을 합쳐 한 번에 피킹한다.","src":"기출 2024-17"},{"x":"DPS는 대형품목 소빈도 피킹에 효과적이다.","o":"다품종 소량·다빈도 피킹에 효과적이다.","src":"기출 2026-18"},{"x":"바코드 방식이 동작에 의한 분류 방식이다.","o":"동작 분류는 밀어내기·다이버트·이송·틸트이다.","src":"기출 2024-36, 2025-34"},{"x":"슬라이딩슈 방식은 정밀기기나 깨지기 쉬운 물건은 피해야 한다.","o":"슬라이딩슈는 전환이 부드러워 손상 가능성이 낮다.","src":"기출 2021-11"},{"x":"컨베이어 하부에서 푸셔로 화물을 들어올려 방향을 전환(다이버터 푸셔)","o":"하부에서 들어 올리는 것은 팝업 방식이다.","src":"기출 2026-35 / 보충(추정)"},{"x":"팝업방식(Pop-up Type)은 컨베이어 반송면의 아래에서 벨트, 롤러, 휠, 핀 등의 분기장치가 튀어나와 단위화물을 내보내는 방식으로, 하부면의 손상 및 충격에 약한 화물에도 적합하다.","o":"팝업 방식은 화물 하부면에 충격을 주는 단점이 있어 하부면 손상과 충격에 약한 화물에는 적합하지 않다.","src":"기출 2020-27"},{"x":"팝업 방식(Pop-up Type): 화물을 컨베이어의 흐르는 방향에 대해서 직각 암(Arm)으로 밀어내는 방식이다.","o":"암으로 직각 방향으로 밀어내는 것은 밀어내는(Pusher) 방식이다. 팝업 방식은 아래에서 분기장치가 튀어나온다.","src":"이론"},{"x":"슬라이딩 슈 방식: 컨베이어 반송면 아래 방향에서 벨트, 롤러, 휠, 핀 등의 분류장치가 튀어나와 화물을 내보낸다.","o":"그 설명은 팝업 방식이다.","src":"이론"},{"x":"다이버터 방식: 레일을 주행하는 연속된 소형 벨트 컨베이어를 레일과 교차하는 방향에서 구동시켜 화물을 내보낸다.","o":"그 설명은 크로스벨트 방식이다. 다이버터는 암을 회전시켜 가이드벽을 만든다.","src":"이론"},{"x":"밀어내는 방식(Pusher Type): 컨베이어 아래 방향에서 벨트, 롤러, 휠, 핀 등의 분기장치가 튀어나와 분류한다.","o":"그 설명은 팝업 방식이다.","src":"이론"},{"x":"총량피킹 방식이란 일정량에 해당되는 화물의 무게만을 피킹하는 방식이다.","o":"총량피킹은 몇 시간 또는 하루 동안의 주문전표를 한데 모아 피킹하는 방식이다.","src":"이론"}]},"#9":{"묶음":[{"머리":"WMS의 기능","줄":[{"t":"WMS(Warehouse Management System): 입출고관리, 재고 및 로케이션관리, 반품관리, 물류센터 지표관리를 종합 수행한다.","src":"기출 2025-14, 2026-17"},{"t":"입고관리·위치관리·재고관리·출고관리 기능.","src":"기출 2025-14"},{"t":"랙(Rack)·셀(Cell)별 재고를 실시간으로 관리한다.","src":"기출 2023-14"},{"t":"정확한 위치정보로 창고 내 피킹·포장작업을 지원한다.","src":"기출 2023-14"},{"t":"입고 후 보관의 원칙에 따라 최적 장소를 골라 저장한다.","src":"기출 2023-14"},{"t":"물동량 증감에 따른 인력계획 수립과 모니터링을 지원한다.","src":"기출 2023-14"},{"t":"피킹관리, 주문진척관리, 자동발주시스템 같은 주문관련 기능을 수행한다.","src":"기출 2025-14"},{"t":"전사적 자원관리시스템(ERP)과 연계해 자동화 범위를 넓히고 정보 가용성을 높인다.","src":"기출 2025-14"},{"t":"시설운영의 효율적 관리와 공간·설비 활용도가 향상된다.","src":"기출 2025-14"},{"t":"WMS 도입 효과: 피킹·출하 효율이 높아지고, 운송수단과의 연계가 쉬워지고, 입하·검품이 쉬워지고, 로케이션 관리가 쉬워진다. 화물파손 위험은 낮아진다.","src":"기출 2024-16"},{"t":"고객 주문내역의 운송수단을 고려한 최적 경로 설정은 WMS 기능이 아니다(TMS).","src":"기출 2023-14 / 보충"},{"t":"자동발주시스템은 EOS, 유연생산시스템은 FMS, 통합생산관리시스템은 MES, 디지털분배시스템은 DAS이다.","src":"기출 2026-17"},{"t":"WMS: 제품의 입하·입고·피킹·출하·재고관리 등 창고 비즈니스 프로세스와 창고의 직접 활동을 효율적으로 관리하는 시스템이다. 공간효율 최대화와 입고 프로세스 자동화로 운반관리(Material Handling)를 효율화한다.","src":"이론"},{"t":"등장배경: 다품종 소량상품화·고객요구 다양화·물류 아웃소싱 확대, 화주 요구에 빠른 대응을 위한 물류센터 대형화, 유통중심형 물류센터의 차별화 전략, 자동화·정보화·지능화 요구, SCM 등장과 IT 발달.","src":"이론"},{"t":"도입효과: 단위화·규격화 물품 보관으로 효율적 재고관리, 정확한 입출고관리와 선입선출, 자동화로 생산성·효율성 개선, 재고량과 재고관련비용 감소, 재고 투명성으로 공급사슬 효율 향상, 입출고 업무 시스템화로 작업시간·인력 절감, ERP 연계, 고단적재로 보관효율 극대화.","src":"이론"},{"t":"WMS 특징: 소품종 대량생산보다 통제가 어려운 다품종 소량생산 품목의 창고관리에 지원이 더 필요하다. RFID·바코드 같은 자동인식 장치, 무선통신, 자동 제어 기술을 쓴다.","src":"이론"},{"t":"WMS로 재고정확도, 공간·설비 활용도, 제품처리능력, 재고회전율, 고객서비스율, 노동·설비 생산성이 향상된다.","src":"이론"},{"t":"WMS는 주문관리시스템(OMS), 운송관리시스템(TMS), 하역시스템(MHS), DPS, DAS와 연계해 기능을 극대화한다. 초기 설비투자가 막대해 신중한 준비와 계획이 필요하다.","src":"이론"},{"t":"WMS 기능 분류: 재고관련(입고관리·보관관리·선입선출관리·위치관리), 주문관련(피킹관리·자동발주), 출고관련(수·배송관리·배차 스케줄 운영), 관리관련(인력관리·물류센터 지표관리), 인터페이스(무선통신·실시간 정보화).","src":"이론"},{"t":"입고관리·보관관리·재고관리·선입선출관리는 재고(보관)관련 기능이다. 주문관련 기능이 아니다.","src":"이론"},{"t":"WMS 구축단계: 관련부서와 T/F추진팀 구성 → 요구분석 → 효과분석 → 사양정의 → 대안평가 → 업체선정 → 개발설치 → 운영.","src":"이론"},{"t":"입고관리, 출고관리, 재고관리 등 업무를 효율적으로 지원한다.","src":"기출 2020-16"},{"t":"WMS는 설비 활용도와 노동 생산성을 높이고 재고량과 재고관련비용을 줄인다.","src":"기출 2020-16"}]},{"머리":"WMS 패키지(기성제품) 구매 시 고려요인","줄":[{"t":"커스터마이징 용이성, 초기투자비용, 기존 자사 물류정보시스템과의 연계성, 유지보수비용.","src":"기출 2021-15"},{"t":"기성제품의 개발 배경은 고려 요인이 아니다.","src":"기출 2021-15"}]},{"머리":"물류센터 작업 계획 수립 세부 항목","줄":[{"t":"화물 형태: 포장 여부, 포장 방법, 소요 설비.","src":"기출 2022-11"},{"t":"하역 방식: 하역 자동화 수준, 하역 설비 종류·규격.","src":"기출 2022-11"},{"t":"검수 방식: 검수 기준, 검수 작업 방법, 소요 설비.","src":"기출 2022-11"},{"t":"피킹 및 분류: 피킹 기준, 피킹 방법, 소팅 설비.","src":"기출 2022-11"},{"t":"평치·선반·특수 시설 사용 여부는 보관 방식 항목이다. 출하 차량 동선 항목의 내용이 아니다.","src":"기출 2022-11 / 보충(추정)"}]},{"머리":"물류센터 운영 효과","줄":[{"t":"리드타임 단축으로 고객 만족도가 오른다.","src":"기출 2024-5"},{"t":"적정 재고량을 유지하면서 고객니즈에 맞는 서비스를 제공한다.","src":"기출 2024-5"},{"t":"물류센터 수가 늘면 총 안전재고량과 납기준수율이 모두 증가한다.","src":"기출 2024-5"},{"t":"물류센터 운영 전에 비해 공차율이 감소한다.","src":"기출 2024-5"}]},{"머리":"크로스 도킹(Cross Docking)","줄":[{"t":"입고된 물품을 보관하지 않고 바로 출고하는 방식.","src":"기출 2024-13, 2025-11 / 보충"},{"t":"재고 회전율이 증가하고 재고수준·리드타임이 감소한다. 유통업체의 불필요한 재고를 줄인다.","src":"기출 2024-13, 2025-11"},{"t":"장기적으로 센터의 저장 공간을 줄일 수 있다. 기계설비 보강과 정보기술 도입 투자가 필요할 수 있다.","src":"기출 2024-13"},{"t":"입고 품목의 출하지가 알려져 있을 때 더 효과적이다.","src":"기출 2024-13"},{"t":"파렛트 크로스 도킹은 기계설비와 정보기술의 적용이 필요하다. 공급처와 수요처의 정보공유가 필요하다.","src":"기출 2025-11"}]},{"머리":"물류센터 업무·작업공정","줄":[{"t":"물류센터 작업 순서: 입하 → 격납(인입) → 보관 → 피킹 → 검품 → 포장 → 출하.","src":"이론"},{"t":"입하(receive): 물류센터에 물자가 들어오는 것. 반입 물자의 수령·검품·검수와 보관 또는 필요 부문에 배분하는 것을 뜻한다.","src":"이론"},{"t":"예비포장: 공급처에서 입하된 물품을 단품 단위로 포장하는 것이다.","src":"이론"},{"t":"인입(격납, putaway): 입하된 물품을 저장 공간에 옮겨 두는 행위. 물자 취급, 보관 위치 확인, 적치를 포함한다.","src":"이론"},{"t":"보관(storage): 주문을 기다리는 동안 물자를 물리적으로 저장해 두는 행위. 보관방법은 재고품목의 크기·수량·제품이나 용기의 취급조건 등으로 정한다.","src":"이론"},{"t":"피킹: 보관 중인 물품을 꺼내는 작업이다. 특정 주문에 맞춰 선별해 출하를 위한 후속 공정으로 넘긴다. 효율화를 위해 DPS·DAS·피킹카트 등을 도입한다.","src":"이론"},{"t":"포장(packaging): 피킹 업무에 이어지는 선택적 절차이다. 개별 품목 단위 또는 세트 단위로 용기에 담거나 포장한다.","src":"이론"},{"t":"분류(sorting): 피킹된 품목을 고객별·거래처별·지역별로 구분한다. 공수가 많이 들어 기계화·자동화가 필요하다.","src":"이론"},{"t":"단위화 및 적하·출하는 물류센터 업무의 마지막 단계이다.","src":"이론"},{"t":"라인밸런싱: 각 작업공정과 작업자 사이의 작업량을 균등하게 할당해 여유시간과 바쁜 시간이 섞이지 않도록 작업시간을 평준화한다. 목적은 공정 내 재공품 감소, 가동률·리드타임 향상, 애로(병목)공정 개선이다.","src":"이론"},{"t":"공정효율 = 공정별 사이클타임 합계 ÷ (애로공정 사이클타임 × 공정수) × 100.","src":"이론"},{"t":"예: 사이클타임 A13·B25·C17·D21분. 합 76분, 애로공정 B 25분, 공정수 4 → 76÷(25×4)=76%.","src":"이론"},{"t":"가동률 = 실제 작업시간 ÷ 총작업시간 × 100. 입하작업공수비율 = 입하작업시간 ÷ 총작업시간 × 100.","src":"이론"}]},{"머리":"크로스 도킹 보충","줄":[{"t":"크로스도킹: 공급처에서 수령한 물품을 물류센터에서 재고로 보관하지 않고 바로 출하하는 시스템이다. 보관·피킹 작업을 없애 물류비를 줄이고 회전율을 높이며 재고수준과 리드타임을 줄인다.","src":"이론"},{"t":"효율적 운영 조건: 제품 수요가 일정하고 안정적이며 재고품절비용이 낮을 때, 입하 시 출하지를 알고 있을 때, 선적장소가 적거나 입하화물이 대량이고 일일처리량이 많을 때.","src":"이론"},{"t":"크로스도킹으로 보관·하역·수배송·창고관리 프로세스를 단축·개선한다. 효율적 실현에는 사전출하명세서(ASN)와 JIT 환경이 필요하다.","src":"이론"},{"t":"크로스도킹 운영방식: 공급업체가 미리 분류·포장하는 기포장방식, 물류센터에서 분류·출고하는 중간처리방식.","src":"기출 2020-12"},{"t":"ASN(Advanced Shipping Notice, 사전출하명세서): 물류센터 입고 상품의 수량과 내역이 사전에 물류센터로 송달되는 정보이다. 신속·정확한 검품과 적재에 쓴다.","src":"기출 2020-13"}]},{"머리":"물류센터 KPI","줄":[{"t":"환경 KPI: CO2 절감 등 환경 측면의 공헌도를 관리한다.","src":"기출 2020-25"},{"t":"생산성 KPI: 작업인력과 시간당 생산성을 파악해 작업을 개선한다.","src":"기출 2020-25"},{"t":"납기 KPI: 수주부터 납품까지의 기간을 측정해 리드타임을 줄인다.","src":"기출 2020-25"},{"t":"품질 KPI: 오납율·사고율 등 물류품질 수준을 파악해 고객서비스 수준을 높인다.","src":"기출 2020-25"},{"t":"비용 KPI: 작업마다 비용을 파악해 물류센터의 물류비용을 줄인다.","src":"기출 2020-25"}]}],"함정":[{"x":"고객주문내역 상의 운송수단을 고려한 최적의 경로를 설정하여 비용과 시간을 절감하도록 지원한다.","o":"WMS는 창고 내부 입고·보관·피킹·출고를 관리한다. 운송수단을 고려한 최적 경로 설정은 운송관리시스템(TMS)의 기능이다.","src":"기출 2023-14 / 보충"},{"x":"각각의 공장에서 소비지까지 제품을 개별 수송하므로 손상, 분실, 오배송이 감소 한다.","o":"물류센터를 거치면 공장별 개별 수송 대신 통합 수송을 하므로 손상·분실·오배송이 줄어든다는 서술이어야 한다. 제시문은 개별 수송을 전제로 한 오답.","src":"기출 2024-5 / 기출 2024-5 / 보충"},{"x":"물류센터의 재고 회전율이 감소한다.","o":"크로스도킹은 재고 회전율을 높이고 재고수준·리드타임을 줄인다.","src":"기출 2024-13 / 기출 2024-13, 2025-11"},{"x":"기존의 독립된 구매관리시스템, 생산관리시스템, 인사관리시스템 및 영업관리 시스템을 통합하여 관리한다.","o":"구매·생산·인사·영업관리 시스템을 통합 관리하는 것은 ERP이다. WMS는 창고 업무를 다룬다.","src":"기출 2025-14 / 기출 2025-14 / 보충"},{"x":"WMS 도입으로 화물파손에 대한 위험성이 높아진다.","o":"화물파손 위험성은 낮아진다.","src":"기출 2024-16"},{"x":"기성제품(패키지)의 개발 배경(WMS 패키지 구매 시 고려 요인으로)","o":"고려 요인이 아니다. 커스터마이징·초기투자비·연계성·유지보수비를 본다.","src":"기출 2021-15"},{"x":"출하 차량 동선 - 평치, 선반 및 특수 시설의 사용 여부(작업 계획 세부 고려사항)","o":"평치·선반 사용 여부는 보관 방식 항목이다.","src":"기출 2022-11 / 보충(추정)"},{"x":"일일 처리량이 적을 때 적합한 방식은 파렛트 크로스 도킹이다.","o":"출제 오답(바른 구분 미확인)","src":"기출 2025-11"},{"x":"물류센터의 재고관리비용은 낮추면서 재고 수준을 증가시킬 수 있다.","o":"크로스도킹은 재고수준을 크게 줄이므로 재고관리비용도 낮아진다.","src":"기출 2020-12"},{"x":"설비 활용도와 노동 생산성을 높이며, 재고량과 재고관련비용을 증가시킨다.","o":"WMS는 재고량과 재고관련비용을 감소시킨다.","src":"기출 2020-16"},{"x":"납기 KPI는 수주부터 납품까지의 기간을 측정하여 리드타임을 증가시키기 위한 지표이다.","o":"납기 KPI는 리드타임을 줄이기 위한 지표이다.","src":"기출 2020-25"},{"x":"WMS의 주문관련 기능은 입고관리, 보관관리, 재고관리, 선입선출관리 등이다.","o":"그것들은 재고(보관)관련 기능이다. 주문관련 기능은 피킹관리와 자동발주(주문진척관리)이다.","src":"이론"},{"x":"물품 보관셀에 표시기를 설치하고 피킹작업자가 방문하여 표시량만큼 피킹하는 것은 DAS이다.","o":"그 설명은 DPS이다. DAS는 피킹한 물품을 거래처별로 분배한다.","src":"이론"}]},"#10":{"묶음":[{"머리":"집중구매 · 분산구매","줄":[{"t":"집중구매방식: 본사가 공통품목을 일괄 구매한다. 대량 구매가 가능하고 가격·거래조건이 유리하다.","src":"기출 2021-23, 2022-18, 2024-21"},{"t":"집중구매방식은 구입 절차를 표준화하기 쉽고, 공통자재의 표준화·단순화가 가능하다.","src":"기출 2024-21"},{"t":"집중구매방식은 수요량이 많은 품목, 수량할인이 있는 품목에 적합하다.","src":"기출 2021-23, 2022-18"},{"t":"분산구매방식: 사업장별 독립적 구매가 가능하고, 사업장의 특수한 요구를 반영하기 쉽다.","src":"기출 2022-18, 2024-21"},{"t":"분산구매방식은 긴급수요에 대처하기 유리하다.","src":"기출 2024-21"}]},{"머리":"MRP(자재소요계획)","줄":[{"t":"MRP는 주생산계획(MPS)을 기초로 완제품 생산에 필요한 자재·구성부품의 종류·수량·시기를 계획한다.","src":"기출 2024-19, 2025-16"},{"t":"MRP 입력: 주생산계획, 자재명세서(BOM), 재고기록파일.","src":"기출 2024-19, 2025-16"},{"t":"MRP는 소요자재를 언제 발주할지 알려 준다. 재고수준의 최소화를 목표로 한다.","src":"기출 2024-19"},{"t":"MRP를 확장해 사업계획과 부문별 계획을 연결한 것이 제조자원계획(MRP II)이다.","src":"기출 2024-19"},{"t":"원자재·반제품 등 모든 자재의 소요량을 산정해 조달계획을 세운다.","src":"기출 2025-16"},{"t":"기업 내 모든 인적·물적 자원의 통합관리는 ERP의 설명이다.","src":"기출 2025-16"},{"t":"정리·정돈·청소·청결·습관화(5S)는 MRP가 아니다.","src":"기출 2025-16"}]},{"머리":"계산: 순소요량","줄":[{"t":"순소요량 = 총소요량 − 예정입고량 − 가용재고.","src":"기출 2023-20, 2025-26"},{"t":"부품 총소요량 = 완제품 소요량 × 완제품 1개당 부품 수.","src":"기출 2023-20, 2025-26"},{"t":"예(2023-20): K 50개, X 2개/Y 3개 구성. X=100−10−5=85, Y=150−20−0=130.","src":"기출 2023-20"},{"t":"예(2025-26): A 60개, X 3개/Y 4개. X=180−20−10=150, Y=240−30=210.","src":"기출 2025-26"}]},{"머리":"구매관리 의의","줄":[{"t":"구매관리: 자재의 최적구매를 위해 계획·조정·통제·평가하는 일련의 과정이다. 필요한 자재를 적절한 공급자에게서 적절한 품질로 적절한 시기에 필요한 수량만큼 최소 비용으로 입수하는 관리활동이다.","src":"이론"},{"t":"구매관리 전제조건: 용도에 맞는 적정품 구입, 납기 관리, 적정재고관리로 결품 방지, 우량업체 선정(구매 시장조사), 적절한 수송수단, 최저 구매비용, 사용 중 발생한 잔재의 활용.","src":"이론"},{"t":"집중구매: 각 부서가 필요로 하는 자재의 주문을 한 업체에 집중시켜 대량으로 구매한다. 분산구매: 각 사업장(부서)마다 필요한 물품을 자율적으로 구매한다.","src":"이론"}]},{"머리":"집중구매·분산구매 비교","줄":[{"t":"집중구매 적용 품목: 전사공통품목, 표준품목, 수요가 높은 품목, 구매량별 가격차가 큰 품목.","src":"이론"},{"t":"집중구매 장점: 교섭력 증대로 가격·거래조건이 유리하고, 절차가 복잡한 구매(수입자재 등)에 유리하며, 시장조사·거래처조사와 구매효과 측정이 쉽다.","src":"이론"},{"t":"집중구매 단점: 각 구매부서의 자주성이 없고 수속이 복잡하다. 긴급조달이 곤란하다. 각 공장별 재고상황 파악이 곤란하다. 조달기간과 운임이 늘어난다.","src":"이론"},{"t":"분산구매 적용 품목: 시장성 품목, 가격차 없는 품목, 소량·소액 품목, 사무소모품, 수리부속품.","src":"이론"},{"t":"분산구매 장점: 자주적 구매, 사업장의 특수요구 반영, 긴급한 수요에 유리, 구매수속 신속 처리.","src":"이론"},{"t":"분산구매 단점: 본사 방침과 다른 자재를 사는 경우가 생긴다. 구입경비가 많이 들고 구입단가가 비싸다. 구입처와 거리가 멀면 적절한 자재구입이 곤란하다.","src":"이론"},{"t":"분산구매방식은 사무용 소모품처럼 구매지역에 따라 가격 차이가 없는 품목에 쓴다.","src":"기출 2020-39"},{"t":"집중구매방식은 절차가 복잡한 수입물자 구매 등에 쓴다.","src":"기출 2020-39"}]},{"머리":"MRP 보충","줄":[{"t":"MRP: 제품의 생산수량·일정을 토대로 원자재·부품·조립품의 소요량과 소요시기를 역산해 조달계획과 일정관리를 하는 재고관리법이다. 종속수요품목의 소요량과 소요시기를 결정한다.","src":"이론"},{"t":"MRP는 최종 제품의 독립수요를 추정하고, 그에 따른 구성부품의 종속수요를 필요한 때 필요한 양만큼 보유하려는 것이다.","src":"이론"},{"t":"상위품목의 생산계획이 바뀌면 부품 수요량과 재고보충시기를 쉽게 갱신할 수 있다. 예측오차와 불확실성에 대비한 안전재고가 필요하다.","src":"이론"},{"t":"MRP는 제조준비비용과 재고유지비용이 균형을 이루도록 로트 크기를 정한다. 우선순위계획은 착수순서와 실시시기를 정한다.","src":"이론"},{"t":"MRP 목적: 적시·적량·적소 공급으로 과잉재고와 재고부족을 해결해 재고비용을 극소화한다.","src":"이론"},{"t":"MRP는 계획생산에 입각한 푸시(push) 방식이다. 조립·부품 생산시간이 짧고 신뢰할 수 있을 때, 확고한 기준일정이 있을 때, 생산·제작 규모 변화가 없을 때 더 유효하다.","src":"이론"},{"t":"MRP 계산순서: ① 총소요량(BOM·MPS 기준) ② 현재고 산출(기초재고 − 계획된 수주량) ③ 순소요량 = 총소요량 − 현재고 ④ 발주량 결정 ⑤ 발주일자 결정(조달기간 고려).","src":"이론"},{"t":"예: A 1개 = X 3개 + Y 2개, A 순소요량 50개. X 총 150, 가용재고 45 → 105. Y 총 100, 가용재고 50+입고예정 15=65 → 35.","src":"이론"},{"t":"MRP II(Manufacturing Resource Planning): 원자재뿐 아니라 생산에 필요한 모든 자원을 관리하는 MRP의 확대 개념이다. 재고관리·생산현장관리·자재소요관리를 하나의 시스템으로 통합한다.","src":"이론"},{"t":"ERP(전사적 자원관리): 설계·생산·물류·재무·영업·회계·인사 등 여러 시스템을 유기적으로 연결해 정보를 공유하고 자원을 관리한다.","src":"이론"},{"t":"DRP(유통자원계획): 생산 완료된 제품을 수요처에 효율적으로 공급하는 시스템. 주요 산출물은 물류망의 최적 단계수이다. DRP·IP·Deployment 3가지로 구성한다.","src":"이론"},{"t":"DRP 도입효과: 고객 수요정보를 예측해 제품 재고수준을 낮춘다. 정시 배송을 늘리고 고객 불만을 줄여 고객서비스를 높인다.","src":"이론"}]}],"함정":[{"x":"분산구매방식은 본사의 공통품목을 일괄적으로 구매하기에 적합하다.","o":"집중구매방식이 본사의 공통품목을 일괄 구매하기에 적합하다.","src":"기출 2021-23 / 기출 2021-23, 2024-21"},{"x":"집중구매방식은 분산구매방식보다 사업장별 독립적 구매가 가능하다.","o":"분산구매방식이 집중구매방식보다 사업장별 독립적 구매가 가능하다.","src":"기출 2021-23 / 기출 2021-23"},{"x":"분산구매방식은 구매량에 따라 가격차가 큰 품목의 대량 구매에 적합하다.","o":"구매량에 따라 가격차가 큰 품목의 대량 구매는 집중구매방식에 적합하다.","src":"기출 2021-23 / 기출 2021-23"},{"x":"분산구매방식은 집중구매방식 보다 대량 구매가 이루어지기 때문에 가격 및 거래 조건이 유리하다.","o":"집중구매방식이 분산구매방식보다 대량 구매라 가격·거래 조건이 유리하다.","src":"기출 2021-23 / 기출 2021-23, 2024-21"},{"x":"사업장별 다양한 요구를 반영하여 구매하기에 용이하다.","o":"사업장별 다양한 요구를 반영하기 쉬운 것은 분산구매방식이다.","src":"기출 2022-18 / 기출 2024-21"},{"x":"사업장별 독립적 구매에 유리하나 수량할인이 있는 품목에는 불리하다.","o":"집중구매방식이 수량할인이 있는 품목에 유리하다.","src":"기출 2022-18 / 기출 2021-23, 2024-21"},{"x":"전사적으로 집중구매하기 때문에 가격 및 거래조건이 불리하다.","o":"집중구매는 대량 구매라 가격 및 거래조건이 유리하다.","src":"기출 2022-18 / 기출 2024-21"},{"x":"구매절차의 표준화가 가능하여 긴급조달이 필요한 자재의 구매에 유리하다.","o":"집중구매는 구매절차 표준화에 유리하지만 긴급조달에는 불리하다. 긴급수요에 유리한 쪽은 분산구매이다.","src":"기출 2022-18 / 기출 2024-21"},{"x":"MRP는 재고수준의 최대화를 목표로 한다.","o":"MRP는 재고수준의 최소화를 목표로 한다.","src":"기출 2024-19 / 기출 2024-19"},{"x":"분산구매방식은 긴급수요에 대처하기 불리하다.","o":"분산구매방식은 긴급수요에 대처하기 유리하다.","src":"기출 2024-21 / 기출 2022-18, 2024-21"},{"x":"집중구매방식(Centralized Purchasing Method)은 구매절차 표준화가 용이하며, 자재의 긴급조달에 유리하다.","o":"집중구매는 긴급조달이 곤란하다. 긴급수요에 유리한 쪽은 분산구매이다.","src":"기출 2020-39"},{"x":"MRP시스템은 칸반(Kanban)으로 자재의 제조명령·구매주문을 가시적으로 통제하고, JIT시스템은 컴퓨터로 정교한 정보처리를 한다.","o":"칸반은 JIT의 도구이고, MRP가 컴퓨터로 정교한 정보처리를 한다.","src":"이론"}]},"#11":{"묶음":[{"머리":"정성적 예측방법 전체","줄":[{"t":"정성적: 델파이법, 시장조사법, 패널조사법, 역사적 유추법, 라이프사이클 유추법, 경영자판단법, 판매원이용법, 전문가조사법.","src":"기출 2021-29, 2022-21, 2023-24, 2026-24"},{"t":"델파이법: 전문가들에게 설문을 반복해 의견을 모으는 방법.","src":"기출 2021-29, 2026-24 / 보충"},{"t":"시장조사법: 설문지·현장인터뷰 등으로 소비자 자료를 수집·분석해 가설을 검증한다. 신제품이나 새로운 시장에 소개되는 제품에 많이 쓴다.","src":"기출 2023-24, 2025-19"},{"t":"라이프사이클 유추법: 상품 수명주기 기간별 과거 매출 증감 폭을 기준으로 수요량을 유추한다.","src":"기출 2022-21"},{"t":"역사적 유추법: 유사 제품의 과거 자료로 신제품의 수요를 정성적으로 예측한다.","src":"기출 2025-19 / 보충"},{"t":"전문가조사법은 타협이나 절충으로 예측 정확도가 낮아질 수 있다.","src":"기출 2025-19"}]},{"머리":"정량적 예측방법 전체","줄":[{"t":"정량적: 시계열분석(이동평균법, 가중이동평균법, 지수평활법)과 인과모형(회귀분석).","src":"기출 2021-29, 2022-21, 2023-24, 2024-18, 2026-24"},{"t":"단순이동평균법: 예측 기간 직전 일정 기간의 시계열 평균값으로 예측한다.","src":"기출 2023-24"},{"t":"가중이동평균법: 먼 과거는 낮은 가중치, 가까운 과거는 높은 가중치를 준다.","src":"기출 2022-21, 2023-24, 2025-19"},{"t":"지수평활법: 관찰된 실제수요와 이전 예측치에 가중치를 두어 새 예측치를 구한다.","src":"기출 2025-19"},{"t":"회귀분석: 원인과 결과 관계를 가진 두 요소의 과거 변화량으로 인과관계를 분석하는 정량적 방법.","src":"기출 2021-29, 2022-21, 2026-24"}]},{"머리":"시계열의 구성요소","줄":[{"t":"수준(level): 추세·계절·순환·무작위 요인을 제외한 평균적 수요량.","src":"기출 2024-18"},{"t":"추세(trend): 수요가 계속 증가하거나 감소하는 경향.","src":"기출 2024-18"},{"t":"계절적(seasonal) 요인: 수요 변화가 규칙적으로 반복되는 현상.","src":"기출 2024-18"},{"t":"순환적(cyclical) 요인: 수년 단위 경기 변동 같은 장기 반복 변화. 단기 불규칙 변화는 무작위 요인.","src":"기출 2024-18 / 보충"}]},{"머리":"계산: 수요예측","줄":[{"t":"지수평활법: 새 예측치 = 이전 예측치 + α × (실제 − 이전 예측치) = α×실제 + (1−α)×이전 예측치.","src":"기출 2021-20, 2022-19, 2024-20, 2025-27, 2026-23"},{"t":"풀이 순서: 조건에 해당 월 실제·예측이 모두 주어졌는지 확인. 한 달씩 순서대로 전개한다.","src":"기출 2022-19, 2025-27"},{"t":"예(2021-20): 55,400+0.6×(56,900−55,400)=56,300.","src":"기출 2021-20"},{"t":"예(2022-19): 7월 예측 50,000+0.4×(48,000−50,000)=49,200. 8월 49,200+0.4×(52,000−49,200)=50,320.","src":"기출 2022-19"},{"t":"예(2024-20): 110,000+0.2×(100,000−110,000)=108,000.","src":"기출 2024-20"},{"t":"예(2025-27): 7월 94,000+0.3×4,000=95,200. 8월 95,200+0.3×(92,000−95,200)=94,240.","src":"기출 2025-27"},{"t":"예(2026-23): 9월 5,000+0.2×(5,500−5,000)=5,100. 직전 달 실제(7월)는 쓰지 않는다.","src":"기출 2026-23"},{"t":"단순이동평균(n=3) = 최근 3기 합 ÷ 3. 예(2021-22): (36+34+37)÷3=35.7.","src":"기출 2021-22"},{"t":"가중이동평균 = Σ(가중치×실적). 예(2021-22): 0.5×37+0.3×34+0.2×36=35.9.","src":"기출 2021-22"},{"t":"예(2021-22) 지수평활: 39+0.4×(37−39)=38.2.","src":"기출 2021-22"}]},{"머리":"수요예측 일반","줄":[{"t":"수요예측은 장·단기 계획 수립의 기초자료이다. 재고감축·품절예방, 원활한 생산계획, 안정적 구매조달, 원가절감, 고객서비스 개선을 위해 가장 먼저 고려한다.","src":"이론"},{"t":"수요에 영향을 주는 요인: 경기변동, 제품수명주기, 광고·판매활동, 품질, 경쟁업체 가격, 고객의 신뢰와 태도.","src":"이론"},{"t":"예측기간별: 단기예측은 보통 6개월 이내(월별·주별·일별), 중기예측은 6개월~2년 이내, 장기예측은 대개 2년 이상.","src":"이론"}]},{"머리":"정량적·정성적 기법 비교","줄":[{"t":"정량적 기법: 수치로 측정된 통계자료에 기초해 계량적으로 예측한다. 인과형 모형(회귀분석)과 시계열 분석(평균법, 지수평활법)으로 나눈다. 주로 단기 예측에 쓴다.","src":"이론"},{"t":"정성적 기법: 개인의 주관·판단이나 다수 전문가 의견으로 예측한다(델파이법, 유추법, 시장조사법, 패널동의법 등). 과거 자료가 충분치 않거나 신뢰할 수 없을 때 유용하다. 주로 중·장기 예측에 쓴다.","src":"이론"},{"t":"시계열분석법은 단기수요 예측에 유용하다. 인과형모형은 시간 이외의 특정 요인이 수요와 인과관계를 가진다고 가정한다.","src":"이론"},{"t":"추세분석법: 시계열을 관통하는 추세선을 구해 그 선상에서 미래 수요를 예측한다.","src":"이론"},{"t":"이동평균법: 매기 앞으로 이동하면서 일정 기간 수요를 평균해 예측한다. 경기변동·계절변동을 충분히 알 수 없다. 단순이동평균은 이동평균기간이 짧을수록 최근 수요변화를 많이 반영한다.","src":"이론"},{"t":"지수평활법: 현시점에 가까운 실적치에 큰 가중치를 준다. 평활상수가 클수록 최근 실적에 큰 비중을 둔다. 수요변동이 크거나 성장률이 높은 제품은 평활상수를 크게 한다.","src":"이론"},{"t":"회귀분석: 독립변수(원인, 예 인구수)의 변화에 따른 종속변수(결과, 예 물류량)의 관계를 선형 직선식으로 산정한다. 상관계수가 ±1에 가까울수록 모형의 신뢰성이 높다.","src":"이론"},{"t":"투입-산출 모형: 산업의 산출량·가격 변화가 다른 산업에 미치는 영향을 예측한다. 계량경제모형·시뮬레이션모형도 정량적 모형이다.","src":"이론"},{"t":"델파이법: 전문가 집단에게 여러 차례 설문지를 돌려 의견을 수렴한다. 시간과 비용이 많이 들지만 불확실성이 크거나 과거 자료가 없을 때 유용하다. 장기예측·기술예측에 맞는다.","src":"이론"},{"t":"전문가 의견법(panel consensus): 전문가들이 의견을 자유롭게 교환해 일치된 결과를 얻는다. 단기간에 저렴하게 예측한다. 패널동의법·경영자 판단법·판매원 예측법이 여기에 든다.","src":"이론"},{"t":"시장조사법: 설문지·직접 인터뷰·전화 조사·시제품 발송으로 소비자 의견을 조사해 가설을 검증한다. 정성적 기법 중 시간과 비용이 가장 많이 들지만 비교적 정확하다.","src":"이론"},{"t":"수명주기 유추법은 역사적 유추법(historical analogy)이라고도 한다.","src":"이론"}]},{"머리":"계산: 수요예측 보충","줄":[{"t":"회귀식 예측: 독립변수 값을 회귀식 y=ax+b에 대입한다. 예: y=0.9886x−0.8295, x=6.3 → 5.399(약 5.4).","src":"이론"},{"t":"예(2020-34): 발문의 평활상수는 0.2(정답 60,560에서 역산). 6월 예측 = 60,000+0.2×(56,000−60,000)=59,200. 7월 예측 = 59,200+0.2×(66,000−59,200)=60,560.","src":"기출 2020-34"},{"t":"지수평활법은 한 달 건너뛰지 않고 월별로 이어서 계산한다. 7월 예측에는 6월 예측치와 6월 실제치가 들어간다.","src":"기출 2020-34"}]}],"함정":[{"x":"델파이법(Delphi Method)은 원인과 결과관계를 가지는 두 요소의 과거 변화량에 대한 인과관계를 분석한 방법으로 정량적 수요예측방법에 해당한다.","o":"델파이법은 전문가 설문을 반복해 합의를 구하는 정성적 방법이다. 원인-결과 관계를 분석하는 것은 회귀분석 등 인과모형이다.","src":"기출 2022-21 / 기출 2021-29, 2026-24"},{"x":"지수평활법은 예측하고자 하는 기간의 직전 일정 기간의 시계열 평균값을 활용 하여 산출하는 방법이다.","o":"지수평활법은 실제수요와 직전 예측치에 가중치를 두어 새 예측치를 구한다. 직전 일정 기간 평균은 이동평균법이다.","src":"기출 2023-24 / 기출 2025-19"},{"x":"순환적(cyclical) 요인은 단기간에 발생하는 불규칙한 수요변화이다.","o":"순환적 요인은 수년 단위의 경기 변동에 따른 수요 변화이다. 단기간의 불규칙한 변화는 무작위(불규칙) 요인이다.","src":"기출 2024-18 / 보충"},{"x":"시계열분석법은 기존 제품과 관련된 과거의 자료를 분석하여 신제품의 미래 수요를 정성적으로 예측하는 방법이다.","o":"신제품의 미래 수요를 유사 제품의 과거 자료로 정성적으로 예측하는 것은 역사적 유추법이다. 시계열분석법은 정량적 방법이다.","src":"기출 2025-19 / 기출 2023-24, 2024-18"},{"x":"회귀분석법이 정성적 수요예측 기법이다.","o":"회귀분석은 정량적(인과모형) 기법이다.","src":"기출 2021-29, 2026-24"},{"x":"이동평균법·선형 회귀분석이 정성적 예측방법이다(2026-24 ㄱ, ㄹ).","o":"둘 다 정량적 방법이다.","src":"기출 2026-24"}]},"#12":{"묶음":[{"머리":"EOQ 모형의 가정","줄":[{"t":"수요는 확정적이고 일정하다. 조달기간(리드타임)이 일정하다.","src":"기출 2022-17, 2024-25, 2025-17, 2026-19"},{"t":"주문량은 전량 일시에 입고된다. 단일 품목이다.","src":"기출 2022-17, 2024-25, 2025-17, 2026-19"},{"t":"재고부족(품절)을 허용하지 않는다. 미납주문도 없다.","src":"기출 2025-17, 2026-19"},{"t":"주문비용과 단가는 주문량과 무관하게 일정하다. 수량할인이 없다.","src":"기출 2022-17, 2024-25"},{"t":"재고유지비용은 단위당 일정하고 평균재고량(주문량)에 비례한다. 주문량에 반비례하지 않는다.","src":"기출 2022-17, 2024-25, 2025-17, 2026-19"},{"t":"1회 주문비용은 주문량에 관계없이 일정하다.","src":"기출 2025-17"}]},{"머리":"공식","줄":[{"t":"EOQ = √(2 × 연간수요량 D × 1회 주문비용 S ÷ 단위당 연간 재고유지비용 H).","src":"기출 2021-21, 2022-20, 2023-19, 2025-25, 2026-22"},{"t":"EOQ에서 연간 주문비용(D/Q×S)과 연간 재고유지비용(Q/2×H)이 같고, 총재고비용은 둘의 합이다.","src":"기출 2022-20"},{"t":"연간 발주횟수 = D ÷ EOQ.","src":"기출 2022-20"},{"t":"재고유지비용 = 평균재고량 × 단가 × 재고유지비율. 단가 5%·재고 10,000개·5,000원이면 2,500,000원.","src":"기출 2023-22, 2025-24"},{"t":"EPQ = √(2DS ÷ (H × (1 − d/p))). d=일일 소비량, p=일일 생산량.","src":"기출 2024-22, 2026-20"},{"t":"재주문점 ROP = 리드타임 중 평균수요(일평균수요×리드타임) + 안전재고.","src":"기출 2022-22, 2025-23"},{"t":"안전재고 = Z × 일수요 표준편차 × √리드타임.","src":"기출 2022-22, 2026-21"},{"t":"EOQ가 알려져 있을 때 1회 주문비용 S = EOQ² × H ÷ (2D).","src":"기출 2026-22"}]},{"머리":"계산 풀이","줄":[{"t":"예(2021-21): D 4,000→6,400(60%↑), H 75→60(20%↓). EOQ는 √(1.6÷0.8)=√2≈1.414배, 약 41% 증가.","src":"기출 2021-21"},{"t":"예(2022-20): D 90,000, H=80,000×25%=20,000, S 160,000 → EOQ=1,200. 총재고비용=600×20,000+75×160,000=24,000,000원. 발주 75회.","src":"기출 2022-20"},{"t":"예(2022-22): 일수요 14,000÷350=40, 리드타임 9일 → 360. 안전재고 1.282×20×√9≈77. ROP=437.","src":"기출 2022-22"},{"t":"예(2023-19): √(2×20,000×80,000÷(4,000×0.2))=2,000개.","src":"기출 2023-19"},{"t":"예(2024-22): D 2,700, S 400,000, H 13,500, d=9, p=12 → √(2×2,700×400,000÷(13,500×0.25))=800톤.","src":"기출 2024-22"},{"t":"예(2025-23): 200×3+400=1,000개.","src":"기출 2025-23"},{"t":"예(2025-25): √(2×1,200×60,000÷900)=400개.","src":"기출 2025-25"},{"t":"예(2026-20): √(2×3,600×100,000÷(36,000×0.5))=200개.","src":"기출 2026-20"},{"t":"예(2026-21): 1.5×250×√16=1,500개.","src":"기출 2026-21"},{"t":"예(2026-22): 4,000²×500÷(2×100,000)=40,000원.","src":"기출 2026-22"}]},{"머리":"발주 시스템","줄":[{"t":"정량발주시스템(Q시스템, 연속점검시스템): 재고수준을 연속적으로 검토하고 주문량이 일정하다.","src":"기출 2024-24, 2025-18, 2026-25"},{"t":"정기발주시스템(P시스템): 재고수준 파악과 발주를 정기적으로 하고, 목표수준에 도달하도록 발주량을 정한다. 정량발주보다 안전재고가 많다.","src":"기출 2024-24 / 보충"},{"t":"기준재고시스템(s-S): 보유재고가 s보다 적어지면 최대재고량 S에 도달하도록 발주량을 정한다.","src":"기출 2024-24"},{"t":"확률적 정량발주법: 주문량이 일정하고 Q시스템이며 수요가 불확실할 때 쓰고 연속실사로 재고를 조사한다.","src":"기출 2026-25"},{"t":"재주문점 기법: 정량발주법, Two-Bin법, 기준재고법, 정기발주법. 델파이법은 수요예측 기법이다.","src":"기출 2023-23"}]},{"머리":"재고관리 비용·기법 분류","줄":[{"t":"주문비용(발주비용): 자재·부품을 살 때 주문에 따라 드는 비용이다. 주문 서류비, 통신비, 검사비, 입고비, 통관료, 운송비 등.","src":"이론"},{"t":"재고유지비용: 재고를 보유·유지하는 데 드는 비용이다. 이자비용, 창고료, 보험료, 감가상각비, 진부화비용, 세금 등.","src":"이론"},{"t":"재고부족비용: 재고부족으로 생기는 생산중단, 판매기회 상실, 신용하락 등의 손실이다.","src":"이론"},{"t":"총재고비용 = 주문비용 + 재고유지비용 + 재고부족비용.","src":"이론"},{"t":"준비비용: 재고품을 자체 생산할 때 드는 비용(노무비, 자재·공구 교체비, 원료 준비). EPQ 산정 때 고려한다.","src":"이론"},{"t":"재고관리기법 분류: 고정주문량 모형(정량발주: EOQ, EPQ, 투빈시스템, 단일기간 재고모형), 고정주문기간 모형(정기발주), 절충모형(미니-맥스 시스템, s·S System), 기타(ABC 재고관리, MRP, JIT).","src":"이론"},{"t":"재고수준: 운영재고는 조달기간 중 필요한 자재의 수요 예측량이다. 적정재고 = 운영재고 + 안전재고. 운영재고 수준은 가용자금, 보관시설, 재고회전율, 재고의 보충 빈도 등으로 정한다.","src":"이론"},{"t":"재고일수 = 현재 재고수량(금액) ÷ 일일평균출하량(금액).","src":"이론"}]},{"머리":"EOQ 보충","줄":[{"t":"EOQ: Harris가 제시한 확정적 모형 중 고정주문량 모형이다. 연간 재고유지비용과 재고주문비용을 더한 연간 재고비용을 최소로 하는 1회 주문량을 정한다.","src":"이론"},{"t":"EOQ는 연간 재고유지비용과 주문비용이 같아지는 1회 주문량이다. EOQ 모형에서 안전재고는 0이다.","src":"이론"},{"t":"ATC(연간총비용) = Ch×Q/2 + O×D/Q. Ch는 연간 단위당 재고유지비용, O는 1회 주문비용, D는 연간수요량, Q는 1회 주문량.","src":"이론"},{"t":"ATC를 Q로 미분해 0으로 놓으면 EOQ = √(2×D×O ÷ Ch).","src":"이론"},{"t":"최적 주문횟수 = D ÷ EOQ. 최적 주문주기 = EOQ ÷ D(년). 평균재고량 = EOQ ÷ 2.","src":"이론"},{"t":"1회 주문량이 늘면 주문횟수가 줄고 연간 주문비용도 준다.","src":"이론"},{"t":"예: D 50,000개, 1회 주문비 4,000원, 단위 재고유지비 100원 → EOQ=√(2×4,000×50,000÷100)=2,000개. 주문횟수 50,000÷2,000=25회.","src":"이론"},{"t":"변수 변화 예: 수요 1,000→2,000(2배), 재고유지비 10%→80%(8배) → EOQ는 √(2÷8)=0.5배, 50% 감소.","src":"이론"},{"t":"총재고비용(EOQ 기준) = EOQ÷2×H + D÷EOQ×S. 단가×수요(구입비)는 더하지 않는다.","src":"기출 2020-31"},{"t":"예(2020-31): D 2,000, H=1,000×10%=100, S 4,000 → EOQ=400. 총재고비용 = 400÷2×100 + 2,000÷400×4,000 = 20,000+20,000 = 40,000원.","src":"기출 2020-31"},{"t":"예(2020-37): D 40,000, H=2,000×20%=400, S 20,000 → EOQ=√(2×40,000×20,000÷400)=2,000개. 연간 발주횟수 40,000÷2,000=20회.","src":"기출 2020-37"}]},{"머리":"EPQ 보충","줄":[{"t":"EPQ(경제적 생산량): 재고를 주문하지 않고 수요량을 고려해 자체 생산해 보충할 때 비용을 최소로 하는 생산량이다. 제조기업 대상이다.","src":"이론"},{"t":"EPQ 가정: 재고준비비는 생산량과 관계없이 로트마다 일정, 재고유지비는 생산량에 정비례, 생산단가는 일정, 수요량(D)과 생산능력(P)은 일정(생산능력이 수요량보다 큼), 생산품은 생산기간 중 순차적으로 생산·입고.","src":"이론"},{"t":"EPQ = EOQ × √(P ÷ (P−D)). 생산능력 P가 무한대이면 EPQ = EOQ.","src":"이론"},{"t":"예: D 1,000,000, 준비비 200원, 유지비 100원, P 무한대 → EPQ=EOQ=√(2×1,000,000×200÷100)=2,000개.","src":"이론"},{"t":"예: 생산능력이 수요의 2배(P=2D) → EPQ=EOQ×√2=1.414배. 4배(P=4D) → EOQ×√(4/3)=1.155배. 따라서 (1.155−1.414)÷1.414 ≈ −18%, 약 18% 감소.","src":"이론"}]},{"머리":"재주문점·안전재고 보충","줄":[{"t":"ROP(재주문점)법: 재고수준이 일정 수준으로 내려가면 발주한다. 발주점을 통계적으로 정할 때 수요분포는 정규분포를 따른다.","src":"이론"},{"t":"ROP = 조달기간 중 판매량 + 안전재고 = 일일수요량 × 리드타임 + 안전재고. 정량발주법은 재주문점과 발주량을 정해야 한다.","src":"이론"},{"t":"안전재고 = 안전계수 × 수요의 표준편차 × √조달기간. 서비스율 95%(결품률 5%)의 안전계수는 1.645, 90%는 1.282.","src":"이론"},{"t":"서비스율 = (연간 총수요 − 평균 품절량) ÷ 연간 총수요 × 100. 예: 5,000개, 품절 400개 → 92%.","src":"이론"},{"t":"안전재고 계산 순서: ① 허용 품절률 = 허용 품절량 ÷ 연간수요 ② 서비스율 = 1 − 품절률 ③ 서비스율에 맞는 Z값 ④ Z × 표준편차 × √조달기간.","src":"기출 2020-40"},{"t":"예(2020-40): 품절률 300÷6,000=5% → 서비스율 95% → Z=1.645. 안전재고 = 1.645×20×√4 = 65.8.","src":"기출 2020-40"},{"t":"예(2020-28): 일평균수요 60,000÷300=200개, 리드타임 3일 → 600. 안전재고 400을 더해 재주문점 1,000.","src":"기출 2020-28"},{"t":"안전재고 수준을 높이면 재고유지비 부담이 커진다. 조달기간이 길어지면 안전재고량이 늘고, 수요변동의 표준편차가 커져도 늘어난다.","src":"기출 2020-38"},{"t":"안전재고는 품절예방, 납기준수, 고객서비스 향상을 위해 필요하다. 수요와 고객서비스를 고려해 적정 수준을 유지하면 재고비용이 과다해지는 것을 막는다.","src":"기출 2020-38"}]},{"머리":"정량·정기발주 비교","줄":[{"t":"정량발주법(발주점법): 재고가 발주점까지 내려가면 일정량을 주문한다. 대형마트·백화점에서 쓴다. 종류는 EOQ 모형, EPQ 모형, 투빈시스템, 단일기간 재고모형이다.","src":"이론"},{"t":"정량발주법 적용: 로트 보충, 수요예측이 어려울 때, 품목이 많아 관리하기 어려울 때, 주문과 생산이 그다지 관계없을 때, 계속적 실사가 필요할 때.","src":"이론"},{"t":"정기발주법: 발주시점을 매주·매월 정해 놓고 그때마다 발주량을 정해 주문한다. 자동발주하는 정량발주법과 대응된다. 조달기간과 발주 사이클 기간을 둘 다 고려하므로 안전재고가 상대적으로 크다.","src":"이론"},{"t":"정기발주법 적용: 소비량이 큰 주요 원재료 등 중요품목, 일괄구입으로 비용을 줄일 수 있는 품목, 시장동향에 따라 재고조정이 가능한 품목, 진부화 가능성이 큰 계절·유행상품(조달기간이 길어도), 주기적으로 조달되는 물품.","src":"이론"},{"t":"비교: 재고조사 — 정기는 정기실사, 정량은 계속실사. 수요예측 — 정기는 장래 예측정보, 정량은 과거 실적. 발주시기 — 정기는 정기적, 정량은 부정기적. 발주량 — 정기는 매번 변동, 정량은 매번 고정.","src":"이론"},{"t":"비교: 표준성 — 정기는 표준보다 전용부품이 좋고, 정량은 표준품이 좋다. 조달기간 — 정기는 긴 편, 정량은 비교적 짧은 편. 안전재고 — 정기는 크고 수요변화에 대응하며, 정량은 안정적 수요에 맞아 적다.","src":"이론"},{"t":"투빈법: 나사 같은 부품의 재고관리에 쓴다. 상자 2개에 부품을 보관하다가 한 상자가 소진되면 발주해 채운다. 남은 상자의 부품이 곧 안전재고이다. 저가품, ABC의 C그룹에 적용하고 재고수준을 계속 조사할 필요가 없다.","src":"이론"}]}],"함정":[{"x":"주문량이 커질수록 할인율이 높아지기 때문에 가능한 많은 주문량을 설정하는 것이 유리하다.","o":"EOQ 모형은 수량할인이 없다고 가정한다. 단가·주문비용은 주문량과 무관하게 일정하다.","src":"기출 2022-17 / 기출 2024-25"},{"x":"재고유지비용은 평균재고량에 반비례한다.","o":"재고유지비용은 평균재고량에 비례한다.","src":"기출 2022-17 / 기출 2024-25, 2025-17"},{"x":"재고부족에 대응하기 위한 안전재고가 필요하다.","o":"EOQ 모형은 재고부족을 허용하지 않으므로 안전재고가 필요 없다.","src":"기출 2022-17 / 기출 2025-17, 2026-19"},{"x":"수요가 불확실하기 때문에 주문량과 주문간격이 달라진다.","o":"EOQ 모형은 수요가 확정적이고 일정하므로 주문량과 주문간격이 일정하다.","src":"기출 2022-17 / 기출 2026-19"},{"x":"정기발주시스템: 통상 정량발주시스템에 비하여 적은 안전재고량을 갖는다.","o":"정기발주시스템은 정량발주시스템보다 안전재고량이 많다(점검 사이 기간까지 대비해야 하므로).","src":"기출 2024-24 / 보충"},{"x":"EOQ 모형에서 재고부족에 대응하는 안전재고가 필요하다.","o":"재고부족을 허용하지 않으므로 안전재고를 두지 않는다.","src":"기출 2022-17"},{"x":"정기발주시스템은 통상 정량발주시스템보다 적은 안전재고량을 갖는다.","o":"정기발주가 안전재고를 더 많이 갖는다.","src":"기출 2024-24 / 보충"},{"x":"정기발주법은 연속적으로 재고수준을 점검하는 연속점검시스템이다.","o":"연속점검시스템은 정량발주법이다.","src":"기출 2025-18"},{"x":"EOQ 모형의 가정: 재고유지비용은 주문량에 반비례한다(2024-25).","o":"주문량에 비례한다.","src":"기출 2024-25"},{"x":"EOQ 모형의 가정: 미납주문은 다음 입고 시 우선 처리한다(2026-19).","o":"재고부족을 허용하지 않아 미납주문 자체가 없다.","src":"기출 2026-19"},{"x":"EOQ 전제: 주문량이 다량일 경우 할인율을 적용한다. 1회 주문당 비용은 주문량에 비례해 증가한다(2025-17 ㄷ, ㅁ).","o":"수량할인이 없고, 1회 주문비용은 일정하다.","src":"기출 2025-17"},{"x":"델파이법은 재주문점의 주문관리 기법이다.","o":"델파이법은 수요예측(정성적) 기법이다. 재주문점 기법은 정량발주법, Two-Bin법, 기준재고법, 정기발주법이다.","src":"기출 2023-23"},{"x":"고객수요가 임의의 확률분포를 따를 때 수요변동의 표준편차가 작아지면 제품의 안전재고량이 증가한다.","o":"수요변동의 표준편차가 작아지면 안전재고량은 감소한다. 표준편차가 커지면 증가한다.","src":"기출 2020-38"}]},"#13":{"묶음":[{"머리":"재고관리의 목적·장점·보유 이유","줄":[{"t":"재고관리는 제품·반제품·원재료·상품 등을 합리적·경제적으로 유지하기 위한 활동이다.","src":"기출 2022-23"},{"t":"재고관리 장점: 실제 재고량 파악, 불확실성 대비, 가용 제품 확대로 고객서비스 달성, 수요·공급 변동성 대응. 상품 공급의 지연은 장점이 아니다.","src":"기출 2021-25, 2022-23"},{"t":"재고관리 목표: 서비스율 증대, 백오더율 감소, 재고회전율 증대, 손상율 감소, 보관비용 감소.","src":"기출 2024-23"},{"t":"재고 보유 이유: 원재료 부족으로 인한 생산중단 방지, 작업준비 시간·비용이 클 때 생산계획의 유연성 확보, 미래 위험 회피, 계절 집중 출하품의 판매기회 확보.","src":"기출 2023-21"},{"t":"재고를 필요 이상 보유하면 과도한 재고비용이 발생한다.","src":"기출 2022-23"},{"t":"재고는 공급사슬의 수요·공급 변동과 불확실성에 대한 완충 역할을 한다.","src":"기출 2022-23"},{"t":"재고(Inventory): 경제적 가치를 지닌 모든 물품의 흐름이 시간적 관점에서 시스템 내 어떤 지점에 정체 또는 저장되어 있는 상태이다.","src":"이론"},{"t":"재고를 보유하는 이유: 경제적 발주(제조) 기능, 불확실성 대처 기능, 생산평준화 기능.","src":"이론"},{"t":"재고관리: 창고·배송센터의 입지결정과 각 유통재고점의 재고품목 결정(재고배정)을 포함한다. 좁은 의미로는 각 품목의 발주시기와 1회 발주량을 정하는 것이 과제이다.","src":"이론"},{"t":"재고관리 목적: 재고수준 적정화로 재고투자·재고관련비용 절감, 품절방지(백오더율 감소)와 고객 서비스율 향상, 생산·판매활동 안정화, 재고관리시스템으로 업무 효율화·간소화.","src":"이론"},{"t":"재고관리의 중요 의사결정: 1회 주문량(EOQ), 발주시기(발주점), 적정 재고유지 수준과 안전재고 수준, 지연(postponement)전략 여부.","src":"이론"},{"t":"지연전략: 제품의 완성을 뒤로 미뤄 물류센터에서 출고 직전에 간단한 조립이나 패키징을 한다. 수요의 불확실성에 대처하고 설계부터 고객 인도까지 총비용을 최소화하는 SCM 개선방식이다.","src":"이론"},{"t":"재고관리 기능: 수급적합, 생산의 계획·평준화, 경제적 발주, 운송합리화, 불확실성 감소.","src":"이론"}]},{"머리":"재고 지표","줄":[{"t":"서비스율 = 납기 내 납품량 ÷ 전체 수주량.","src":"기출 2023-18, 2025-18"},{"t":"백오더율 = 납기 내 결품량 ÷ 전체 수주량.","src":"기출 2023-18, 2025-18"},{"t":"재고회전율 = 연간 매출액 ÷ 평균재고액. 예(2025-22): 300억÷60억=5.","src":"기출 2023-18, 2025-22"},{"t":"재고회전기간 = 수요대상 기간 ÷ 재고회전율.","src":"기출 2023-18"},{"t":"평균재고액 = (기초재고액 + 기말재고액) ÷ 2.","src":"기출 2023-18 / 보충"}]},{"머리":"재고의 종류","줄":[{"t":"주기재고(Cycle Inventory): 연간 주문횟수를 줄여 주문비용을 절감하려는 로트 단위 조달에서 생긴다.","src":"기출 2022-23, 2025-18"},{"t":"안전재고(Safety Stock): 수요·공급의 불확실성에 대비한다. 재고유지비 부담을 키우므로 적정 수준으로 관리한다.","src":"기출 2022-23, 2025-18"},{"t":"공급자관리재고(VMI): 공급사슬에서 생산자(공급자)가 납품 대상업체의 재고량을 유지·관리한다.","src":"기출 2021-24, 2025-21"},{"t":"재공품(WIP): 제조부 내 공정관리 대상인 가공 중 자재. 보통 생산현장에 놓여 있다.","src":"기출 2025-21"},{"t":"예비재고(Anticipation Stock): 계절적 수요 증가를 예상하거나 계획적 공장가동 중단에 대비해 사전에 준비하는 재고.","src":"기출 2025-21"},{"t":"운송중재고(Pipeline Stock), 완충재고(Buffer Stock), 로트사이즈 재고(Lot-size Stock)도 재고 유형이다.","src":"기출 2025-21"}]},{"머리":"채찍효과 해소 방안","줄":[{"t":"공급사슬 주체 간 실시간 정보공유, VMI, EDLP, CPFR, 리드타임 단축.","src":"기출 2021-24"},{"t":"리드타임을 길게 설정하는 것은 해소 방안이 아니다.","src":"기출 2021-24"}]},{"머리":"JIT (Just In Time)","줄":[{"t":"JIT는 불필요한 부품·재공품 재고를 없애는 것을 목표로 한다. 재고수준을 낮추고 불량품을 최소화한다.","src":"기출 2021-27, 2026-26"},{"t":"효과적인 Pull(끌어당기기) 시스템을 구현한다. 칸반시스템을 주로 활용한다.","src":"기출 2022-24, 2026-26"},{"t":"반복적 생산에 적합하다. 제조준비시간과 리드타임을 단축한다. 로트 크기를 줄인다.","src":"기출 2021-27, 2022-24, 2025-20"},{"t":"공급업체의 안정적 자재공급과 엄격한 품질관리, 공급업체와 생산업체의 상호협력이 있어야 효과가 난다.","src":"기출 2022-24"},{"t":"필요한 시기·양만큼 자재를 조달해 수요변화에 유연하게 대처한다.","src":"기출 2025-20"},{"t":"다기능공 양성이 필요하다(단일 기능공이 아니다).","src":"기출 2021-27 / 보충"}]},{"머리":"재고 지표 보충","줄":[{"t":"서비스율 = (연간 총수요 − 품절량) ÷ 연간 총수요 × 100. 예: 수요 5,000개, 품절 400개 → 92%.","src":"이론"},{"t":"백오더율 = 결품량 ÷ 고객요구량 × 100. 서비스율 + 백오더율 = 100%.","src":"이론"},{"t":"재고회전율 = 매출액 ÷ 평균재고액 = 판매량 ÷ 평균재고량. 평균재고액 = (기초재고 + 기말재고) ÷ 2. 재고회전율과 수요량은 양(+)의 상관관계이다.","src":"이론"},{"t":"EOQ로 보충할 때 평균재고량 = EOQ÷2. 예: D 100,000, 주문비 20,000, 유지비 10 → EOQ 20,000, 평균재고 10,000 → 재고회전율 100,000÷10,000 = 10회.","src":"이론"}]},{"머리":"재고의 종류·ABC 재고관리","줄":[{"t":"수송 중 재고(pipeline): 물류 흐름으로 한 지점에서 다른 지점으로 이동 중인 재고이다. 시간적 효용을 창출하기도 한다.","src":"이론"},{"t":"안전재고: 갑작스러운 수요 변동이나 리드타임·부품공급 불확실성으로 생기는 결품을 막으려고 비축하는 예비적 완충재고이다.","src":"이론"},{"t":"순환재고: 연속적인 재고보충 시점 간의 평균수요를 충족시키는 재고이다.","src":"이론"},{"t":"투기성 재고: 가격 변동이 큰 물품을 쌀 때 보유했다가 오르면 출하해 차익을 얻으려는 재고이다.","src":"이론"},{"t":"ABC 재고관리: 제품을 회전율이나 매출액 기준으로 A·B·C그룹으로 나누어 관리한다. A는 사용빈도가 높고 고가인 매출상품, C는 사용빈도가 낮고 저가인 상품, B는 중간이다.","src":"이론"},{"t":"ABC 등급별: A는 품목 20%·사용금액 80%·물동량 50%·정기발주방식. B는 품목 30%·사용금액 15%·물동량 30%·정량발주방식. C는 품목 50%·사용금액 5%·물동량 20%·Two-Bin 방식.","src":"이론"},{"t":"ABC 재고관리의 A그룹은 매출액이 가장 많은 중요 품목이라 정기발주를 보편적으로 적용한다.","src":"이론"},{"t":"ABC(Activity Based Costing): 서비스 다양화에 맞춰 보다 정확한 코스트를 파악하는 원가계산 기법이다. 물류활동 실태를 물류 원가에 반영한다. 물류활동 또는 작업내용으로 구분하고 활동마다 단가를 산정해 물류서비스 코스트를 산출한다.","src":"기출 2020-29"}]},{"머리":"SCM·채찍효과·VMI·CRP 보충","줄":[{"t":"SCM: 원자재 공급자부터 생산자·유통업자에 이르는 전 과정의 물자·자금·정보 흐름을 전체적 관점에서 통합관리하는 물류경영전략이다. 고객서비스 수준을 만족하면서 전체 시스템 비용을 최소화한다.","src":"이론"},{"t":"채찍효과: 공급사슬에서 최종 소비자로부터 멀어져 상류로 갈수록 정보가 지연·왜곡되어 수요와 재고의 불안정이 커지는 현상이다.","src":"이론"},{"t":"채찍효과 발생원인: 중복적인 수요예측, 일괄주문(batch order)에 의한 주문량 변동 폭 증가, 결품 우려로 경쟁적 주문을 늘리는 가수요, 고가·저가정책에 의한 선행 구입, 긴 리드타임.","src":"이론"},{"t":"채찍효과 해결방안: 수요 정보의 집중화·공유, 상시 저가전략(EDLP), 구성원 간 정보 실시간 공유, 주문 리드타임과 정보 리드타임 단축, 전략적 파트너십 구축.","src":"이론"},{"t":"VMI(공급자주도 재고관리): 벤더가 POS 매출량에 대응해 재고를 관리한다. 공급자가 물류창고에서 상품을 보충·유지한다. 생산계획·수발주 프로세스를 간소화하고 수요예측정보로 신속히 납품한다.","src":"이론"},{"t":"CRP(지속적 상품보충): 소비자에게서 나온 재고·판매 정보를 바탕으로 공급업체가 상품보충량을 결정한다.","src":"이론"}]},{"머리":"JIT 보충","줄":[{"t":"JIT: 필요한 시기에 필요한 수량만큼 자재를 조달해 낭비를 근본적으로 없애려는 무재고 생산시스템이다. 1950년대 중반 일본 도요타에서 개발했다.","src":"이론"},{"t":"JIT 도입목표: 재고 감소, 제조준비시간 단축, 리드타임 단축, 불량품 최소화, 자재취급노력 경감.","src":"이론"},{"t":"7대 낭비: 불량, 재고, 과잉생산, 가공, 동작, 운반, 대기시간. JIT생산, 소로트생산, 라인 자동화, TQC 같은 하위시스템을 구축한다.","src":"이론"},{"t":"칸반(Kanban): 작업에 필요한 부품·반제품의 양·시간·장소를 적어 전 공정 작업자에게 생산을 지시하는 카드이다. 생산지시와 자재 이동을 가시적으로 통제하는 정보시스템이다.","src":"이론"},{"t":"JIT 품질관리: 안돈시스템(품질문제 발생 시 알려주는 경고등), 카이젠(지속적 개선), 포카요케(실수 방지도구). 모든 구성원이 품질에 책임진다.","src":"이론"},{"t":"JIT 성공 조건: 안정된 주일정계획과 생산의 평준화(Heijunka), 공급자와의 장기적·긴밀한 협력, 생산자동화(Jidoka)와 표준화.","src":"이론"},{"t":"JIT 특징: 반복생산에 쓰고 주일정계획이 매일 규칙적일 때 맞는다. 단일 또는 소수 공급자와 장기 협력이 필요하다. 소량다빈도 배송으로 운송비가 늘어난다.","src":"이론"},{"t":"JIT와 MRP 비교: JIT는 Pull(요구에 따라가는) 시스템, MRP는 Push(계획대로 추진). JIT 목표는 낭비 제거(최소 재고), MRP 목표는 계획·통제. JIT는 생산 사이클타임 중심, MRP는 MPS 중심.","src":"이론"},{"t":"JIT는 안정된 생산계획이 필요하고, MRP는 변경이 잦은 MPS를 수용한다. JIT는 공급자와 장기거래, MRP는 경제적 구매 위주의 단기거래이다.","src":"이론"},{"t":"JIT는 반복적 생산에, MRP는 비반복적 생산(주문생산·로트생산 등)에 쓴다. JIT는 준비비용 축소로 소로트, MRP는 경제적 주문량(생산량)으로 정한다.","src":"이론"},{"t":"JIT는 100% 양품을 추구하고 눈으로 보는 관리(칸반)를 쓴다. MRP는 약간의 불량을 인정하고 컴퓨터로 처리한다.","src":"이론"}]}],"함정":[{"x":"안전재고는 재고를 품목별로 일정한 로트(Lot) 단위로 조달하기 때문에 발생한다.","o":"로트 단위 조달 때문에 생기는 재고는 주기재고이다. 안전재고는 수요·공급의 불확실성에 대비한 재고이다.","src":"기출 2022-23 / 기출 2025-18, 2022-23"},{"x":"평균재고액은 기말재고액에서 기초재고액을 뺀 값이다.","o":"평균재고액 = (기초재고액 + 기말재고액) ÷ 2.","src":"기출 2023-18 / 보충"},{"x":"기술력 향상 및 생산공정의 자동화 도입 촉진을 위해 재고를 보유한다.","o":"재고 보유 이유는 수요·공급 불확실성 대응, 로트 구매, 계절 수요 등이다. 기술력 향상·자동화 촉진은 재고 보유 목적이 아니다.","src":"기출 2023-21 / 기출 2023-21"},{"x":"정기발주법은 연속적으로 재고수준을 점검하므로 연속점검시스템(Continuous Review System)이라 한다.","o":"연속적으로 재고수준을 점검하는 연속점검시스템은 정량발주법이다. 정기발주법은 정기적으로 점검한다.","src":"기출 2025-18 / 기출 2024-24"},{"x":"리드타임을 길게 설정(채찍효과 해소 방안)","o":"리드타임을 단축해야 채찍효과가 줄어든다.","src":"기출 2021-24"},{"x":"상품 공급의 지연(delay)이 재고관리의 장점이다.","o":"장점이 아니다.","src":"기출 2021-25"},{"x":"백오더(back order)율 증대(재고관리의 목표)","o":"백오더율은 낮추는 것이 목표이다.","src":"기출 2024-23"},{"x":"JIT: 한 작업자에게 업무가 할당되는 단일 기능공 양성이 필수적이다.","o":"다기능공이 필요하다.","src":"기출 2021-27 / 보충"},{"x":"JIT: 효과적인 Push 시스템을 구현할 수 있다.","o":"JIT는 Pull 시스템이다.","src":"기출 2021-27, 2025-20, 2026-26"},{"x":"JIT: 비반복적 생산시스템에 적합하다.","o":"반복적 생산에 적합하다.","src":"기출 2021-27, 2022-24"},{"x":"JIT: 제조 준비 시간이 길어진다.","o":"제조준비시간이 짧아진다.","src":"기출 2021-27"},{"x":"JIT: 충분한 안전재고를 확보하므로 공급업체와 상호협력 없이도 운영 가능(2022-24 선지 5)","o":"공급업체의 안정적 공급과 협력이 필수이다. 안전재고를 최소화한다.","src":"기출 2022-24"},{"x":"JIT: 다품종 소량생산과 소량다빈도 배송으로 운송비가 절감된다(2025-20 ㄱ).","o":"소량다빈도 배송은 운송비를 키운다.","src":"기출 2025-20 / 보충(추정)"},{"x":"JIT: 자재를 거점창고에 통합 보관하므로 재고비용 절감과 취급이 용이(2025-20 ㄷ).","o":"JIT는 거점창고 통합 보관이 아니라 필요한 시기에 소량 조달한다.","src":"기출 2025-20 / 보충(추정)"},{"x":"재고의 입출고가 활발한 상품을 파악하여 중점적으로 관리하기 위한 기법이다(ABC, Activity Based Costing).","o":"입출고가 활발한 상품을 중점 관리하는 것은 재고 ABC 분석이다. Activity Based Costing은 활동별 원가계산 기법이다.","src":"기출 2020-29"},{"x":"품목수가 적으나 매출액 구성비가 높은 상품을 A그룹, 품목수는 많으나 매출액 구성비가 낮은 상품을 C그룹으로 관리한다(Activity Based Costing).","o":"A·C그룹 분류는 재고 ABC 분석의 내용이다. Activity Based Costing은 활동마다 단가를 산정해 물류서비스 코스트를 산출한다.","src":"기출 2020-29"},{"x":"채찍효과에 따른 부정적 영향을 최소화하기 위해서는 가격할인 등의 판매촉진 정책을 장려해야 한다.","o":"가격할인 등 판매촉진은 선행 구입과 가수요로 채찍효과를 키운다. 상시 저가전략(EDLP), 정보공유, 리드타임 단축으로 줄인다.","src":"기출 2020-36"},{"x":"ABC 재고관리에서 A품목은 매출액이 매우 적어 노력이 적게 드는 관리방법을 택하고, C품목은 매출액이 높아 정기발주시스템을 쓴다.","o":"A품목은 연간 사용량·매출액이 가장 많은 중요 품목이라 정기발주법을 쓰고, C품목은 Two-Bin법을 쓴다.","src":"이론"},{"x":"JIT는 수요예측을 기반으로 하는 Push 방식이 효과적이다.","o":"JIT는 고객 주문에서 시작되는 Pull 방식이다.","src":"이론"},{"x":"백오더율(%) = (요구량 ÷ 결품량) × 100.","o":"백오더율 = (결품량 ÷ 요구량) × 100.","src":"이론"}]},"#14":{"묶음":[{"머리":"하역의 의의·구성","줄":[{"t":"하역은 운송 및 보관에 수반해 생산에서 소비에 이르는 전 유통과정에서 행해진다.","src":"기출 2023-25"},{"t":"하역은 적하·운반·적재·반출·분류·정돈으로 구성된다.","src":"기출 2021-40, 2023-25, 2024-29"},{"t":"하역은 시간·장소 효용을 창출한다. 형태효용은 창출하지 않는다.","src":"기출 2021-40, 2023-25"},{"t":"하역 요소에는 쌓기, 내리기, 반출, 꺼내기, 운반이 든다. 통관은 하역 구성 요소가 아니다.","src":"기출 2024-29"},{"t":"물류센터 내 물품의 짧은 거리 이동(운반)도 하역 범위에 든다. 정돈·분류도 포함한다.","src":"기출 2022-26, 2024-26"},{"t":"하역작업 장소별 분류: 사내하역, 항만하역, 항공하역. 제조업체 사내하역은 조달·생산 과정의 운반과 하역을 포함한다.","src":"기출 2022-28, 2023-28"},{"t":"하역시스템 기계화·자동화로 작업환경이 개선되고 에너지·자원이 절약된다. 전자상거래 시대에 중요성이 커진다.","src":"기출 2022-28, 2023-28, 2024-26"},{"t":"하역의 기계화가 필요한 화물: 액체·분립체, 많은 인적 노력이 요구되는 화물, 상하차가 곤란한 높낮이의 작업장, 인력으로 시간을 맞추기 어려운 화물(4개 모두).","src":"기출 2022-31"},{"t":"하역: 물류과정에서 물자의 싣기·내리기, 운반, 쌓기, 꺼내기, 분류하기, 정리 등의 작업과 여기에 부수되는 작업이다.","src":"이론"},{"t":"하역은 운송·보관·포장 등 주요 물류활동을 지원하고 연결한다. 생산에서 소비에 이르는 전 유통과정의 효용창출에 직접 영향을 주므로 하역합리화는 물류합리화와 관련성이 크다.","src":"이론"},{"t":"하역은 운송과 보관을 연결하는 기능을 한다. 시간적·장소적 효용 창출을 지원한다.","src":"기출 2020-3"},{"t":"하역은 화물의 상·하차 작업, 운송기관 상호 간 중계 작업, 창고의 입출고 작업 등 범위가 넓다. 협의의 하역은 사내하역이고 광의로는 수출입 선적을 위한 항만하역까지 포함한다.","src":"이론"},{"t":"하역은 화물 또는 생산품의 저장과 이동을 말하며 제조·품질검사 공정은 제외한다.","src":"이론"},{"t":"물류기술의 발달로 노동집약적인 물류활동이 자동화·무인화로 진행되고 있다.","src":"기출 2020-3"}]},{"머리":"하역합리화 원칙 전체","줄":[{"t":"운반 활성화의 원칙: 화물의 이동 용이성(운반활성지수)을 최대화한다.","src":"기출 2022-25, 2023-26, 2025-28"},{"t":"하역 경제성의 원칙: 불필요한 하역작업을 생략해 작업능률을 높이고 파손·분실을 줄인다.","src":"기출 2022-25, 2023-26"},{"t":"거리(시간) 최소화의 원칙: 화물의 이동거리(톤·킬로)를 최소화한다.","src":"기출 2021-39, 2022-25, 2023-26, 2025-28"},{"t":"화물 단위화의 원칙: 화물을 일정한 중량 또는 용적으로 단위화한다.","src":"기출 2023-26"},{"t":"시스템화의 원칙, 인터페이스의 원칙도 하역 원칙으로 출제됐다. 동일성 원칙은 하역의 원칙이 아니다.","src":"기출 2022-25, 2024-28"}]},{"머리":"운반활성지수","줄":[{"t":"0: 화물이 바닥에 놓인 상태. 1: 상자 안에 넣은 상태. 2: 파렛트 위에 놓인 상태. 3: 대차에 실은 상태. 4: 컨베이어 위에 놓인 상태.","src":"기출 2022-27, 2024-27, 2026-29"},{"t":"활성지수가 가장 높은 상태는 컨베이어 위(4)이다.","src":"기출 2026-29"},{"t":"예(2024-27): 컨베이어 4 + 바닥 0 + 대차 3 + 상자 1 = 8.","src":"기출 2024-27"}]},{"머리":"하역 용어 전체","줄":[{"t":"더니지(Dunnage): 화물이 손상·파손되지 않도록 밑바닥이나 틈 사이에 까는 물건. 깔거나 끼우는 작업.","src":"기출 2021-36, 2023-27, 2025-30"},{"t":"래싱(Lashing): 운송기기에 실린 화물이 움직이지 않도록 줄로 고정하는 작업.","src":"기출 2021-36, 2023-27, 2025-30, 2026-28"},{"t":"스태킹(Stacking): 화물을 보관시설·장소에 규칙적으로 쌓는 작업.","src":"기출 2021-36, 2026-28"},{"t":"피킹(Picking): 보관 장소에서 화물을 꺼내는 작업.","src":"기출 2021-36, 2022-26, 2023-27"},{"t":"소팅(Sorting, 분류): 화물을 품종별·발송지별·고객별로 분류하는 작업.","src":"기출 2023-27"},{"t":"배닝(Vanning): 컨테이너에 화물을 싣는 작업. 디배닝(Devanning): 컨테이너에서 화물을 꺼내는 작업.","src":"기출 2022-26, 2025-30, 2026-28"},{"t":"운반: 창고 내부처럼 한정된 장소에서 화물을 이동하는 작업. 하역의 일부이다.","src":"기출 2022-26"},{"t":"적재: 물건을 보관시설로 옮겨 정해진 형태로 정해진 위치에 쌓는 작업.","src":"기출 2022-26"}]},{"머리":"하역 기계화·표준화","줄":[{"t":"물류합리화 관점에서 추진하고, 환경·안전을 고려한다.","src":"기출 2021-31, 2023-30"},{"t":"생산자·제조업자·물류업자 등 관련 당사자의 상호협력을 고려한다. 특정 화주 화물만을 대상으로 하지 않는다.","src":"기출 2021-31"},{"t":"운송·보관·포장·정보 등 물류활동 간의 호환성과 연계성을 고려하고 표준규격을 일관성 있게 만든다.","src":"기출 2023-30"},{"t":"유닛로드시스템에 맞는 하역·운반 장비의 표준화가 필요하다.","src":"기출 2023-30"}]},{"머리":"하역 용어 보충","줄":[{"t":"적하(loading & unloading): 운송기기 등에 물건을 싣고(적입, loading) 내리는(적출, unloading) 작업이다.","src":"이론"},{"t":"정돈(tidying): 출하하는 화물을 운송기관에 바로 실을 수 있도록 준비하는 작업이다.","src":"이론"},{"t":"쇼링(shoring): 각목이나 판재 등의 지주를 이용해 화물을 고정시키는 작업이다.","src":"이론"},{"t":"초킹(chocking): 화물 사이나 화물과 컨테이너 벽면 사이를 각재 등의 지주로 수평 방향으로 고정시키는 작업이다.","src":"이론"},{"t":"스태킹(Stacking): 화물을 창고나 야드 등 주어진 시설·장소에 정해진 형태와 순서로 정돈해 쌓는 작업이다. 하역 효율화에 크게 영향을 준다.","src":"기출 2020-5"}]},{"머리":"하역의 분류·기계화","줄":[{"t":"시설(장소)별: 자가용 시설하역(공장·자가용 창고·배송센터 등), 사업용 물류시설하역(복합터미널·항만·공항·역·보세창고).","src":"이론"},{"t":"운송수단별: 트럭하역, 화차하역, 선박하역, 항공기하역.","src":"이론"},{"t":"화물형태별: 개별하역(상자 등 포장단위별 또는 대형화물), 유닛로드 하역(파렛트·컨테이너), 비포장화물(벌크) 하역(분립체·액체를 운송수단·저장설비에 직접 적재·입출고).","src":"이론"},{"t":"하역기기별: 연속운반방식(컨베이어 등), 일괄운반방식(지게차 등), 시스템화된 기기(자동분류기 sorter 등), 차량·시설의 일부(도크레벨러, 돌리 등).","src":"이론"},{"t":"하역은 물류활동 중 인력의존도가 가장 높은 분야이다. 기계화에 따른 생력화와 자동화가 빠르게 진행되고 있다.","src":"이론"},{"t":"파렛트화에 의한 하역 기계화는 주로 물류비 절감을 위해 도입한다.","src":"기출 2020-6"},{"t":"하역 기계화 효과를 높이려면 물동량과 인건비 수준을 고려해 도입한다. 액체·분립체처럼 인력으로 하기 힘든 화물은 기계화 필요성이 더 크다.","src":"기출 2020-6"},{"t":"하역 기계화를 촉진하려면 하역기기 개발과 정보시스템을 통합한 하역 자동화시스템 구축이 필요하다.","src":"기출 2020-6"},{"t":"운반관리(MH): 한정된 구내에서 물자를 취급하고 이동시키는 작업이다. 제조공정·검사공정은 포함하지 않는다. 중점사항은 직선적 흐름, 계속적 흐름, 최소의 투입(시간·노동력), 작업집중화이다.","src":"이론"},{"t":"운반관리 4요소: 동작(경제적·합리적 운반), 시간(필요한 곳에 적시 공급), 수량(정확한 수량·중량·용량), 공간(계통적·효율적 이용).","src":"이론"}]},{"머리":"하역합리화 원칙 상세","줄":[{"t":"하역 경제성의 원칙: 불필요한 하역작업을 줄여 가장 경제적인 횟수로 하역한다. 하위원칙은 운반 순도, 최소 취급, 수평 직선이다.","src":"이론"},{"t":"운반 순도(purity)의 원칙: 필요 이상의 과대포장(overpacking)으로 중량·용적을 키워 운임·운반비·하역비를 더 부담하지 않게 한다.","src":"이론"},{"t":"최소 취급(least handling)의 원칙: 생략해도 지장 없는 하역·운반을 줄여 다시 취급(rehandling)하지 않는다. 임시로 놓아두는 행위도 줄인다.","src":"이론"},{"t":"수평 직선(straight line)의 원칙: 운반거리를 직선(최단거리)으로 해 교차·지그재그·왕복을 없앤다. 하역작업의 톤·킬로(중량×이동거리)를 최소화한다.","src":"이론"},{"t":"활성화(live load)의 원칙: 운반활성지수를 최대화한다. 지표와 접점이 작을수록 활성지수가 높고 하역 효율이 오른다. 활성지수는 놓여 있는 물건을 다음 동작으로 옮기기 쉬운 정도이다.","src":"이론"},{"t":"이동거리 및 시간 최소화 원칙: 하역작업의 이동거리를 최소화한다. 수·배송·보관에서 기본이 되는 원칙이며 물류비용과 직접 연결된다.","src":"이론"},{"t":"유닛로드(단위화) 원칙: 화물을 특정 단위(중량·부피)로 단위화한다. 파렛트화·컨테이너화로 손상·감모·분실을 막고 효율을 높인다. 표준화 원칙은 이 원칙의 전제조건이다.","src":"이론"},{"t":"기계화 원칙: 인력 작업을 기계작업으로 대체해 생력화한다. 중력이용 원칙: 중력에 따른 하역작업을 선택하고 물품을 들고 다니는 경우를 최소화한다.","src":"이론"},{"t":"시스템화 원칙: 개개의 하역활동을 유기체로 보고 시스템 전체의 균형과 시너지를 노린다. 파렛트·컨테이너의 규격·구조·품질이 유기적으로 연결되어야 한다.","src":"이론"},{"t":"인터페이스(호환성) 원칙: 하역작업에서 공정 간 접점이 원활하게 소통하게 한다.","src":"이론"},{"t":"취급균형(balanced handling) 원칙: 작업 흐름은 병목(애로)공정이 좌우하므로 공정능력을 파악하고 평준화 계획을 세운다.","src":"이론"},{"t":"하역합리화 보조원칙: 표준화, 단순화, 흐름유지(운반 흐름을 연속적으로 유지), 취급균형, 수평직선, 탄력성(하역설비를 다양한 용도로 탄력 운영), 운반속도, 최소취급.","src":"이론"},{"t":"하역의 기본원칙에 포함되는 것: 최소 취급, 경제성, 중력이용, 화물 단위화, 이동거리·시간의 최소화.","src":"기출 2020-4"}]}],"함정":[{"x":"배닝(Vanning): 파렛트에 화물을 쌓는 작업을 말한다.","o":"배닝(Vanning): 컨테이너에 화물을 싣는 작업. 파렛트에 쌓는 작업이 아니다.","src":"기출 2021-36 / 기출 2022-26, 2025-30"},{"x":"하역기기를 탄력적으로 운영하여야 한다.","o":"하역기기는 탄력적으로 운영하는 것이 바람직하다는 설명(옳은 서술). 이 문항은 발문 미확인.","src":"기출 2021-39 / 출제 오답(발문 미확인, 검수 필요)"},{"x":"불필요한 물품의 취급을 최소화하여야 한다.","o":"불필요한 물품 취급을 최소화하는 것은 하역합리화 원칙에 맞는 서술(발문 미확인).","src":"기출 2021-39 / 출제 오답(발문 미확인, 검수 필요)"},{"x":"하역작업을 표준화하여 효율성을 추구하여야 한다.","o":"하역작업을 표준화하여 효율성을 추구하는 것은 하역합리화 원칙에 맞는 서술(발문 미확인).","src":"기출 2021-39 / 출제 오답(발문 미확인, 검수 필요)"},{"x":"복잡한 시설과 하역체계를 단순화하여야 한다.","o":"복잡한 시설과 하역체계를 단순화하는 것은 하역합리화 원칙에 맞는 서술(발문 미확인).","src":"기출 2021-39 / 출제 오답(발문 미확인, 검수 필요)"},{"x":"제품에 대한 형태효용을 창출한다.","o":"하역은 시간·장소 효용을 창출한다. 형태효용은 생산의 몫이다.","src":"기출 2021-40 / 기출 2023-25 / 보충"},{"x":"운반활성화 지수를 최소화해야 한다.","o":"운반활성화 지수는 최대화를 지향한다.","src":"기출 2021-40 / 기출 2023-26, 2025-28"},{"x":"화물에 대한 제조공정과 검사공정을 포함한다.","o":"하역은 적하·운반·적재·반출·분류로 구성된다. 제조공정과 검사공정은 포함하지 않는다.","src":"기출 2021-40 / 기출 2021-40, 2023-25"},{"x":"기계화와 자동화를 통한 하역생산성 향상이 어렵다.","o":"기계화와 자동화로 하역생산성을 높일 수 있다.","src":"기출 2021-40 / 기출 2022-28, 2023-25"},{"x":"하역시스템의 도입 목적은 범용성과 융통성을 지양하는데 있다.","o":"하역시스템은 범용성과 융통성을 갖추는 것을 목적으로 한다.","src":"기출 2022-28 / 보충(추정)"},{"x":"시간, 장소 및 형태 효용을 창출한다.","o":"하역은 시간·장소 효용을 창출한다. 형태효용은 생산공정의 효용이다.","src":"기출 2023-25 / 보충"},{"x":"운반활성지수를 최소화한다.","o":"운반활성지수는 최대화를 지향한다.","src":"기출 2023-26 / 기출 2021-40, 2025-28"},{"x":"필요한 원재료ㆍ반제품ㆍ제품 등의 최적 보유량을 계획하고 조직하고 통제하는 기능을 한다.","o":"필요한 원재료·반제품·제품의 최적 보유량을 계획·통제하는 것은 재고관리의 기능이다.","src":"기출 2023-28 / 기출 2023-28"},{"x":"생산의 마지막 단계로 치수, 강도, 재질, 기법 등의 표준화로 구성된다.","o":"하역의 표준화는 생산의 마지막 단계가 아니라 운송·보관·포장·정보 등 물류 전체의 호환성을 위해 치수·강도·재질·기법을 통일하는 것이다.","src":"기출 2023-30 / 기출 2023-30"},{"x":"물류센터 내에서 물품의 짧은 거리 이동은 하역의 범위에 포함되지 않는다.","o":"물류센터 내에서 물품을 짧은 거리로 옮기는 것(운반)도 하역의 범위에 포함된다.","src":"기출 2024-26 / 기출 2022-26, 2024-29"},{"x":"하역은 운송 수단에 실려 있는 물품을 꺼내는 일만을 의미하며, 정돈이나 분류 는 하역의 범위에 포함되지 않는다.","o":"하역은 적하·운반·적재·반출·분류·정돈을 모두 포함한다.","src":"기출 2024-26 / 기출 2023-25, 2024-29"},{"x":"하역작업의 생산성을 향상시키기 위해 인력 하역 비중이 늘어나는 추세이다.","o":"하역작업은 기계화·자동화로 생산성을 높이는 추세이며 인력 하역 비중은 줄어든다.","src":"기출 2024-26 / 기출 2023-28"},{"x":"하역작업의 혁신을 위해 물류센터 장비의 기계화와 무인화를 늦게 도입해야 한다.","o":"물류센터 장비의 기계화·무인화는 늦추지 않고 도입한다(전자상거래 시대에 하역 중요성 증가).","src":"기출 2024-26 / 기출 2024-26"},{"x":"경제성 원칙: 하역작업의 횟수를 증가시켜 비용을 최대화한다.","o":"경제성 원칙: 불필요한 하역작업을 줄여 비용을 최소화한다.","src":"기출 2025-28 / 기출 2023-26"},{"x":"운반활성화 원칙: 운반활성화 지수를 최소화한다.","o":"운반활성화 원칙: 운반활성지수를 최대화한다.","src":"기출 2025-28 / 기출 2023-26"},{"x":"화물 단위화의 원칙: 다품종 소량운송을 위해 화물을 개별화하여 하역한다.","o":"화물 단위화의 원칙: 화물을 파렛트·컨테이너 등으로 묶어 일정 중량·용적으로 단위화한다.","src":"기출 2025-28 / 기출 2023-26"},{"x":"화물유동화 원칙: 화물의 손상, 분실 등을 최소화하기 위하여 하역공정을 멈추고 불량 검사를 한다.","o":"화물유동화 원칙은 하역공정을 멈추지 않고 흐름을 유지하는 방향이다. 하역공정을 멈추고 불량 검사를 하는 것은 아니다.","src":"기출 2025-28 / 보충(추정)"},{"x":"하역은 시간·장소 및 형태 효용을 창출한다.","o":"시간·장소 효용을 창출한다. 형태효용은 아니다.","src":"기출 2023-25"},{"x":"특정 화주의 화물을 대상으로 추진(하역의 기계화·표준화 고려사항)","o":"특정 화주가 아니라 물류합리화 관점으로 추진한다.","src":"기출 2021-31"},{"x":"하역의 원칙: 동일성 원칙","o":"하역의 원칙이 아니다(운반활성화, 경제성, 이동거리 최소화, 단위화 등).","src":"기출 2024-28"},{"x":"스태킹(Stacking): 화물이 손상되지 않도록 밑바닥이나 틈 사이에 물건을 깔거나 끼우는 작업(2023-27, 2025-30)","o":"그 설명은 더니지이다. 스태킹은 규칙적으로 쌓는 작업이다.","src":"기출 2023-27, 2025-30"},{"x":"디배닝(Devanning): 컨테이너에 화물을 싣는 작업(2025-30)","o":"컨테이너에서 화물을 꺼내는 작업이다.","src":"기출 2025-30"},{"x":"피킹(Picking): 화물을 유형별·고객별·도착지별로 분류하는 작업(2025-30)","o":"피킹은 보관 장소에서 화물을 꺼내는 작업이다. 분류는 소팅이다.","src":"기출 2025-30"},{"x":"분류(Sorting): 출하 화물을 수송기기에 바로 실을 수 있게 정돈하는 작업(2025-30)","o":"그 설명은 정돈이다. 분류는 품종·고객·도착지별로 나누는 작업이다.","src":"기출 2025-30"},{"x":"하역 구성 요소에 통관이 포함된다(2024-29 ㅂ).","o":"통관은 하역 구성 요소가 아니다.","src":"기출 2024-29"},{"x":"하역은 항만, 공항, 철도역 등 다양한 장소에서 수행되고 있으나 운송과 보관을 연결하는 기능은 갖고 있지 않다.","o":"하역은 보관과 운송 전후에 수반되는 작업이므로 운송과 보관을 연결하는 기능을 한다.","src":"기출 2020-3"},{"x":"하역 분야는 물류활동 중에서 가장 기계화 수준이 높으며, 인력의존도가 낮은 분야이다.","o":"하역은 물류활동 중 인력의존도가 가장 높은 분야이다. 기계화·자동화가 빠르게 진행되는 중이다.","src":"기출 2020-6"},{"x":"하역의 기본원칙: 최대 취급의 원칙","o":"하역의 원칙은 최소 취급이다.","src":"기출 2020-4"},{"x":"하역의 기본원칙: 이동거리 및 시간의 최대화 원칙","o":"이동거리 및 시간의 최소화 원칙이다.","src":"기출 2020-4"},{"x":"래싱(Lashing)·배닝(Vanning)·더니징(Dunnaging)이 화물을 정해진 형태와 순서로 쌓는 작업이다.","o":"정해진 시설·장소에 정해진 형태와 순서로 쌓는 작업은 스태킹이다. 래싱은 줄로 고정, 배닝은 컨테이너에 적입, 더니징은 틈에 깔거나 끼우는 작업이다.","src":"기출 2020-5"},{"x":"Material Handling의 4요소는 Motion, Time, Quantity, Price이다.","o":"4요소는 동작(Motion)·시간(Time)·수량(Quantity)·공간(Space)이다.","src":"이론"}]},"#15":{"묶음":[{"머리":"하역기기 선정","줄":[{"t":"선정 기준: 에너지 효율성, 안전성, 작업량과 작업 특성, 취급 품목의 종류, 경제성.","src":"기출 2021-33, 2025-29"},{"t":"사내하역 선정 기준에는 취급화물의 중량·종류, 건물구조와 시설배치도 든다.","src":"기출 2025-29"},{"t":"화물의 원산지·목적지는 선정 기준이 아니다.","src":"기출 2021-33, 2025-29"}]},{"머리":"지게차(Forklift) 종류","줄":[{"t":"카운터 밸런스형: 포크와 마스트를 전방에 장착하고 후방에 웨이트를 둔다.","src":"기출 2024-30"},{"t":"사이드 포크형: 차체 측면에 포크와 마스트가 장착된다.","src":"기출 2022-30, 2024-30"},{"t":"스트래들형: 차체 전방에 아웃리거를 설치하고 그 사이에 포크를 두어 안정성을 높인다.","src":"기출 2022-30"},{"t":"3방향 작동형: 포크와 캐리지가 회전해 진행방향 변경 없이 작업한다.","src":"기출 2022-30"},{"t":"워키(Walkie)형: 작업자가 걸어서 조작하는 소형 지게차.","src":"기출 2022-30 / 보충"},{"t":"전동식은 실내작업에, 디젤엔진식은 배기가스·소음 때문에 실외에 맞는다.","src":"기출 2022-30 / 보충"}]},{"머리":"컨베이어·무인운반","줄":[{"t":"벨트 컨베이어: 연속 이동하는 벨트로 화물을 운반한다.","src":"기출 2024-30"},{"t":"롤러·휠 컨베이어: 로울러 또는 휠을 배열해 화물을 운반한다. 트롤리 컨베이어는 천장 레일에 매달아 이송한다.","src":"기출 2024-30 / 보충"},{"t":"AGV: 지정된 장소까지 자동 주행하는 장비.","src":"기출 2024-30"}]},{"머리":"컨테이너·벌크 하역기기","줄":[{"t":"언로우더(Unloader): 철광석·석탄·석회석 같은 벌크 화물을 하역한다.","src":"기출 2021-38"},{"t":"호퍼(Hopper): 원료·연료·화물을 컨베이어나 기계로 이송하는 깔때기 모양 장비. 컨테이너터미널 장비가 아니다.","src":"기출 2022-37, 2023-29"},{"t":"톱 핸들러(Top Handler): 공(empty) 컨테이너를 적치한다.","src":"기출 2021-38"},{"t":"트랜스퍼 크레인(Transfer Crane): 컨테이너를 적재하거나 다른 장소로 이송·반출한다.","src":"기출 2021-38"},{"t":"천정 크레인(Overhead Travelling Crane): 크레인 본체가 천장을 주행하며 화물을 상하로 들어 올리고 수평 이동한다.","src":"기출 2021-38"},{"t":"리치 스태커(Reach Stacker): 철도터미널 화차의 컨테이너 상·하차, 스프레더로 운반·적재, 긴 붐으로 풀 컨테이너를 CY 내에서 이동한다.","src":"기출 2025-36"},{"t":"스트래들 캐리어: 컨테이너를 양다리 사이에 끼워 운반한다.","src":"기출 2021-12"},{"t":"로딩 암(Loading Arm): 본선과 터미널 간 액체화물 이송에 연결하는 육상 터미널 측 장비.","src":"기출 2023-29 / 보충"},{"t":"그라브 버켓(Grab Bucket)은 컨테이너터미널 장비가 아니다(벌크용).","src":"기출 2026-38"}]},{"머리":"항공하역","줄":[{"t":"항공화물 탑재방식: 살화물, 파렛트, 컨테이너 탑재방식.","src":"기출 2026-36"},{"t":"리프트 로더(Lift Loader): 파렛트를 항공기 적재공간 바닥 높이까지 들어 올려 탑재한다.","src":"기출 2021-19, 2026-36"},{"t":"돌리(Dolly): 파렛트 운반용 차대. 자체 기동력이 없고 터그 카(Tug Car)에 연결해 쓴다.","src":"기출 2021-19"},{"t":"트랜스포터(Transporter): 항공기에서 내린 ULD를 터미널까지 수평 이동한다.","src":"기출 2021-19, 2026-36"},{"t":"터그 카, 이글루(igloo), 파렛트 스케일도 항공하역 장비다.","src":"기출 2024-39, 2025-35, 2026-36"},{"t":"항공하역 장비 해당: 이글루, 트랜스포터, 돌리, 터그 카. 리치스태커·탑 핸들러·스트래들 캐리어·로딩 암은 아니다.","src":"기출 2024-39, 2025-35"},{"t":"소터(Sorter): 비교적 소형 화물을 행선지별·인도지별로 구분하는 장치. 통상 컨베이어와 제어장치로 구성한다.","src":"기출 2021-19"}]},{"머리":"철도하역 방식","줄":[{"t":"TOFC(Trailer on Flat Car): 컨테이너를 실은 트레일러를 철도화차 위에 적재해 운송한다.","src":"기출 2023-32"},{"t":"COFC(Container on Flat Car): 화차 위에 컨테이너만 적재한다.","src":"기출 2023-32"},{"t":"피기백(Piggy Back): 화물열차 대차 위에 트레일러나 트럭을 컨테이너 등과 함께 싣는다.","src":"기출 2023-32"},{"t":"캥거루(Kangaroo): 화차에 트레일러 바퀴가 들어갈 홈이 있어 적재높이가 낮다.","src":"기출 2023-32"},{"t":"트럭이 화물열차에 직각으로 후진해 무개화차에 컨테이너를 바로 싣는 방식은 플렉시밴(Flexi-Van)이다. 프레이트 라이너는 컨테이너 전용 직행 열차이다.","src":"기출 2023-32 / 보충"}]},{"머리":"하역운반장비·하역시스템","줄":[{"t":"하역운반장비가 필요한 이유: 인력 하역의 한계 극복, 안전사고 방지(노동환경), 전·후 공정과 기능 간 일관된 작업, 효율성·생산성 향상으로 비용 절감, 신속·정확한 고객서비스. 하역운반 작업은 3D업무라 기계화·자동화·시스템화가 필수이다.","src":"이론"},{"t":"장비 선정 시 고려: 화물특성(형상·크기·중량), 작업특성(작업량·계절변동의 유동성·취급품목 종류·운반거리와 범위), 작업환경 특성(작업장 구조·여건), 하역기기 특성(안전성·신뢰성·성능·탄력성·생에너지성), 비용절감과 수익성.","src":"이론"},{"t":"하역시스템: 하역관련 요소를 유기적으로 결합해 하역에 드는 시간·노력·경비를 최소화하고 물류기능을 높이는 체계이다.","src":"이론"},{"t":"하역시스템 목적: 하역비용 절감, 노동환경 개선, 생력화·생자원화, 범용성과 융통성 제고, 고도의 운전기능과 안전성 향상.","src":"이론"},{"t":"하역시스템 구축절차: 1단계 유닛로드시스템 도입 → 2단계 최적 출고방식 결정(피킹·소팅 고려) → 3단계 보관방식 선택(창고 규모·종류·수) → 4단계 입하에서 출하까지 운반방식 선택(레이아웃·움직임·환경).","src":"이론"},{"t":"하역시스템도 보관품목수·수량·회전수별 ABC군으로 분류해 결정한다. 예: 품목수 소·수량 다·회전수 고(A-A-A)는 플로우 랙·대차 랙·파렛트 랙에 대차 랙·스태커 크레인을 쓴다.","src":"이론"}]},{"머리":"지게차·어태치먼트 보충","줄":[{"t":"지게차(포크리프트): 포크나 램 등 화물 적재장치와 이를 승강시키는 마스트를 갖춘 하역 자동차이다. 올바른 명칭은 포크리프트 트럭이다.","src":"이론"},{"t":"지게차 특성: 전륜구동·후륜조향(좁은 회전 반경). 포크는 2.5m에서 5m 정도 이내로 승강한다.","src":"이론"},{"t":"카운터 밸런스형: 가장 일반적인 형식이다. 차체 전면에 포크와 승강·적재 장치, 후면에 카운터웨이트가 있다. 내연식과 전동식(축전지식)이 있다.","src":"이론"},{"t":"스트래들 포크형: 차체 전방으로 뻗은 주행 가능한 아웃리거로 안정을 유지하고 포크가 양쪽 아웃리거 사이에 내려진다.","src":"이론"},{"t":"사이드 포크형: 포크와 마스트가 차체 옆쪽에 설치된다. 통로가 좁은 창고에서 장척화물을 취급하기에 가장 적합하다.","src":"이론"},{"t":"피킹 포크리프트: 랙 창고에서 쓴다. 포크 면 높이에 운전대가 있어 임의의 높이에서 작업하고, 좁은 통로에서 쓸 수 있으며 포크가 180도 회전한다.","src":"이론"},{"t":"파렛트 스태킹 트럭: 전방으로 뻗은 아웃리거로 안정을 유지하고 포크가 아웃리거 위로 뻗어 있다.","src":"이론"},{"t":"리치(Reach)형: 포크가 양쪽 아웃리거 사이에 있고 전후방으로 이동해 좁은 장소에서 작업한다. 마스트와 포크가 앞뒤로 움직이는 입승식(서서 운전) 지게차이다.","src":"이론"},{"t":"워키(Walkie)형: 탑승 설비 없이 운전자가 걸어 다니며 작업한다.","src":"이론"},{"t":"탑 핸들러형: 카운터 밸런스형의 일종이다. 컨테이너 모서리쇠를 잡는 스프레더와 승강 마스트를 갖춘 대형 지게차이다. 크레인 끝에 스프레더를 단 것은 리치 스태커이다.","src":"이론"},{"t":"어태치먼트: 지게차 하역장치에 추가하거나 대체해 보통 포크와 교환하는 부속장치이다.","src":"이론"},{"t":"램(ram): 화물 구멍에 삽입하는 막대 모양 장치로 코일·전선 운반에 적합. 회전포크: 포크를 좌우로 회전. 힌지드포크: 포크를 상하로 기울임. 로드 스태빌라이저: 포크 위 화물을 누름.","src":"이론"},{"t":"클램프: 화물을 사이에 끼움(회전클램프, 원통을 끼우는 드럼클램프, 종이상자용 카톤클램프). 푸시풀: 백레스트 하부 장치로 화물을 폭이 넓은 포크 위로 끌어들이거나 밀어냄. 버킷: 벌크화물 하역용. 스프레더: 컨테이너 등을 달아 올림.","src":"이론"},{"t":"필요 지게차 수 = 연간 목표처리량 ÷ 실제작업량. 실제작업량 = 정상작업량 × 장비가동률. 정상작업량 = 연간 작업일수 × 일일 작업가능시간 × 시간당 작업량.","src":"이론"},{"t":"예: 360일×15시간×12톤=64,800톤, ×0.75=48,600톤. 목표 486,000톤÷48,600=10대.","src":"이론"}]},{"머리":"크레인·컨베이어·기타 장비","줄":[{"t":"크레인(기중기): 윈치, 윈치 구동용 동력, 와이어, 활차, 지주, 붐 등으로 구성되어 물건을 들어 올리는 기계이다. 고정식과 이동식이 있다. 사용범위로 수상용·수륙양용·육상용, 형식으로 천정주행·지브·갠트리·탑형으로 나눈다.","src":"이론"},{"t":"천장 크레인: 본체가 천장을 주행하며 화물을 상하로 들어 올려 수평 이동한다. 트랜스퍼 크레인(트랜스테이너): 컨테이너를 적재하거나 다른 장소로 이송·반출한다.","src":"이론"},{"t":"갠트리 크레인(컨테이너 크레인): 안벽을 따라 설치된 레일 위를 주행하며 컨테이너를 선박에 싣고 내린다. 레일 대신 타이어로 주행하는 크레인도 있다. 레일 위를 주행하는 다리를 가진 거더에 트롤리가 장착된 구조이다.","src":"이론"},{"t":"데릭(Derrick): 삼각뿔 구조물에 상단이 지지된 마스트를 가지며 마스트 또는 붐 위 끝에서 화물을 달아 올리는 지브붙이 크레인이다. 교각형 기둥으로 상부 크레인을 지지하고 컨테이너를 들어 올려 적재하는 것은 스트래들 캐리어이다.","src":"이론"},{"t":"언로더에는 호퍼·피더·컨베이어 등을 장착한다.","src":"이론"},{"t":"지브 크레인: 선회할 수 있는 붐 선단에 지브를 부착한 크레인이다. 항만이나 선박에 설치해 화물과 해치를 운반한다. 고정식과 주행식이 있다.","src":"이론"},{"t":"윈치 크레인: 차체를 이동·회전시키며 컨테이너 트럭이나 플랫 카에서 컨테이너를 하역한다.","src":"이론"},{"t":"스태커 크레인: 랙에 화물을 입출고시키는 크레인이다. 하부에 주행 레일, 상부에 가이드 레일이 있는 통로 안에서 주행한다.","src":"이론"},{"t":"크레인은 천정크레인, 갠트리크레인, 집(Jib)크레인, 기타 크레인으로 구분한다.","src":"기출 2020-8"},{"t":"집크레인은 고정식과 주행식이 있다. 아파트 등 건설공사에도 많이 쓰고 수평방향으로 더 넓은 범위에서 작업할 수 있다.","src":"기출 2020-8"},{"t":"컨베이어(KS T 2301): 화물을 연속적으로 운반하는 기계이다. 수평운반이 주 목적이다.","src":"이론"},{"t":"컨베이어 장점: 원격조정·자동제어 가능, 자재검사와 운반 동시 수행 가능, 작업장 간 임시 저장소 역할, 오버헤드 컨베이어로 공간활용, 좁은 장소·비직선 경로 가능, 중력 이용 설비는 노면과 무관하게 설치, 벌크화물·액체 등 다양한 화물 운반.","src":"이론"},{"t":"컨베이어 단점: 속도가 한정되어 하역에 시간이 걸리고 양단에 인원이 필요한 경우가 있다. 기동성이 적어 탄력적 운영이 곤란하다. 높이 쌓기에 부적합하고 화물 형상이 다르면 부적당하다.","src":"이론"},{"t":"벨트 컨베이어: 수평·경사면 반송에 경량물부터 중량물까지 쓴다. 트롤리 컨베이어: 가이드 레일을 따라 입체공간을 활용해 반송한다. 슬랫 컨베이어: 체인에 부착한 슬랫으로 운반한다. 라인 컨베이어: 파렛트에 적재한 중량물 안전반송에 적합하고 설비비가 싸지만 고속반송에는 부적합하다.","src":"이론"},{"t":"롤러 컨베이어: 롤러·휠을 운반 방향으로 병렬시킨다. 하중으로 높은 쪽에서 낮은 쪽으로 흐르게 하는 프리 롤러컨베이어와 수평반송용 구동식이 있다.","src":"이론"},{"t":"수직 반송 컨베이어: 수직 트레이 컨베이어(VT)와 수직 왕복 컨베이어(VR). 플로우 컨베이어: 밀폐 상태로 체인·케이블로 분립체(시멘트·곡물)를 운반한다. 유체 컨베이어: 파이프라인으로 액체·기체를 운반한다.","src":"이론"},{"t":"체인 컨베이어 종류: 슬랫, 토우, 트롤리, 에이프런 컨베이어. 유체 컨베이어 종류: 공기 컨베이어, 기체송유관 컨베이어.","src":"이론"},{"t":"무인반송차량(AGV): 차체에 화물을 싣고 지시된 장소까지 자동 주행해 이재 또는 적재하는 무궤도 차량이다.","src":"이론"},{"t":"호이스트(권상기): 화물의 권상·권하·횡방향 끌기·견인 등을 하는 장치를 총칭한다. 체인 레버 호이스트는 레버를 반복 조작해 권상·권하·견인한다.","src":"이론"},{"t":"도크레벨러: 도크 보드를 고정하는 유압장치 또는 철판으로 화물차량 하대의 높이를 조정하는 장치. 리프트게이트: 하역장에 도크가 없을 때 트럭이 자체적으로 화물을 승강시키도록 차체에 부착하는 장치.","src":"이론"},{"t":"도크보드: 화물차와 창고 입구를 연결하는 하대. 파렛트로더: 트럭·컨테이너 하대 위로 파렛타이즈드 화물을 이동시키는 기구. 테이블리프터: 유압장치로 링크기를 장치해 하대를 승강시킨다.","src":"이론"}]},{"머리":"철도·항공 하역 보충","줄":[{"t":"TOFC: 화물을 적재한 트레일러를 화물과 함께 적재하는 철도하역 방식이다. 종류는 피기백, 캥거루, 프레이트 라이너.","src":"이론"},{"t":"피기백: 화물적재 단위가 클수록 편리하고 피기 패커 등 하역기계가 필요하다. 캥거루: 트럭·트레일러 바퀴가 화차 하대 밑으로 낙하해 터널·차량 높이 제한이 있을 때 피기백보다 유리하다.","src":"이론"},{"t":"프레이트 라이너: 영국 국철이 개발한 정기적 급행 컨테이너 열차로 터미널 사이를 고속·고정편성으로 정기 운행한다.","src":"이론"},{"t":"COFC: 화차에 컨테이너만 적재한다. 철도 컨테이너 데포에서 크레인이나 컨테이너 핸들러로 적재하며 평판화차 또는 전용 컨테이너화차를 쓴다.","src":"이론"},{"t":"COFC 종류: 세로-가로방식(탑 핸들러·리치 스태커 이용, 취급량이 비교적 적을 때), 매달아 싣는 방식(크레인, 대량 컨테이너 신속 처리), 플렉시밴(트럭이 직각 후진해 무개화차에 싣고 화차 회전판으로 컨테이너를 90도 회전해 고정).","src":"이론"},{"t":"COFC에 해당: 지게차에 의한 방식, 크레인에 의한 방식, 플렉시밴. 피기백·캥거루는 TOFC이다.","src":"이론"},{"t":"피기백 방식은 컨테이너를 적재한 트레일러·트럭을 화차에 싣는 방식과 컨테이너를 직접 철도 대차 위에 싣는 방식이 있다. COFC는 크레인이나 컨테이너 핸들러로 적재한다.","src":"기출 2020-32"},{"t":"2단적 열차(Double Stack Train): 한 화차에 컨테이너를 2단으로 적재한다. 바이모달시스템: 철도차륜과 도로 주행용 타이어를 겸비한 차량이라 철도에서는 화차로, 도로에서는 트레일러로 쓴다.","src":"기출 2020-32"},{"t":"ULD(Unit Load Device): 항공운송에만 쓰는 항공화물용 컨테이너(CAC)·파렛트·이글루이다.","src":"이론"},{"t":"CAC(항공형 컨테이너): 항공기 화물실 동체 모양에 맞게 만들어 화물실 공간을 최대로 활용한다. 항공형 파렛트: 금속 평판 위에 화물을 싣고 net 또는 이글루로 고정해 탑재한다. 이글루: 항공기 동체 모양으로 만든 덮개로 파렛트 위에 덮는다.","src":"이론"},{"t":"트랜스포터: 하역이 끝난 ULD를 터미널에서 항공기까지 수평 이동시키는 자주식 차량이다. 터그카(토잉 카·트랙터): 돌리를 연결해 이동한다. 돌리: 자체 구동력이 없는 이동식 받침대이며 사방에 스토퍼가 있다.","src":"이론"},{"t":"셀프 프로펠드 컨베이어: 수화물·소형화물을 낱개로 탑재·하역하는 장비(Bulk Cargo Loader). 하이 로더: ULD를 대형기 화물실 높이까지 들어 올려 탑재·하역하며 Lower Deck와 Main Deck 하이로더가 있다.","src":"이론"},{"t":"살화물 탑재방식은 단시간에 집중적으로 작업해야 하는 화물 탑재에 적합하다. 트랙터와 카고 카트가 주로 쓰인다.","src":"기출 2020-7"},{"t":"파렛트 탑재방식은 기본적인 항공화물 취급 방법이다. 파렛트화된 화물에 이글루를 씌워 탑재한다. 컨테이너 탑재방식은 항공기 내부구조에 맞는 컨테이너로 탑재한다.","src":"기출 2020-7"}]}],"함정":[{"x":"컨투어게이지(Contour Gauge): 파렛트에 적재가 끝난 후 적재된 파렛트의 무게를 계량하기 위하여 트레일러에 조립시켜 놓은 장치이다.","o":"컨투어게이지(Contour Gauge): 적재한 화물의 외곽 윤곽이 항공기 적재공간에 맞는지 재는 장치이다. 무게 계량 장치가 아니다.","src":"기출 2021-19 / 보충(추정)"},{"x":"스트래들 캐리어(Straddle Carrier): 부두의 안벽에 설치되어 선박에 컨테이너를 선적하거나 하역하는데 사용된다.","o":"스트래들 캐리어: 컨테이너를 양다리 사이에 끼워 야드에서 운반·적재한다. 안벽에서 선적·하역하는 장비는 컨테이너크레인(안벽크레인)이다.","src":"기출 2021-38 / 기출 2021-12, 2023-29 / 보충"},{"x":"스트래들(Straddle)형은 전방이 아닌 차체의 측면에 포크와 마스트가 장착된 지 게차이다.","o":"스트래들형 지게차: 차체 전방의 아웃리거 사이에 포크를 두어 안정성을 높인다. 측면에 포크와 마스트가 있는 것은 사이드포크형이다.","src":"기출 2022-30 / 기출 2022-30, 2024-30"},{"x":"디젤엔진식은 유해 배기가스와 소음이 적어 실내작업에 적합한 환경친화형 장비 이다.","o":"디젤엔진식은 배기가스와 소음이 커서 실내작업에는 전동식이 적합하다.","src":"기출 2022-30 / 보충"},{"x":"워키(Walkie)형은 스프레더를 장착하고 항만 컨테이너 야드 등 주로 넓은 공간 에서 사용된다.","o":"워키(Walkie)형은 작업자가 걸어서 조작하는 소형 지게차이다. 스프레더로 컨테이너를 다루는 것은 컨테이너용 장비이다.","src":"기출 2022-30 / 보충"},{"x":"사이드 포크형은 차체전방에 아웃리거를 설치하고 그 사이에 포크를 위치시켜 안정성을 향상시킨 지게차이다.","o":"사이드포크형: 차체 측면에 포크와 마스트가 장착된 지게차이다. 전방 아웃리거 사이에 포크를 두는 것은 스트래들형이다.","src":"기출 2022-30 / 기출 2024-30, 2022-30"},{"x":"트롤리 컨베이어는 로울러 또는 휠을 배열하여 화물을 운반하는 컨베이어이다.","o":"로울러 또는 휠을 배열해 화물을 운반하는 것은 롤러·휠 컨베이어이다. 트롤리 컨베이어는 천장 레일에 매단 트롤리로 이송한다.","src":"기출 2024-30 / 보충"},{"x":"항공컨테이너는 해상컨테이너와 호환이 가능하다.","o":"항공컨테이너는 해상컨테이너와 호환되지 않는다.","src":"기출 2026-36 / 기출 2026-36"},{"x":"하역물품의 원산지(하역기기 선정 기준으로)","o":"원산지는 선정 기준이 아니다.","src":"기출 2021-33"},{"x":"취급화물의 원산지와 목적지(사내하역 하역기기 선정 기준)","o":"선정 기준이 아니다.","src":"기출 2025-29"},{"x":"Freight Liner 방식: 트럭이 화물열차에 직각으로 후진하여 무개화차에 컨테이너를 바로 실어 운송","o":"그 설명은 플렉시밴 방식이다.","src":"기출 2023-32 / 보충"},{"x":"탑 핸들러: 본선과 터미널 간 액체화물 이송 시 연결되는 육상 터미널 측 장비(2023-29)","o":"그 설명은 로딩 암이다. 탑 핸들러는 공 컨테이너 적치 장비이다.","src":"기출 2023-29 / 보충"},{"x":"로딩 암: 부두에서 본선으로 석탄·광석 벌크화물을 선적하는 장비(2023-29)","o":"벌크 선적 장비가 아니다. 로딩 암은 액체화물 이송 연결 장비이다.","src":"기출 2023-29 / 보충"},{"x":"돌리: 해상 컨테이너를 적재하거나 이송·반출하는 장비(2023-29)","o":"그 설명은 트랜스퍼 크레인이다. 돌리는 파렛트 운반 차대이다.","src":"기출 2021-19, 2021-38"},{"x":"호퍼(Hopper)가 컨테이너터미널 하역기기이다(2022-37).","o":"호퍼는 컨테이너터미널 장비가 아니다.","src":"기출 2022-37"},{"x":"그라브 버켓이 컨테이너터미널 장비이다(2026-38).","o":"컨테이너터미널 장비가 아니다.","src":"기출 2026-38"},{"x":"리치스태커·탑 핸들러·스트래들 캐리어·로딩 암이 항공하역 장비이다.","o":"항공하역 장비가 아니다.","src":"기출 2024-39, 2025-35"},{"x":"살화물 탑재방식은 개별 화물을 항공전용 컨테이너에 넣은 후 언로더(Unloader)를 이용하여 탑재하는 방식이다.","o":"살화물(벌크) 탑재는 컨테이너나 파렛트 없이 낱개로 탑재하는 방식이다. 개별 화물을 컨테이너에 넣어 탑재하는 것은 컨테이너 탑재방식이다.","src":"기출 2020-7"},{"x":"언로더(Unloader)는 천정에 설치된 에이치빔(H-beam)의 밑 플랜지에 전동 체인 블록 등을 매단 구조이며 소규모 하역작업에 널리 이용되고 있다.","o":"언로더는 철광석·석탄 같은 벌크 화물을 양륙하는 전용 크레인이다.","src":"기출 2020-8"},{"x":"TOFC 방식은 COFC 방식에 비하여 총중량이 적으며, 철도터미널에서의 소요공간이 적어 널리 사용되고 있다.","o":"총중량이 적고 소요공간이 적은 쪽은 COFC이다. TOFC는 트레일러를 같이 싣는 방식이라 COFC보다 무겁고 공간이 더 든다.","src":"기출 2020-32"},{"x":"데릭(Derrick)은 항공하역에서 사용되는 장비이다.","o":"데릭은 항만하역 크레인이다. 항공하역 장비는 트랜스포터·터그카·돌리·이글루 등이다.","src":"이론"},{"x":"리치포크(Reach Fork)형은 크레인 끝에 스프레더가 장착되어 주로 파렛트를 하역하는 데 사용된다.","o":"크레인 끝에 스프레더를 단 것은 리치 스태커이다. 리치포크형은 마스트 또는 포크가 전후로 이동하는 입승식 지게차이다.","src":"이론"},{"x":"슬랫 컨베이어, 토우 컨베이어, 트롤리 컨베이어, 에이프런 컨베이어, 공기 컨베이어는 모두 체인 컨베이어이다.","o":"공기 컨베이어는 유체 컨베이어이다. 슬랫·토우·트롤리·에이프런이 체인 컨베이어이다.","src":"이론"}]},"#16":{"묶음":[{"머리":"컨테이너터미널 시설 전체","줄":[{"t":"선석(Berth): 컨테이너 선박이 접안하는 시설.","src":"기출 2021-18"},{"t":"에이프런(Apron): 안벽을 따라 폭 약 30~50m로 포장된 공간. 야드트럭이 하역작업을 하고 컨테이너크레인이 주행한다.","src":"기출 2021-18, 2024-38"},{"t":"마샬링 야드(Marshalling Yard): 선적·양하할 컨테이너를 임시 보관하는 공간. 대부분 에이프런에 인접한다.","src":"기출 2024-6"},{"t":"컨테이너 야드(CY): 컨테이너를 인도·인수·장치하는 장소.","src":"기출 2025-6 / 보충"},{"t":"CFS: LCL 화물의 적입(Stuffing)과 FCL 화물의 분리(Stripping) 작업을 하는 시설.","src":"기출 2021-18, 2025-6"},{"t":"컨트롤센터(Control Center): 본선 하역작업과 야드의 컨테이너 배치를 계획·통제·감독한다.","src":"기출 2021-18"},{"t":"게이트(Gate): 컨테이너터미널의 화물 출입통로.","src":"기출 2024-6"},{"t":"메인트넌스 숍(Maintenance Shop): 컨테이너 자체의 검사·보수·사용 전후 청소를 한다.","src":"기출 2024-6"},{"t":"위생검사소: 부패성 화물·음식물 같은 위생 위험 화물을 검사한다.","src":"기출 2024-6"},{"t":"잔교(Pier): 선박이 접안하는 구조물.","src":"기출 2024-38 / 보충"}]},{"머리":"안벽크레인 용어","줄":[{"t":"아웃리치(Outreach): 스프레더가 바다 측으로 최대로 나갔을 때 바다 측 레일중심에서 스프레더 중심까지의 거리.","src":"기출 2026-30"},{"t":"백리치(Backreach): 스프레더가 육지 측으로 최대로 나갔을 때 육지 측 레일중심에서 스프레더 중심까지의 거리.","src":"기출 2026-30"},{"t":"스프레더(Spreader): 컨테이너 크기에 맞추어 싱글·트윈 컨테이너를 하역하는 장치.","src":"기출 2026-30"},{"t":"계류장치: 크레인을 쓰지 않을 때 정지용 핀과 타이다운을 설치해 강풍·태풍으로부터 보호한다.","src":"기출 2026-30"}]},{"머리":"컨테이너터미널 운영방식·장비","줄":[{"t":"새시(Chassis) 방식: 컨테이너를 새시 위에 적재한 상태로 필요할 때 이송한다.","src":"기출 2021-12"},{"t":"스트래들 캐리어 방식: 컨테이너를 양다리 사이에 끼워 자유롭게 운반한다.","src":"기출 2021-12"},{"t":"트랜스테이너 방식: 트랜스퍼 크레인으로 컨테이너를 이동한다. 자동화가 어렵다는 설명은 틀렸다.","src":"기출 2021-12 / 보충(추정)"},{"t":"컨테이너터미널 장비: 리치 스태커, 야드 트랙터, 트랜스퍼 크레인, 탑 핸들러, 컨테이너 섀시, RMGC.","src":"기출 2022-37, 2026-38"}]},{"머리":"컨테이너 종류","줄":[{"t":"표준 컨테이너(드라이 컨테이너): 온도조절이 필요 없는 밀폐형.","src":"기출 2026-27"},{"t":"냉동 컨테이너(Reefer): 냉동·냉장 화물 수송용으로 냉동장치를 부착한다.","src":"기출 2026-27"},{"t":"오픈탑 컨테이너: 천장이 개방되는 컨테이너. 경량화물이 적합하다는 설명은 오답.","src":"기출 2026-27 / 보충(추정)"},{"t":"탱크 컨테이너: 액체 화물용. 지붕 맨홀로 넣고 밑면 호퍼로 배출하는 것은 벌크 컨테이너 설명.","src":"기출 2026-27 / 보충(추정)"}]},{"머리":"항만하역 작업방식","줄":[{"t":"LO-LO(Lift on-Lift off): 크레인으로 화물을 수직으로 들어 올려 싣고 내린다.","src":"기출 2023-31 / 보충"},{"t":"RO-RO(Roll on-Roll off): 선측·선미의 경사판을 거쳐 견인차로 수평 적재·양륙한다. 페리 선박에서 전통적으로 쓴다.","src":"기출 2023-31"},{"t":"RO-RO 방식으로 하역하는 선박: 자동차전용선, 카페리선(7종 중 2개).","src":"기출 2026-37"},{"t":"FO-FO(Float on-Float off), LASH(Lighter Aboard Ship)도 항만하역 방식이다.","src":"기출 2023-31"}]},{"머리":"항만운송사업법","줄":[{"t":"항만운송: 타인의 수요에 응하여 하는 행위로서 법 제2조 제1항 각 호에 해당하는 것.","src":"항만운송사업법 제2조"},{"t":"항만하역사업의 핵심 행위: 선박으로 운송된 화물을 화주 또는 선박운항업자의 위탁을 받아 항만에서 선박으로부터 인수하거나 화주에게 인도하는 행위.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"t":"검수: 선적화물을 싣거나 내릴 때 화물의 개수를 계산하거나 인도·인수를 증명하는 일.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"t":"감정: 선적화물·선박(부선 포함)에 관한 증명·조사·감정을 하는 일.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"t":"검량: 선적화물을 싣거나 내릴 때 화물의 용적 또는 중량을 계산하거나 증명하는 일.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"t":"검수·감정·검량은 항만하역사업이 아니다.","src":"항만운송사업법 제2조 / 기출 2022-38"}]},{"머리":"컨테이너터미널 시설 보충","줄":[{"t":"선석(Berth): 컨테이너선이 접안해 컨테이너를 선적·양하하려고 설치한 구조물이다. 바다와 맞닿은 안벽(Quay wall)을 말한다.","src":"이론"},{"t":"에이프런(Apron): 안벽에 접한 야드 부분에 일정한 폭으로 나란히 뻗은 공간이다. 컨테이너를 임시로 하치하거나 크레인이 통과 주행하도록 레일을 설치한 곳이다.","src":"이론"},{"t":"CY: 철도·해상운송과 관련해 컨테이너를 효율적으로 배치·회수·보관하는 시설이다. 부두 안의 CY는 On-Dock CY, 혼잡할 때 부두 외곽의 외부 컨테이너터미널을 쓰는 것이 Off-Dock CY(ODCY)이다.","src":"이론"},{"t":"CFS: 컨테이너화물처리장이다. LCL 화물 처리의 기본 시설이며 소량 화물(LCL)을 인수·인도·보관하고 컨테이너에 적입·적출한다.","src":"이론"}]},{"머리":"컨테이너터미널 하역기기·하역방식","줄":[{"t":"리치 스태커(Reach Stacker): 장비 회전 없이 붐에 달린 스프레더만 회전해 컨테이너를 이적·하역한다. 항만 CY에서 공컨테이너 야적, 차량 적재, 단거리 이송에 쓴다.","src":"이론"},{"t":"탑 핸들러(Top Handler): 항만 CY에서 공컨테이너 야적·차량 적재·단거리 이송에 쓴다. 마스트에 스프레더를 장착한다(리치 스태커는 붐에 장착).","src":"이론"},{"t":"트랜스퍼 크레인: CY에서 컨테이너를 야드 샤시에서 내려 장치하거나 장치된 컨테이너를 샤시에 싣는다. 타이어형은 RTGC(Rubber Tired Gantry Crane), 레일 위를 이동하는 형은 RMGC(Rail Mounted Gantry Crane)이다.","src":"이론"},{"t":"야드 트랙터(Yard Tractor): 부두에 내려진 컨테이너를 터미널로, 대기 중인 수출용 컨테이너를 부두로 이동시킨다.","src":"이론"},{"t":"새시 방식(Chassis System): 로드트랙터와 로드새시를 조합해 컨테이너를 직접 적하·양하한다. 크레인으로 선박에 직접 상·하차하며 보조 하역기기가 필요 없다.","src":"이론"},{"t":"새시 방식 단점: 컨테이너를 1단밖에 장치할 수 없어 넓은 야드 면적과 많은 새시·트레일러가 필요하다.","src":"이론"},{"t":"스트래들 캐리어 방식: 컨테이너선에서 크레인으로 에이프런에 직접 내리고 스트래들 캐리어로 운반한다. 2~3단 적재로 토지 효율이 높고 작업량 탄력성이 있다. 장비와 컨테이너의 파손율이 높다.","src":"이론"},{"t":"트랜스테이너 방식: 야드새시에 탑재한 컨테이너를 마샬링 야드로 이동시켜 장치한다. 일정한 방향으로 이동하므로 전산화에 의한 자동화가 가능하다. 우리나라에서 주로 쓴다. 물량이 늘면 대기시간이 길어진다.","src":"이론"},{"t":"방식별 비교(야드면적/자본투자/양륙시간/장비 유지비/자동화 가능성): 새시 대·대·단·소·저, 스트래들 캐리어 중·중·중·대·중, 트랜스테이너 소·소·장·소·고.","src":"이론"}]},{"머리":"계산: TGS와 컨테이너 적재방식","줄":[{"t":"TGS(Twenty-foot Ground Slot): 1TEU를 평면으로 적재할 수 있는 단위이다. 터미널 적정처리능력은 소요 TGS를 산정한 뒤 이를 수용할 장치장 면적을 산출한다.","src":"이론"},{"t":"소요 TGS = 연간 처리대상 물동량 × 평균장치일수 × 피크계수 × 분리계수 ÷ (평균장치단수 × 연간영업일수).","src":"이론"},{"t":"예: 100,000TEU, 장치 10일, 피크·분리계수 각 1.5, 평균 4단, 연 365일 → 2,250,000÷1,460 = 1,541.","src":"이론"},{"t":"LOLO: 본선 또는 육상의 갠트리크레인으로 컨테이너를 본선에 수직으로 하역한다. RORO: 선미·선측의 경사판(ramp)을 거쳐 견인차로 수평 적재·양륙한다. FOFO: 크레인으로 컨테이너가 적재된 부선을 하역한다.","src":"이론"}]},{"머리":"컨테이너 개념·규격·종류","줄":[{"t":"컨테이너: 20ft·40ft·45ft 등 해운용뿐 아니라 표준규격으로 화물을 적재할 수 있는 용기이다. 컨테이너를 쓰는 화물운송방식으로 바꾸는 것이 컨테이너화(containerization)이다.","src":"이론"},{"t":"컨테이너 조건(ISO): 내구성과 반복사용에 맞는 강도, 도중에 다시 채우지 않고 수송 가능, 환적 때 쉽게 하역할 장치, 넣고 꺼내기 쉬운 설계, 내용적 1㎥ 이상.","src":"이론"},{"t":"ISO Series 1 규격: 길이 40ft, 높이 8ft, 폭 8ft, 최대 총중량 30t. 표준 크기는 20ft·40ft 해운용 컨테이너이다.","src":"이론"},{"t":"TEU(Twenty-foot Equivalent Unit): 컨테이너 물동량 산출의 표준 단위이며 컨테이너선 적재능력 표시 기준이다.","src":"이론"},{"t":"플랫랙 컨테이너(Flat rack): 목재·기계류 같은 중량 화물용이다. 지붕과 벽을 제거하고 기둥과 버팀대만 두어 전후좌우에서 하역한다.","src":"이론"},{"t":"오픈톱 컨테이너: 중량화물·장척화물 운송에 적합하게 천장이 개방된다. 통기·환기 컨테이너(Ventilated): 통풍이 필요한 수분성 화물·생피 등을 수송한다.","src":"이론"},{"t":"드라이 벌크 컨테이너(솔리드 벌크): 사료·곡물·분립체 등 벌크화물을 수송한다. 가축용 컨테이너(Pen, Live stock): 통풍이 잘되도록 옆면과 전후 양면에 창문이 있다.","src":"이론"},{"t":"서멀 컨테이너(Thermal): 냉동·냉장이 필요한 화물용이다. 단열 컨테이너(Insulated): 냉각·가열장치 없이 바깥쪽을 모두 단열재로 덮고 통풍장치를 부착한다.","src":"이론"},{"t":"플랫폼 컨테이너: 기둥이나 벽이 없고 모서리 쇠와 바닥만으로 구성된다. 중량물이나 부피가 큰 화물을 운송한다.","src":"이론"},{"t":"사이드오픈 컨테이너: 옆면이 개방된다. 행거 컨테이너(Hanger): 가죽·모피 같은 의류를 운송한다.","src":"이론"},{"t":"컨테이너 이용 장점: 화물 안전성이 높아 보험료 절약, 환적 하역 단순·신속, 포장비·창고보관비 절약, 복합·일관운송으로 운송비 절감, 운반 기계화로 인건비 절약.","src":"이론"},{"t":"컨테이너 이용 단점: 운반설비에 대규모 시설·장비 자금이 필요, 적입 가능한 화물의 크기·종류 제한, 전문 지식·기술 필요, 하역시설이 없는 항구는 하역 시간이 길어질 수 있다.","src":"이론"}]},{"머리":"크레인 용어 보충·항만하역 정의","줄":[{"t":"호이스트(Hoist): 스프레더가 최대로 올라갔을 때 지상에서 스프레더 컨테이너 코너 구멍 접촉면까지의 거리를 말한다.","src":"기출 2020-30"},{"t":"헤드블록(Head Block): 스프레더를 달아매는 리프팅 빔이다. 아래 면에는 스프레더 소켓을 잡는 수동식 연결핀이 있고 윗면은 스프레더 급전용 케이블이 연결된다.","src":"기출 2020-30"},{"t":"항만하역: 항만에서 화물을 선박에 적·양하하거나 보관·장치·운반하는 등 화물유통을 담당하는 사업이다. 항만운송사업법 제2조에 규정한다.","src":"이론"},{"t":"항만하역사업의 행위: 선박으로 운송된 화물을 화물주·선박운항업자 위탁으로 인수하거나 인도, 선박에 싣거나 내리는 일, 부선·범선 이용 운송, 창고·하역장에 들여놓거나 내가는 행위, 하역장·부선에서의 싣기·내리기·보관, 목재의 뗏목 편성 운송과 수면 목재저장소 반입·반출.","src":"이론"}]}],"함정":[{"x":"마샬링야드(Marshalling Yard): 컨테이너의 자체검사, 보수, 사용 전후 청소 등을 수행하는 공간이다.","o":"마샬링야드: 선적·양하할 컨테이너를 임시로 모아 두는 공간이다. 컨테이너 자체검사·보수·청소는 메인트넌스 숍의 일이다.","src":"기출 2021-18 / 기출 2024-6"},{"x":"ILS(Instrument Landing System)은 선박이 안전하게 접안할 수 있도록 유도하 는 시설로 평소에는 항만 하역장비를 보관하기도 한다.","o":"ILS는 항공기 계기착륙장치이다. 컨테이너터미널 시설이 아니다.","src":"기출 2024-6 / 보충(추정)"},{"x":"호이스트(Hoist)는 안벽크레인에 부착된 릴(Reel)로서 육상의 변전소에서 공급되는 전선을 감는 장치를 말한다.","o":"안벽크레인에 부착되어 전선을 감는 릴은 케이블 릴이다. 호이스트는 컨테이너를 들어 올리는 권상장치이다.","src":"기출 2026-30 / 보충(추정)"},{"x":"트랜스테이너 방식은 자동화가 어렵다(2021-12 ㄴ).","o":"트랜스퍼 크레인 방식은 자동화가 용이하다.","src":"기출 2021-12 / 보충(추정)"},{"x":"선적화물을 싣거나 내릴 때 화물의 개수를 계산하는 행위(항만하역사업으로)","o":"검수에 해당한다. 항만하역사업이 아니다.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"x":"선적화물 및 선박에 관련된 증명·조사·감정을 하는 행위(항만하역사업으로)","o":"감정에 해당한다. 항만하역사업이 아니다.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"x":"선적화물의 용적 또는 중량을 계산·증명하는 행위(항만하역사업으로)","o":"검량에 해당한다. 항만하역사업이 아니다.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"x":"오픈탑 컨테이너는 경량화물 수송에 적합하다(2026-27 ㄷ).","o":"경량화물용으로 보는 설명은 오답이다.","src":"기출 2026-27 / 보충(추정)"},{"x":"탱크 컨테이너: 지붕 맨홀로 넣고 밑면을 호퍼형으로 만들어 배출(2026-27 ㄹ).","o":"그 설명은 벌크 컨테이너이다. 탱크 컨테이너는 액체용이다.","src":"기출 2026-27 / 보충(추정)"},{"x":"타이다운(Tie-down)이란 크레인이 넘어졌을 때의 육지 측 레일의 중심에서 붐 상단까지의 거리를 말한다.","o":"타이다운은 크레인을 쓰지 않을 때 정지용 핀과 함께 설치해 강풍·태풍으로부터 크레인을 보호하는 계류장치이다.","src":"기출 2020-30"}]},"#17":{"묶음":[{"머리":"ULS의 의의·효과","줄":[{"t":"유닛로드시스템(ULS): 화물을 파렛트나 컨테이너 1개분으로 일정 중량·용적으로 단위화해 이 단위를 유지하며 운송·보관·하역하는 방식.","src":"기출 2021-37, 2022-36, 2024-33"},{"t":"선결과제: 운송 표준화, 장비 표준화, 하역 기계화.","src":"기출 2021-37, 2022-34"},{"t":"효과: 하역 기계화 촉진, 하역능력 향상으로 운송수단 회전율 상승, 보관효율 향상, 재고파악 용이, 파손·분실 감소, 포장 간소화와 포장비 절감, 인건비 절감.","src":"기출 2021-37, 2022-36, 2023-39, 2024-33"},{"t":"운반활성지수가 높아진다(감소가 아니다).","src":"기출 2024-37"},{"t":"단점: 하역기기 등에 고정투자비용이 들고 대규모 자본투자가 필요하다. 빈 파렛트·컨테이너 회수가 원활하지 않으면 운송·하역이 지연된다.","src":"기출 2023-39, 2024-33"},{"t":"일관파렛트화의 경제적 효과: 포장 간소화로 포장비 절감, 작업능률 향상, 화물 파손 감소, 운임·부대비용 절감, 화물 도난 감소, 물품검수 용이. 제품의 과잉생산 방지는 효과가 아니다.","src":"기출 2022-33, 2024-37"},{"t":"물류모듈화에서 파렛트화된 화물과 정합성을 맞출 대상: 랙, 파렛트 트럭, 컨테이너, 운반승강기. 해상용 갠트리 크레인은 해당하지 않는다.","src":"기출 2024-34"},{"t":"파렛트 풀 시스템 효과: 물류합리화·물류비 절감, 비수기 불필요한 파렛트 비용 절감, 파렛트 규격 표준화 필요, 지역적·계절적 수요 변동 대응. 회수관리를 일원화할 수 있다.","src":"기출 2021-32"}]},{"머리":"파렛트 표준규격","줄":[{"t":"한국 1,100×1,100mm, 일본 1,100×1,100mm, 영국 800×1,200mm(출제 정답), 미국 1,219×1,016mm.","src":"기출 2022-32"}]},{"머리":"파렛트 적재방식","줄":[{"t":"블록쌓기: 각 단의 모양과 방향을 모두 같게 일렬로 쌓는다. 작업은 쉽지만 무너질 위험이 있다.","src":"기출 2021-30, 2023-36"},{"t":"교호열쌓기: 같은 단 안에서는 같은 방향으로 나란히 놓고, 단마다 방향을 직각(90도)으로 바꾸거나 교대로 겹쳐 쌓는다.","src":"기출 2021-30"},{"t":"벽돌쌓기: 벽돌을 쌓듯이 가로·세로를 조합해 1단을 쌓고, 홀수층과 짝수층을 180도 회전시켜 쌓는다.","src":"기출 2023-36"},{"t":"핀휠(Pinwheel)쌓기: 중앙에 공간을 두고 풍차형으로 쌓는다.","src":"기출 2023-36"},{"t":"스플릿(Split)쌓기도 적재방식이다.","src":"기출 2021-30"}]},{"머리":"파렛트 종류 전체","줄":[{"t":"롤 파렛트(Roll Pallet): 바닥면에 바퀴가 달려 밀어서 움직인다.","src":"기출 2023-40, 2024-32, 2026-32"},{"t":"시트 파렛트(Sheet Pallet): 푸시풀(push-pull) 장치를 부착한 장비로 하역하는 시트 모양 1회용 파렛트.","src":"기출 2024-32, 2026-32"},{"t":"사일로 파렛트(Silo Pallet): 분말체의 보관·운송에 쓴다. 밀폐 커버와 하부 개폐장치가 있다.","src":"기출 2026-32, 2025-33"},{"t":"탱크 파렛트(Tank Pallet): 액체 취급에 쓴다. 밀폐 커버와 개폐 장치가 있다.","src":"기출 2025-33 / 보충"},{"t":"기둥(Post) 파렛트: 상단에 기둥을 설치해 기둥을 접거나 연결해 쓴다.","src":"기출 2026-32"},{"t":"스키드 파렛트: 핸드 리프트 등으로 하역하는 파렛트.","src":"기출 2025-33 / 보충(추정)"},{"t":"롤박스 파렛트: 상부가 박스이고 받침대 밑면에 바퀴가 달려 배송용으로 많이 쓴다.","src":"기출 2025-33"},{"t":"항공 파렛트: 화물 탑재 후 항공기 화물적재공간을 고려해 망(net)이나 띠(strap)로 묶는다.","src":"기출 2024-32"},{"t":"항공 단위탑재용기(ULD): 지상조업시간 단축으로 항공기 가동률 향상, 악천후·도난·파손 방지, 파렛트류·컨테이너류로 구분, IATA 검증을 거친 것도 있다. 모든 기종에 호환되지 않는다.","src":"기출 2025-37"}]},{"머리":"파렛트 풀 시스템 운영방식 전체","줄":[{"t":"교환(즉시교환)방식: 같은 수량의 파렛트를 동시에 교환한다. 동일 규격 파렛트를 미리 보유해야 하고 규격 통일이 선행되어야 한다. 유럽 국영철도역의 파렛트 적재 운송이 예다.","src":"기출 2021-35, 2022-35, 2024-35, 2026-34"},{"t":"교환방식은 동일 규격의 예비 파렛트 확보를 위한 추가비용이 발생한다.","src":"기출 2023-37"},{"t":"대차결제방식: 현장에서 즉시 교환하지 않고 일정 시간 내에 같은 수량의 파렛트를 반환한다.","src":"기출 2021-35"},{"t":"리스·렌탈방식: 개별 기업이 파렛트를 보유하지 않고 파렛트 풀 회사에서 일정 기간 임대한다. 이용자가 교환용 동일 수량을 준비할 필요가 없다. 운영 파렛트 수를 최소화하고 품질유지·보수가 쉽고 수급파동에 탄력적이다.","src":"기출 2021-35, 2022-35, 2023-37, 2025-32, 2026-34"},{"t":"교환·리스병용방식: 교환방식의 단점을 보완하려고 개발됐다.","src":"기출 2023-37, 2026-34 / 보충"}]},{"머리":"ULS의 의의·효과 보충","줄":[{"t":"유닛로드(Unit Load): 수송·보관·하역 등 물류활동을 합리적으로 처리하려고 복수의 물품·포장화물을 기계·기구로 취급하기에 알맞게 하나의 단위로 정리한 화물이다.","src":"이론"},{"t":"ULS 전제조건(표준화): 수송장비 적재함규격, 포장단위치수, 파렛트, 운반하역장비, 창고보관설비, 거래단위 표준화.","src":"이론"},{"t":"ULS 구축 때 고려사항: 적재화물의 형태·무게, 적재화물의 적재형태, 유닛로드의 운송수단, 하역장비의 종류와 특성.","src":"이론"},{"t":"ULS 구축으로 일관파렛트화, 파렛트 풀 시스템(PPS) 구축, 물류공동화가 가능하다. 고객서비스 향상과 물류비 절감을 이룬다.","src":"이론"},{"t":"ULS 장점: 취급단위화로 하역효율 상승, 하역 기계화와 운송·보관 일관 합리화, 하역시간 단축·인건비 절감, 포장 간소화로 포장비 절감, 화물파손 방지와 운송수단 회전율 향상, 컨테이너선으로 대량운송 가능.","src":"이론"},{"t":"일관파렛트화(Palletization): 화물이동 출발지점부터 최종도착지점까지 파렛트에 적재한 상태로 운반·하역·수송·보관하는 것이다. 송하인에서 수하인까지 같은 파렛트를 쓴다.","src":"이론"},{"t":"일관파렛트화 효과: 작업능률 향상으로 인력 절감, 작업 표준화·기계화 촉진으로 하역시간 절감, 제한된 공간 최대 이용, 포장 간소화로 포장비·운임 절감, 포장 해체가 없어 화물파손 최소화.","src":"이론"},{"t":"유닛로드와 관련 있는 것: 일관파렛트화, 프레이트 라이너, 컨테이너화, 협동일관운송(Intermodal). 호퍼는 관련 없다.","src":"기출 2020-17"},{"t":"ULS 효과로 하역의 기계화, 화물 파손 방지, 신속한 적재, 운송수단 회전율 향상이 있다. 경제적 재고량 유지와는 관련 없다.","src":"기출 2020-21"},{"t":"파렛트·유닛로드 효과: 하역작업의 혼잡 감소, 창고 물품 운반관리 용이, 기계화가 쉬워 하역시간 단축, 파렛트에 맞는 운송수단 사용으로 파손·손실 감소.","src":"기출 2020-22"},{"t":"물류모듈: 물류합리화와 표준화를 위해 기준척도와 단위구성 요소를 수치적으로 연계시킨 것이다. 물류모듈화는 시설·장비의 규격·치수가 일정한 배수나 분할관계로 집합된 것이다. 운송 모듈화 대상은 트럭·화차·컨테이너 선박이다.","src":"이론"}]},{"머리":"파렛트 개요·규격","줄":[{"t":"파렛트(KS): 하역운반기기로 물품 취급을 편리하게 하려고 물품을 싣는 면을 가진 것이다.","src":"이론"},{"t":"파렛트화 선행조건: 파렛트 치수의 표준화와 설비기기 개량·개발, 운임 요금체계 개선과 비용부담 명확화, 화물 무너짐 방지책, 파렛트 운용관리시스템 확립.","src":"이론"},{"t":"파렛트 도입효과: 인건비 절감과 노동조건 향상, 하역 단순화로 수송효율 향상, 하역인원·시간 단축, 화물 훼손 감소로 상품보호.","src":"이론"},{"t":"자사파렛트 장점: 필요할 때 편리하게 사용, 자체 파렛트 풀 시스템 도입 용이, 자사 필요규격을 임의로 선택. 단점: 공파렛트 회수가 곤란하고 비용이 많이 듦, 성수기·비수기 양적 조정 곤란, 규격 파렛트 보급 곤란.","src":"이론"},{"t":"임대파렛트 장점: 공파렛트 회수 불필요, 성수기·비수기 양적 조정 가능, 표준 파렛트 도입 용이, 경비 절감. 단점: 긴급 공급 곤란, 회사 간 이동 때 회수 곤란, 모든 포장단위를 임대 파렛트에 맞춰야 함.","src":"이론"},{"t":"ISO 표준파렛트 정사각형(mm): 1,140×1,140(호주), 1,100×1,100(아시아·태평양, 한국), 1,067×1,067(42인치).","src":"이론"},{"t":"ISO 표준파렛트 직사각형(mm): 1,200×800(유럽 R189), 1,200×1,000(한국·독일·네덜란드), 1,219×1,016(48×40인치, 미국).","src":"이론"},{"t":"분할계열치수: NULS(Net Unit Load Size 1,100×1,100mm) 기준으로 T-11형 파렛트를 1/2, 1/3, 1/4 등으로 분할해 박스를 적재한다. 예: 220×220mm(1단 5×5, 100%), 366×220mm(3×5, 99.8%), 550×275mm(2×4, 100%), 550×366mm(2×3, 99.8%).","src":"이론"},{"t":"T-11형과 T-12형 모두에 적용되는 포장모듈치수: 600×500mm, 550×366mm, 500×300mm, 440×330mm.","src":"이론"},{"t":"배수계열치수: PVS(Plan View Size 1,140×1,140mm) 기준이며 최대허용공차 40mm이다. 적재적량: 8톤 트럭 12매, 11톤 트럭 16매. 20ft 컨테이너 10매(1단), 40ft 컨테이너 20매(1단).","src":"이론"}]},{"머리":"파렛트 적재방법·계산","줄":[{"t":"벽돌 적재: 같은 단에서 가로·세로를 조합해 쌓고 다음 단에서 방향을 180도 바꿔 교대로 쌓는다. 작업 효율은 높지만 무너질 염려가 있어 안정성이 낮다.","src":"이론"},{"t":"핀휠 적재: 중간에 둔 공간을 중심으로 풍차 모양으로 둘러쌓고 단 간에 방향을 교대로 바꾼다. T-11형 같은 정방형 파렛트에만 적용한다.","src":"이론"},{"t":"스플릿 적재: 벽돌 적재의 일종으로 물품 사이에 공간을 두고 쌓는다. 블록 적재: 각 단의 모양·방향이 모두 같다(일렬 적재). 안정성이 낮다.","src":"이론"},{"t":"교호열쌓기는 블록쌓기의 짝수층과 홀수층을 90도 회전시켜 교대로 쌓는 방법이다.","src":"기출 2020-35"},{"t":"스플릿쌓기는 벽돌쌓기의 변형으로, 가로·세로를 배열할 때 크기 차이로 생기는 홀수층·짝수층의 빈 공간이 서로 마주 보게 쌓는다.","src":"기출 2020-35"},{"t":"바닥면적 적재율(충진율) = 적재 수량 × 제품 바닥면적 ÷ 파렛트 면적 × 100.","src":"이론"},{"t":"예: T-11형(1,100×1,100) 파렛트에 700×400×300mm 제품을 핀휠로 적재 → 4개. 4×280,000÷1,210,000 = 92.6%.","src":"이론"},{"t":"1단 최대 적재 박스 수 = 파렛트 면적 ÷ 박스 바닥면적(정수 부분). 예: 1,210,000÷(300×200)=20.17 → 20개.","src":"이론"}]},{"머리":"파렛트 종류·파렛타이저","줄":[{"t":"재료별: 목재, 플라스틱, 알루미늄 파렛트. 용도별: Disposable(1회용), Pool(PPS용), Exchange(교환방식용), Reusable(반복사용).","src":"이론"},{"t":"기둥(Post) 파렛트: 상부에 기둥이 있고 기둥은 고정식·조립식·접철식·연결 테두리식이 있다. 롤 상자형 파렛트: 받침대 밑면에 바퀴가 달린 롤 파렛트 중 상부구조가 박스이다. 배송용으로 많이 쓴다.","src":"이론"},{"t":"스키드 파렛트: 포크리프트나 핸드리프트로 하역할 수 있게 만든 단면형 파렛트이다. 플래턴 파렛트: 평판 모양이며 항공기 탑재용이다.","src":"이론"},{"t":"시트 파렛트: 목재·플라스틱 1회용으로 가격이 싸고 가볍다. 하역하려면 Push-Pull 장치를 부착한 포크리프트가 필요하다.","src":"이론"},{"t":"파렛타이저(Palletizer): 박스·포대 등을 파렛트에 적재하는 로봇이다. 표준화 대상은 용어·기호, 안전장치 호환성, 조작방법이다.","src":"이론"},{"t":"로봇식 파렛타이저: 산업용 로봇에 머니퓰레이터를 장착한다. 작동범위가 넓어 1대로 다품종 처리가 가능하다. 기계식: 캐리지·클램프·푸셔 등 적재장치로 자동 적재한다. 고상식: 높은 위치의 적재장치에서 파렛트를 내리며 적재한다. 저상식: 파렛트를 낮은 곳에 놓고 적재장치가 오르내린다.","src":"이론"}]},{"머리":"파렛트 풀 시스템 보충","줄":[{"t":"PPS: 표준화된 파렛트를 서로 교환할 수 있게 해 여러 화주와 물류업자가 공동 이용하는 제도이다. 파렛트 회수문제를 풀려고 도입했다. 파렛트 풀 조직이 납품·회수관리·수리를 맡는다.","src":"이론"},{"t":"PPS 목적: 공파렛트 회수에 드는 시간·비용, 분실 우려, 다량 파렛트 준비 비용을 해결한다. 일관파렛트화의 문제점인 공파렛트 회수난을 해결하며, 성공하려면 파렛트 표준화가 전제되어야 한다.","src":"이론"},{"t":"PPS 장점: 친환경물류시스템 구축, 물류합리화·물류비 절감, 지역적·계절적 수요 대응, 일관파렛트화 실현과 투자비 절감, 파렛트 수량이 줄어 자본지출 감소, 물류 규격화·표준화 촉진.","src":"이론"},{"t":"PPS 단점: 자사의 필요규격을 임의로 선택해 도입하기 어렵다. 지역 간 이동 파렛트 수량이 불균형해 공파렛트를 재배치해야 한다.","src":"이론"},{"t":"교환방식 단점: 교환용 파렛트를 준비해야 한다. 품질이 떨어지거나 보수가 필요한 파렛트를 교환용으로 내놓을 수 있다. 수송기관 이용이 복잡하거나 수송기관 수가 많으면 교환이 원활하지 않다. 발화주와 착화주가 철도회사를 통해 교환한다.","src":"이론"},{"t":"리스·렌탈방식: 화주 소재지에 가까운 데포에서 파렛트를 빌리고 도착지 이용자가 가까운 데포에 반납한다. 장점은 교환용 동질·동수 파렛트를 준비할 필요가 없다는 점이다.","src":"이론"},{"t":"리스·렌탈 단점: 반환 때 렌탈료 계산 등 사무처리가 필요하고, 화주가 특정 지역에 몰리면 특정 데포에 파렛트가 쌓이며, 데포에서 화주까지 공파렛트 수송이 필요하다. 사무처리와 편재는 렌탈회사의 책임이다.","src":"이론"},{"t":"대차결제방식: 즉시교환방식의 단점을 개선하려고 고안했다. 현장에서 바로 교환하지 않고 일정 시간 내(3일)에 같은 수량의 파렛트를 해당 철도역에 반환한다.","src":"이론"},{"t":"교환·리스 병용방식: 교환방식과 리스·렌탈방식의 단점을 보완했다. 송하인·수하인·운송회사가 각각 가까운 리스회사 데포에서 렌탈하고, 빈 파렛트가 회수되는 시점에 가장 가까운 데포에 반환해 대차관계를 정리한다. 대여 파렛트와 교환 파렛트를 함께 관리해야 해 운영관리가 어려워 활성화에 실패했다.","src":"이론"},{"t":"방식별 국가: 즉시교환방식은 유럽, 리스·렌탈방식은 호주·한국, 대차결제방식은 스웨덴, 교환·리스 병용은 영국.","src":"이론"}]}],"함정":[{"x":"파렛트 회수관리의 일원화에 어려움이 있다.","o":"파렛트 풀 시스템: 파렛트 회수관리를 일원화할 수 있다.","src":"기출 2021-32 / 기출 2021-32"},{"x":"파렛트는 시랜드사가 최초로 개발한 단위적재기기이다.","o":"시랜드사가 최초로 개발한 단위적재기기는 컨테이너이다.","src":"기출 2021-37 / 보충"},{"x":"화물을 파렛트나 컨테이너를 이용하여 벌크선박으로 운송한다.","o":"유닛로드시스템은 파렛트나 컨테이너로 단위화한 화물을 기계로 취급하는 방식이다. 벌크선박 운송과는 거리가 멀다.","src":"기출 2022-36 / 기출 2022-36"},{"x":"블록쌓기는 맨 아래에서 상단까지 일렬로 쌓는 방법으로 작업효율성이 높고 무 너질 염려가 없어 안정성이 높다.","o":"블록쌓기는 맨 아래에서 맨 위까지 같은 모양·방향으로 쌓아 작업은 쉽지만 무너질 위험이 있어 안정성이 낮다.","src":"기출 2023-36 / 기출 2021-30 / 보충"},{"x":"교호열쌓기는 짝수층과 홀수층을 180도 회전시켜 쌓는 방식으로 화물의 규격이 일정하지 않아도 적용이 가능한 방식이다.","o":"짝수층과 홀수층을 180도 회전시켜 쌓는 것은 벽돌쌓기이다. 교호열쌓기는 단별로 방향을 직각(90도)으로 바꾼다.","src":"기출 2023-36 / 기출 2021-30, 2023-36"},{"x":"핀휠(Pinwheel)쌓기는 비규격화물이나 정방형 파렛트가 아닌 경우에 이용하는 방식으로 다양한 화물의 적재에 이용된다.","o":"핀휠쌓기는 중앙에 공간을 두고 풍차형으로 쌓는다.","src":"기출 2023-36 / 기출 2023-36"},{"x":"스플릿(Split)쌓기는 중앙에 공간을 두고 풍차형으로 쌓는 방식으로 적재효율이 높고 안정적인 적재방식이다.","o":"중앙에 공간을 두고 풍차형으로 쌓는 방식은 핀휠쌓기이다.","src":"기출 2023-36 / 기출 2023-36"},{"x":"하역기기 등에 관한 고정투자비용이 발생하지 않기 때문에 대규모 자본투자가 필요 없다.","o":"유닛로드시스템은 하역기기 등에 고정투자비용이 들고 대규모 자본투자가 필요하다.","src":"기출 2023-39 / 기출 2023-39"},{"x":"시트 파렛트(Sheet Pallet)는 핸드리프트 등으로 움직일 수 있도록 만들어진 상자형 파렛트이다.","o":"시트 파렛트: 푸시풀 장치를 단 장비로 하역하는 얇은 판 모양의 1회용 파렛트이다.","src":"기출 2023-40 / 기출 2024-32, 2026-32"},{"x":"스키드 파렛트(Skid Pallet)는 상부구조물이 적어도 3면의 수직측판을 가진 상자형 파렛트이다.","o":"상부구조물에 적어도 3면의 수직측판을 가진 상자형 파렛트는 박스 파렛트이다.","src":"기출 2023-40 / 보충"},{"x":"사일로 파렛트(Silo Pallet)는 파렛트 상단에 기둥이 설치된 형태로 기둥을 접거나 연결하는 방식으로 사용한다.","o":"파렛트 상단에 기둥을 설치해 접거나 연결해 쓰는 것은 기둥(포스트) 파렛트이다. 사일로 파렛트는 분말체용이다.","src":"기출 2023-40 / 기출 2026-32"},{"x":"탱크 파렛트는(Tank Pallet)는 주로 분말체의 보관과 운송에 이용하는 1회용 파렛트이다.","o":"탱크 파렛트는 액체용이다. 분말체의 보관·운송용은 사일로 파렛트이다.","src":"기출 2023-40 / 기출 2026-32, 2025-33"},{"x":"사일로(silo) 파렛트는 액체를 담는 용도로 사용되며 밀폐를 위한 뚜껑이 있다.","o":"사일로 파렛트는 분말체용이다. 액체용은 탱크 파렛트이다.","src":"기출 2024-32 / 기출 2026-32, 2025-33"},{"x":"유닛로드시스템으로 운송의 편의성이 떨어졌고, 트럭 회전율 또한 감소하였다.","o":"유닛로드시스템으로 운송 편의성이 좋아지고 트럭 회전율이 증가했다.","src":"기출 2024-33 / 기출 2021-37, 2022-36"},{"x":"1회용 파렛트로 Push-Pull 장치를 부착한 지게차로 취급된다.","o":"푸시풀 장치 지게차로 취급하는 1회용 파렛트는 시트 파렛트이다.","src":"기출 2025-33 / 기출 2024-32, 2026-32"},{"x":"주로 액체화물 취급 시 사용되고 밀폐용 커버를 가지며 상부 또는 하부에 개폐 장치가 있다.","o":"액체화물용이며 밀폐 커버와 개폐 장치가 있는 파렛트는 탱크 파렛트이다.","src":"기출 2025-33 / 기출 2026-32 / 보충"},{"x":"주로 분말화물 취급 시 사용되고 밀폐용 커버를 가지며 하부에 개폐장치가 있다.","o":"분말화물용이며 밀폐 커버와 하부 개폐장치가 있는 파렛트는 사일로 파렛트이다.","src":"기출 2025-33 / 기출 2026-32 / 보충"},{"x":"핸드 리프트로 하역할 수 있도록 만들어진 단면형 및 양면형 파렛트이다.","o":"핸드 리프트로 하역할 수 있게 만든 단면형·양면형 파렛트는 스키드/플랫 계열의 설명이다. 롤박스 파렛트는 박스 모양에 바퀴가 달린다.","src":"기출 2025-33 / 보충(추정)"},{"x":"항공기의 모든 기종에 호환사용이 가능하여 사용회전률을 증가시킬 수 있다.","o":"항공 파렛트·컨테이너는 기종마다 규격이 달라 모든 기종에 호환되지 않는다.","src":"기출 2025-37 / 기출 2026-36"},{"x":"블록쌓기는 무너질 염려가 없어 안정성이 높다.","o":"무너질 염려가 있어 안정성이 낮다.","src":"기출 2023-36 / 보충"},{"x":"일관파렛트화의 효과: 제품의 과잉생산 방지","o":"효과가 아니다.","src":"기출 2022-33"},{"x":"일관파렛트화 장점: 운반활성지수 감소","o":"운반활성지수가 높아진다.","src":"기출 2024-37"},{"x":"해상용 갠트리 크레인은 파렛트화된 화물과 정합성을 고려해야 한다(2024-34).","o":"정합성을 고려할 필요가 없는 장비이다.","src":"기출 2024-34"},{"x":"대차결제방식: 운송업체가 화물을 인도하는 시점에 동일 수의 파렛트를 즉시 인수(2023-37 ㄷ)","o":"그 설명은 즉시교환방식이다.","src":"기출 2023-37, 2026-34"},{"x":"교환·리스병용방식은 대차결제방식의 단점을 보완하기 위해 개발(2023-37 ㄹ, 2026-34 ㄷ)","o":"교환방식의 단점을 보완하기 위한 방식이다.","src":"기출 2023-37, 2026-34 / 보충"},{"x":"한국 파렛트 표준규격은 1,100×1,200mm이다(2022-32 선지 조합 오류).","o":"한국 1,100×1,100mm, 일본 1,100×1,100mm, 영국 800×1,200mm, 미국 1,219×1,016mm.","src":"기출 2022-32"},{"x":"유닛로드 시스템(ULS)의 효과: 경제적 재고량 유지","o":"ULS와 관련이 없다.","src":"기출 2020-21"},{"x":"화물의 입고작업은 복잡하지만, 출고작업은 신속하게 할 수 있다.","o":"파렛트·유닛로드는 입출고 작업 모두를 단순하게 하고 기계화로 시간을 줄인다.","src":"기출 2020-22"},{"x":"장방형 파렛트에는 블록쌓기, 벽돌쌓기 및 핀휠(Pinwheel) 쌓기 방식이 적용된다.","o":"핀휠쌓기는 T-11형 같은 정방형 파렛트에만 적용한다.","src":"기출 2020-35"},{"x":"유닛로드시스템의 선결과제에는 생산 자동화와 무인 자동화가 있다.","o":"선결과제는 운송 표준화·장비 표준화·하역 기계화이다.","src":"이론"},{"x":"교환방식 파렛트 풀 시스템은 렌탈회사 데포에서 화주까지 공파렛트를 수송해야 한다.","o":"공파렛트를 데포에서 화주까지 수송해야 하는 것은 리스·렌탈방식이다.","src":"이론"}]},"#18":{"묶음":[{"머리":"포장의 의의·기능·분류","줄":[{"t":"포장은 소비자의 관심을 유발하는 판매물류의 시작이며 물품의 가치를 높이거나 보호한다.","src":"기출 2023-33"},{"t":"포장 기능: 보호성, 표시성, 취급의 편리성, 판매촉진성. 상품 수요 예측의 정확성은 기능이 아니다.","src":"기출 2024-40"},{"t":"기능에 따라 공업포장과 상업포장으로 나눈다. 상업포장은 물품 개개의 단위포장으로 판매촉진이 목적이다.","src":"기출 2023-33 / 보충"},{"t":"겉포장: 화물 외부의 포장.","src":"기출 2023-33"}]},{"머리":"포장합리화 원칙","줄":[{"t":"대량화·대형화의 원칙: 포장의 대형화·대량화로 물류비를 절감한다.","src":"기출 2025-39, 2026-39"},{"t":"집중화·집약화의 원칙: 물량을 집중·집약해 물류비를 절감한다.","src":"기출 2021-26, 2025-39"},{"t":"사양변경의 원칙: 사양변경으로 물류비를 절감한다.","src":"기출 2025-39"},{"t":"재질변경의 원칙: 내용품 보호에 지장이 없는 범위에서 재질을 바꾼다.","src":"기출 2021-26, 2025-39, 2026-39"},{"t":"규격화·표준화의 원칙, 시스템화·단위화의 원칙.","src":"기출 2021-26, 2026-39"},{"t":"과잉포장을 배제하되 화물 보호를 심미성보다 우선한다.","src":"기출 2025-39 / 보충"},{"t":"통로대면의 원칙, 위치표시의 원칙은 보관 원칙이며 포장 원칙이 아니다.","src":"기출 2021-26, 2026-39"}]},{"머리":"주요 포장기법·결속","줄":[{"t":"방청 포장: 금속의 부식을 방지한다. 방수·방습·진공·완충 포장은 다른 목적이다.","src":"기출 2022-39"},{"t":"밴드결속: 플라스틱·나일론·금속 재질 밴드를 쓴다.","src":"기출 2022-40"},{"t":"꺽쇠 물림쇠: 주로 칸막이 상자 등에서 상자가 고정되게 한다.","src":"기출 2022-40"},{"t":"테이핑: 용기의 견고성을 유지하려고 접착테이프를 쓴다.","src":"기출 2022-40"},{"t":"대형 골판지 상자: 작은 부품 등을 꾸러미로 묶지 않고 담을 때 쓴다.","src":"기출 2022-40"},{"t":"슈링크(수축) 포장: 열수축성 플라스틱 필름을 씌우고 터널을 통과시켜 가열·수축시킨다.","src":"기출 2022-40 / 보충"}]},{"머리":"화인(Shipping Mark)","줄":[{"t":"화인은 기본화인, 정보화인, 취급주의 화인으로 구성되며 포장화물 외장에 표시한다.","src":"기출 2023-35"},{"t":"주화인(Main Mark): 타 화물과 식별을 쉽게 하는 기호. 수입업자 화인이며 일반적으로 도형 속에 머리글자를 넣는다.","src":"기출 2021-28, 2023-35, 2025-38"},{"t":"부화인(Counter Mark): 대조번호 화인. 생산자 또는 공급자의 약호를 붙여야 할 때 표기한다.","src":"기출 2023-35, 2025-38"},{"t":"항구표시(Port Mark): 선적과 양하작업이 쉽도록 도착항을 표시한다.","src":"기출 2021-28"},{"t":"품질 표시(Quality Mark): 내용물품의 품질·등급을 표시한다.","src":"기출 2023-35"},{"t":"취급주의 표시(Care Mark): 화물의 취급·운송·적재요령을 나타내는 주의표시.","src":"기출 2023-35, 2025-38"},{"t":"포장번호(Case Number)는 포장 순서·개수를 나타내는 번호 표시. 생산자 약호 표시가 아니다.","src":"기출 2021-28 / 보충(추정)"},{"t":"원산지표시(Origin Mark)는 물품의 생산국(원산지)을 표시한다. 원자재까지 모두 표시하는 것이 아니다.","src":"기출 2021-28 / 보충(추정)"},{"t":"화인에 표시할 수 있는 것: 원산지, 취급주의, 목적지, 품질, 중량 전부.","src":"기출 2026-40"}]},{"머리":"화인 표시방법","줄":[{"t":"스텐실(Stencil): 기름기가 많은 종이나 셀룰로이드판 등 시트에 문자를 파 두었다가 붓이나 스프레이로 칠한다.","src":"기출 2023-34, 2025-38"},{"t":"라벨링(Labeling): 종이·직포에 미리 인쇄해 두었다가 일정한 위치에 붙인다.","src":"기출 2023-34"},{"t":"태그(Tag): 종이·플라스틱판 등에 표시 내용을 기재한 뒤 철사나 끈으로 맨다. 의류·잡화류에 쓴다.","src":"기출 2023-34, 2025-38"}]},{"머리":"포장의 의의·기능·분류 보충","줄":[{"t":"포장(KS T 1001): 물품의 유통과정에서 그 물품의 가치와 상태를 보호하려고 적합한 재료나 용기 등으로 포장하는 방법 및 포장한 상태이다. 생산의 마지막 단계이자 물류의 시작단계이다.","src":"이론"},{"t":"적정포장(KS T 1001): 상품의 품질보존, 취급의 편의성, 판매촉진, 안전성 등 포장 본래의 기능을 만족시키는 합리적이며 공정한 포장이다.","src":"이론"},{"t":"적정포장: 수송포장에서는 유통과정의 진동·충격·압축·수분·온습도 등으로 물품의 가치·상태가 떨어지지 않게 한다. 소비자 포장에서는 과대·과잉포장, 속임포장을 바로잡고 결함포장을 없앤다.","src":"이론"},{"t":"포장은 물류과정의 시발점이며 물류비용 절감의 주요 수단이다.","src":"이론"},{"t":"포장 설계 때 고려사항: 하역성, 표시성(정보제공), 작업성(취급 편의), 경제성(판매촉진), 보호성.","src":"이론"},{"t":"포장 표준화 4원칙: 치수, 강도, 기법, 재료의 표준화.","src":"이론"},{"t":"KS 분류: 낱포장(단위포장)은 물품 개개의 포장으로 상품가치를 높이거나 개개를 보호한다. 속포장(내부포장)은 포장된 화물 내부의 포장으로 수분·습기·광열·충격을 막는다. 겉포장(외부포장)은 화물 외부의 포장이다.","src":"이론"},{"t":"공업포장: 물품의 운송·보관을 주목적으로 하며 산업포장·수송포장·물류포장이라 한다. 상업포장: 상품화 또는 판매단위의 포장으로 소매포장·소비자포장이라 하며 주로 판매촉진 기능을 한다. 상품의 파손 방지와 물류비 절감에 초점을 두는 것은 공업포장이다.","src":"이론"},{"t":"기능 목적별: 방수·방습포장(물·습기가 스며들지 못하게), 방청포장(녹 방지), 완충포장(충격으로 인한 파손 방지), 진공포장(내용물 활성을 정지시키려고 내부를 진공 밀봉), 압축포장(상품을 압축해 용적을 줄임).","src":"이론"},{"t":"가스치환포장(MAP): 진공포장의 개선책이다. 밀봉 용기에서 공기를 빼고 질소·이산화탄소 같은 불활성 가스로 치환해 변질을 막는다.","src":"이론"},{"t":"레토르트 포장: 단층 플라스틱 필름이나 금속박 재질로 고온 가열 살균을 하므로 내열성과 내구성이 필요하다.","src":"이론"},{"t":"중량물포장: 내용물 중량이 200kg을 초과하는 물품의 포장이다. 반강성포장(semi-rigid)의 재료는 골판지상자·접음상자·플라스틱 보틀이다.","src":"이론"}]},{"머리":"집합포장·포장합리화 보충","줄":[{"t":"밴드 결속(banding): 집합포장에서 가장 많이 쓰는 방법이다. 종이·플라스틱·나일론·금속 밴드를 쓰며 수평 묶음과 수직 묶음이 있다. 코너의 변형을 막으려고 코너패드를 보호재로 쓴다.","src":"이론"},{"t":"테이핑(taping): 용기 표면에 접착테이프를 붙여 집합포장한다. 용기 표면이 손상될 수 있어 주의한다.","src":"이론"},{"t":"슬리브(sleeve): 보통 필름으로 슬리브를 만들어 4면을 감싸는 방법이다.","src":"이론"},{"t":"슈링크(shrink) 포장: 수축필름의 열수축력으로 파렛트와 그 위에 적재된 포장화물을 집합포장한다.","src":"이론"},{"t":"스트레치(stretch) 포장: 스트레치 필름의 접착성을 이용한다. 슈링크 포장이 필름 한 겹인 데 비해 스트레치는 대개 3겹 정도로 한다.","src":"이론"},{"t":"틀: 물품의 수평이동을 막으려고 위·아랫부분을 틀로 고정한다. 적어도 4개 정도의 밴드를 쓴다.","src":"이론"},{"t":"대량화·대형화의 원칙: 포장화물 단위를 키워 대량수송이 가능해지고 하역 기계화로 효율이 높아져 물류비가 준다.","src":"이론"},{"t":"규격화·표준화의 원칙: 포장설계가 간소해지고 과잉포장이 배제된다. 포장재료비, 보관비, 운송비 절감과 하역효율 향상 효과가 있다.","src":"이론"},{"t":"사양변경의 원칙: 완충재 변경이나 입수수 변경 등 사양을 바꿔 비용을 줄인다. 시스템화의 원칙: 크레인·컨테이너·파렛트·보관창고가 물류활동에서 유기적으로 연결되게 한다. 단위화의 원칙: 포장화물을 단위화한다.","src":"이론"}]},{"머리":"화인 보충","줄":[{"t":"화인(Case Mark, Shipping Mark): 화물의 외부에 하는 표시이다. 주로 목적지·발송 개수·취급상 문구를 표시한다. 화물작업의 편리성과 하역 중 물품손상 예방을 위해 포장화물 외장에 확실히 표시한다.","src":"이론"},{"t":"주표시(main mark): 화인 중 가장 중요하다. 타 상품과 식별을 쉽게 하는 기호이다. 외장 면에 다이아몬드형·마름모형·타원형·정방형 도형을 그리고 그 안에 수입자(수하인) 상호의 약자를 적는다.","src":"이론"},{"t":"품질표시(quality mark): 내용품의 품질·등급을 주표시의 위쪽이나 밑에 쓴다. 목적지표시(destination mark): 도착 목적지를 표시하며 반드시 표시해야 한다.","src":"이론"},{"t":"수량표시(case mark): 두 개 이상의 수량일 때 포장에 번호를 붙여 몇 번째에 해당하는지 표시한다.","src":"이론"},{"t":"취급주의표시(Care mark): 화물의 취급·운송·적재요령을 나타내며 일반화물 취급표시와 위험화물 경고표시로 구분한다.","src":"이론"},{"t":"원산지표시(origin mark): 정상적 절차로 선적되는 모든 수출품에 관세법에 따라 원산지명을 표시한다. 기타 표시: 상품명, 내용품번호, 총중량, 용적, 수입허가번호.","src":"이론"},{"t":"카빙(carving): 금속제품에 쓰며 주물을 주입할 때 미리 화인을 해 두어 제품 완성 시 나타나게 한다.","src":"이론"},{"t":"스템핑(stamping): 고무인이나 프레스기로 찍는다. 종이상자·골판지 상자에 적용한다.","src":"이론"},{"t":"스티커(sticker): 표시내용을 기재한 것을 못으로 박거나 특정 방법으로 고정한다.","src":"이론"},{"t":"화인: 화물작업의 편리성과 하역작업 시 물품손상 예방을 위해 포장에 확실히 표시하는 것이다.","src":"기출 2020-33"},{"t":"취급주의표시는 일반화물 취급표시와 위험화물 경고표시로 구분한다. 원산지표시는 정상 절차로 선적되는 모든 수출품에 관세법에 따라 원산지명을 표시한다.","src":"기출 2020-33"},{"t":"화인 읽기: 도형 안의 약자는 주표시, 도시명은 목적지, VIA는 경유지, C/NO. 4/10은 10개 중 4번째 포장, MADE IN은 원산지 표시이다. 방사선 방호 마크는 취급주의 표시로, 방사원에서 격리하거나 방사선을 막으라는 뜻이다.","src":"이론"}]}],"함정":[{"x":"슬리브 - 열수축성 플라스틱 필름을 화물에 씌우고 터널을 통과시킬 때 가열하 여 필름을 수축시키는 방법이다.","o":"열수축성 필름을 씌우고 터널에서 가열·수축시키는 방법은 슈링크(수축) 포장이다.","src":"기출 2022-40 / 보충"},{"x":"공업포장은 물품 개개의 단위포장으로 판매촉진이 주목적이다.","o":"물품 개개의 단위포장으로 판매촉진이 주목적인 포장은 상업포장이다. 공업포장은 수송·보관 중 물품 보호가 목적이다.","src":"기출 2023-33 / 보충"},{"x":"부화인 표시(Counter Mark)는 유통업자나 수입 대행사의 약호를 표시하는 기호 이다.","o":"부화인(Counter Mark): 생산자 또는 공급자의 약호를 표시한다.","src":"기출 2023-35 / 기출 2025-38"},{"x":"레이블링(Labeling) 방법: 종이, 알루미늄 등의 판에 표시내용을 기재한 다음 철사나 끈 등으로 적절히 매는 방법이다.","o":"종이·알루미늄 판에 기재해 철사나 끈으로 매는 방법은 태그(Tag)이다. 레이블링은 미리 인쇄한 종이·직포를 붙인다.","src":"기출 2025-38 / 기출 2023-34"},{"x":"심미성우선의 원칙: 과잉포장 배제를 통해 심미성을 화물보호보다 우선한다.","o":"포장합리화는 과잉포장을 배제하되 화물 보호를 우선한다. 심미성이 화물 보호보다 우선하지 않는다.","src":"기출 2025-39 / 보충"},{"x":"상품 수요 예측의 정확성(포장의 기능으로)","o":"포장의 기능이 아니다.","src":"기출 2024-40"},{"x":"통로대면의 원칙(포장의 원칙으로)","o":"보관의 원칙이다.","src":"기출 2021-26"},{"x":"위치표시의 원칙(포장합리화의 원칙으로)","o":"보관의 원칙이다.","src":"기출 2026-39"},{"x":"포장번호(Case Number): 주화인만으로 식별이 어려울 때 생산자 또는 공급자 약자를 보조 표시(2021-28 ㄴ)","o":"그 설명은 부화인이다. 포장번호는 포장 번호를 표시한다.","src":"기출 2021-28 / 보충(추정)"},{"x":"원산지표시: 당해 물품의 원자재까지 모두 원산지를 표시(2021-28 ㄹ)","o":"물품의 원산지를 표시하는 것이다. 원자재 원산지까지 표시하지 않는다.","src":"기출 2021-28 / 보충(추정)"},{"x":"스티커(Sticker)는 주물을 주입할 때 미리 화인을 해두는 방법(2023-34 ㄱ)","o":"출제 오답(바른 설명 미확인)","src":"기출 2023-34"},{"x":"스텐실(Stencil)은 고무인이나 프레스기 등으로 찍는 방법(2023-34 ㄴ)","o":"스텐실은 파 놓은 시트 위에 붓·스프레이로 칠하는 방법이다.","src":"기출 2023-34, 2025-38"},{"x":"주화인표시(Main Mark)는 수입업자 화인으로 수입업자의 머리문자를 도형 속에 표기하지 않고, 주소, 성명을 전체 문자로서 표시하는 것을 말한다.","o":"주화인은 수입업자 화인이며 도형 속에 수입자 상호의 머리글자(약자)를 기입한다.","src":"기출 2020-33"},{"x":"중량물(heavy) 포장은 각종 제품을 유통과정의 수분과 습도로부터 지키는 포장기법이다.","o":"수분·습도를 막는 것은 방수·방습포장이다. 중량물포장은 내용물 중량이 200kg을 초과하는 물품의 포장이다.","src":"이론"},{"x":"가스치환포장은 상품의 용적을 적게 하여 부피를 줄이는 포장기법이다.","o":"용적을 줄이는 것은 압축포장이다. 가스치환포장은 공기를 빼고 불활성 가스로 치환해 변질을 막는다.","src":"이론"},{"x":"상업포장은 상품의 파손을 방지하고 물류비를 절감하는 데 초점을 둔다.","o":"파손 방지·물류비 절감에 초점을 두는 것은 공업포장이다. 상업포장은 상품화·판매단위 포장이다.","src":"이론"},{"x":"스티커(Sticker): 주물을 주입할 때 미리 화인을 해 두는 방법이다.","o":"그 설명은 카빙이다. 스티커는 표시내용을 기재한 것을 못으로 박거나 특정 방법으로 고정한다.","src":"이론"}]}};
